INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u6-C1','math',6,1,'u6',1,'겉넓이와 부피 만나기 — 직육면체의 여섯 면은 모두 직사각형이고 마주 보는 면은 합동이며, 겉면의 넓이(겉넓이, 감싸는 종이의 양)와 공간에서 차지하는 크기(부피, 담기는 양)가 서로 다른 양임을 알기',ARRAY['6수03-17']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u6-C2','math',6,1,'u6',2,'직육면체의 겉넓이 — 여섯 면의 넓이를 모두 더하거나, 마주 보는 면이 합동(3쌍)임을 이용해 서로 다른 세 면의 넓이의 합을 2배 하여 겉넓이를 구하고, 보이는 세 면만 더하면 안 됨을 알기',ARRAY['6수03-17']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u6-C3','math',6,1,'u6',3,'두 밑면 + 옆면 · 정육면체의 겉넓이 — 두 밑면의 넓이와 옆면(가로가 한 밑면의 둘레, 세로가 높이인 직사각형)의 넓이를 더해 겉넓이를 구하고, 여섯 면이 모두 합동인 정육면체의 겉넓이는 한 면의 넓이를 6배 하여 구하기',ARRAY['6수03-17']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u6-C4','math',6,1,'u6',4,'부피 비교와 1 cm³ — 크기가 같은 단위로 세어야 부피를 비교할 수 있고, 한 모서리가 1 cm인 정육면체의 부피 1 cm³(1 세제곱센티미터)를 단위로 쌓기나무의 개수를 세어 부피를 구하며, 빈틈이 생기는 것은 단위로 쓸 수 없음을 알기',ARRAY['6수03-18']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u6-C5','math',6,1,'u6',5,'직육면체와 정육면체의 부피 — 가로·세로·높이에 놓이는 1 cm³ 쌓기나무의 개수가 각 모서리의 길이와 같음을 이용해 부피 = 가로 × 세로 × 높이 = 한 밑면의 넓이 × 높이로 구하고, 정육면체는 한 모서리를 세 번 곱하여 구하기',ARRAY['6수03-19']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u6-C6','math',6,1,'u6',6,'1 m³와 1 cm³의 관계 — 한 모서리가 1 m인 정육면체의 부피 1 m³(1 세제곱미터)를 알고, 1 m = 100 cm이므로 1 m³ = 100 × 100 × 100 = 1000000 cm³임을 넓이(1 m² = 10000 cm²)와 구별하며, 큰 부피는 m³로 나타내고 단위가 다르면 같은 단위로 고쳐 비교하기',ARRAY['6수03-18']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u6-C7','math',6,1,'u6',7,'문제 해결 — 직육면체를 잘라도 조각의 부피를 모두 더하면 처음과 같아 부피는 변하지 않고, 자른 자리마다 마주 보는 새 면 두 개가 생겨 겉넓이는 늘어남을 셈으로 확인하며 문제를 해결하기',ARRAY['6수03-19']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u6-X01','math',6,'u6',ARRAY['M6-1-u6-C1','M6-1-u6-C7']::text[],'겉넓이와 부피를 헷갈린다(포장지·색칠할 넓이를 부피로, 담기는 양을 겉넓이로)','감싸면 겉넓이, 담으면 부피') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u6-X02','math',6,'u6',ARRAY['M6-1-u6-C1','M6-1-u6-C2','M6-1-u6-C4']::text[],'넓이 단위와 부피 단위를 헷갈린다(겉넓이를 cm³로, 부피를 cm²로 쓴다)','넓이는 ², 부피는 ³') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u6-X03','math',6,'u6',ARRAY['M6-1-u6-C2','M6-1-u6-C3']::text[],'겨냥도에 보이는 세 면만 더해 겉넓이라고 한다','여섯 면 모두') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u6-X04','math',6,'u6',ARRAY['M6-1-u6-C2']::text[],'서로 다른 세 면의 합을 2배 하지 않거나, 여섯 면을 다 더한 뒤 또 2배 한다','세 면 × 2 = 여섯 면') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u6-X05','math',6,'u6',ARRAY['M6-1-u6-C3']::text[],'옆면을 펼친 직사각형의 가로를 한 밑면의 한 변으로 여긴다(둘레가 아니라)','옆면의 가로 = 한 밑면의 둘레') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u6-X06','math',6,'u6',ARRAY['M6-1-u6-C3','M6-1-u6-C5']::text[],'정육면체의 겉넓이를 한 면 × 4나 한 모서리 × 6으로 구한다','한 면의 넓이 × 6') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u6-X07','math',6,'u6',ARRAY['M6-1-u6-C1','M6-1-u6-C2']::text[],'마주 보는 면이 합동이라는 것(넓이가 같은 면 3쌍)을 놓치거나 쌍의 수를 잘못 센다','마주 보는 면은 합동') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u6-X08','math',6,'u6',ARRAY['M6-1-u6-C4']::text[],'크기가 다른 쌓기나무로 센 개수를 그대로 견주어 부피를 비교한다','같은 크기 단위로 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u6-X09','math',6,'u6',ARRAY['M6-1-u6-C4']::text[],'구슬처럼 빈틈이 생기는 것도 부피의 단위로 쓸 수 있다고 여긴다','빈틈 없이 채워지나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u6-X10','math',6,'u6',ARRAY['M6-1-u6-C4','M6-1-u6-C5']::text[],'쌓기나무의 개수를 셀 때 한 층만 세거나 층수를 곱하지 않는다(보이는 것만 센다)','한 층 × 층수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u6-X11','math',6,'u6',ARRAY['M6-1-u6-C5','M6-1-u6-C7']::text[],'부피를 가로 + 세로 + 높이로 더하거나, 두 길이만 곱한다(한 밑면의 넓이에서 멈춘다)','세 길이를 곱하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u6-X12','math',6,'u6',ARRAY['M6-1-u6-C5']::text[],'정육면체의 부피를 한 모서리 × 3이나 한 면의 넓이 × 6으로 구한다','한 모서리를 세 번 곱하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u6-X13','math',6,'u6',ARRAY['M6-1-u6-C6']::text[],'1 m³를 100 cm³·10000 cm³·1000 cm³로 여긴다(100을 세 번 곱하지 않는다)','100 × 100 × 100') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u6-X14','math',6,'u6',ARRAY['M6-1-u6-C6']::text[],'단위가 다른 길이(m와 cm)나 부피(m³와 cm³)를 같은 단위로 고치지 않고 그대로 셈하거나 견준다','단위부터 맞추기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u6-X15','math',6,'u6',ARRAY['M6-1-u6-C7']::text[],'직육면체를 자르면 부피도 바뀐다(줄어든다·늘어난다)고 여긴다','조각을 합치면 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u6-X16','math',6,'u6',ARRAY['M6-1-u6-C7']::text[],'자르면 겉넓이가 그대로라고 여기거나, 한 번 자를 때 새 면을 하나만 센다','한 번 자르면 새 면 2개') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u6-X17','math',6,'u6',ARRAY['M6-1-u6-C1','M6-1-u6-C2','M6-1-u6-C5']::text[],'겉넓이가 크면 부피도 크다(부피가 같으면 겉넓이도 같다)고 여긴다','서로 다른 양') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u6-X18','math',6,'u6',ARRAY['M6-1-u6-C1','M6-1-u6-C2','M6-1-u6-C3','M6-1-u6-C4','M6-1-u6-C5','M6-1-u6-C6','M6-1-u6-C7']::text[],'묻는 말을 놓치거나 곱셈·덧셈 셈을 잘못 한다 — 겉넓이↔부피, 한 면↔여섯 면, cm³↔m³, 옳은↔옳지 않은','물음에 동그라미 · 거꾸로 셈으로 검산') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_basic#1','math',6,1,'u6','L01','g6_1_math_u6_L01_basic','lesson_basic','M6-1-u6-C1',1,'mc','auto','겉넓이란 무엇인가요?',ARRAY['M6-1-u6-X01','M6-1-u6-X18']::text[],true,'{"seq":1,"concept":"M6-1-u6-C1","difficulty":1,"kind":"mc","stem":"겉넓이란 무엇인가요?","options":[{"t":"입체도형의 겉면의 넓이","correct":true},{"t":"입체도형이 담을 수 있는 양","mis":"M6-1-u6-X01"},{"t":"가장 긴 모서리의 길이","mis":"M6-1-u6-X18"},{"t":"꼭짓점의 개수","mis":"M6-1-u6-X18"}],"explanation":["직육면체는 직사각형 6개로 둘러싸여 있고, 마주 보는 면은 합동이에요.","겉넓이는 겉면 여섯 면의 넓이, 부피는 공간에서 차지하는 크기예요.","정답은 「입체도형의 겉면의 넓이」예요."],"variant_rule":{"alt":[{"stem":"부피란 무엇인가요?","options":[{"t":"입체도형이 공간에서 차지하는 크기","correct":true},{"t":"입체도형의 겉면의 넓이","mis":"M6-1-u6-X01"},{"t":"모든 모서리의 길이의 합","mis":"M6-1-u6-X18"},{"t":"한 면의 넓이","mis":"M6-1-u6-X01"}],"explanation":["직육면체는 직사각형 6개로 둘러싸여 있고, 마주 보는 면은 합동이에요.","겉넓이는 겉면 여섯 면의 넓이, 부피는 공간에서 차지하는 크기예요.","정답은 「입체도형이 공간에서 차지하는 크기」예요."]},{"stem":"직육면체의 겉면을 이루는 여섯 면은 모두 어떤 도형인가요?","options":[{"t":"직사각형","correct":true},{"t":"삼각형","mis":"M6-1-u6-X18"},{"t":"원","mis":"M6-1-u6-X18"},{"t":"사다리꼴","mis":"M6-1-u6-X18"}],"explanation":["직육면체는 직사각형 6개로 둘러싸여 있고, 마주 보는 면은 합동이에요.","겉넓이는 겉면 여섯 면의 넓이, 부피는 공간에서 차지하는 크기예요.","정답은 「직사각형」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_basic#2','math',6,1,'u6','L01','g6_1_math_u6_L01_basic','lesson_basic','M6-1-u6-C1',1,'mc','auto','다음 중 부피를 알아야 하는 상황은 어느 것인가요?',ARRAY['M6-1-u6-X01']::text[],true,'{"seq":2,"concept":"M6-1-u6-C1","difficulty":1,"kind":"mc","stem":"다음 중 부피를 알아야 하는 상황은 어느 것인가요?","options":[{"t":"상자 안에 모래를 얼마나 담을지 알 때","correct":true},{"t":"상자에 포장지를 붙일 때","mis":"M6-1-u6-X01"},{"t":"상자의 겉면을 색칠할 때","mis":"M6-1-u6-X01"},{"t":"상자를 감쌀 종이를 살 때","mis":"M6-1-u6-X01"}],"explanation":["감싸고 붙이고 칠하는 일은 겉면의 넓이, 곧 겉넓이와 관계있어요.","담고 채우고 넣는 일은 공간의 크기, 곧 부피와 관계있어요.","그래서 「상자 안에 모래를 얼마나 담을지 알 때」예요."],"variant_rule":{"alt":[{"stem":"다음 중 겉넓이를 알아야 하는 상황은 어느 것인가요?","options":[{"t":"청사초롱 겉면에 붙일 한지의 양을 알 때","correct":true},{"t":"청사초롱 안에 담기는 공간의 크기를 알 때","mis":"M6-1-u6-X01"},{"t":"어항에 물을 얼마나 채울지 알 때","mis":"M6-1-u6-X01"},{"t":"상자에 쌓기나무를 몇 개 넣을지 알 때","mis":"M6-1-u6-X01"}],"explanation":["감싸고 붙이고 칠하는 일은 겉면의 넓이, 곧 겉넓이와 관계있어요.","담고 채우고 넣는 일은 공간의 크기, 곧 부피와 관계있어요.","그래서 「청사초롱 겉면에 붙일 한지의 양을 알 때」예요."]},{"stem":"선물 상자를 포장지로 겹치지 않게 감쌀 때 필요한 종이의 양과 관계있는 것은 어느 것인가요?","options":[{"t":"겉넓이","correct":true},{"t":"부피","mis":"M6-1-u6-X01"},{"t":"모서리의 수","mis":"M6-1-u6-X18"},{"t":"꼭짓점의 수","mis":"M6-1-u6-X18"}],"explanation":["감싸고 붙이고 칠하는 일은 겉면의 넓이, 곧 겉넓이와 관계있어요.","담고 채우고 넣는 일은 공간의 크기, 곧 부피와 관계있어요.","그래서 「겉넓이」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_basic#3','math',6,1,'u6','L01','g6_1_math_u6_L01_basic','lesson_basic','M6-1-u6-C1',1,'sa','auto','가로 8 cm, 세로 5 cm인 직사각형의 넓이는 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u6-C1","difficulty":1,"kind":"sa","stem":"가로 8 cm, 세로 5 cm인 직사각형의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["직사각형의 넓이는 가로 × 세로예요.","8 × 5 = 40이에요.","그래서 40 cm²예요."],"mis":"M6-1-u6-X18","variant_rule":{"alt":[{"stem":"가로 7 cm, 세로 6 cm인 직사각형의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["42"],"explanation":["직사각형의 넓이는 가로 × 세로예요.","7 × 6 = 42예요.","그래서 42 cm²예요."]},{"stem":"가로 9 cm, 세로 4 cm인 직사각형의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["직사각형의 넓이는 가로 × 세로예요.","9 × 4 = 36이에요.","그래서 36 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_basic#4','math',6,1,'u6','L01','g6_1_math_u6_L01_basic','lesson_basic','M6-1-u6-C1',1,'ox','auto','겉넓이는 상자를 감싸는 종이의 양이고, 부피는 상자 안에 담기는 공간의 크기예요.',ARRAY['M6-1-u6-X01']::text[],true,'{"seq":4,"concept":"M6-1-u6-C1","difficulty":1,"kind":"ox","stem":"겉넓이는 상자를 감싸는 종이의 양이고, 부피는 상자 안에 담기는 공간의 크기예요.","answer":"O","reason_options":[{"t":"겉면의 넓이와 공간의 크기는 서로 다른 양이기 때문에","correct":true},{"t":"둘 다 상자의 크기라서 같은 양이기 때문에","mis":"M6-1-u6-X01"}],"mis":"M6-1-u6-X01","explanation":["직육면체는 직사각형 6개로 둘러싸여 있고 마주 보는 면은 합동이에요.","겉넓이는 감싸는 양, 부피는 담기는 양이에요.","두 양은 서로 달라요."],"variant_rule":{"alt":[{"stem":"직육면체의 여섯 면은 모두 직사각형이에요.","answer":"O","reason_options":[{"t":"직육면체는 직사각형 6개로 둘러싸인 도형이기 때문에","correct":true},{"t":"옆면만 직사각형이고 위아래는 다른 모양이기 때문에","mis":"M6-1-u6-X07"}],"explanation":["직육면체는 직사각형 6개로 둘러싸여 있고 마주 보는 면은 합동이에요.","겉넓이는 감싸는 양, 부피는 담기는 양이에요.","두 양은 서로 달라요."]},{"stem":"겉넓이는 겉면 여섯 면의 넓이를 모두 더한 것이에요.","answer":"O","reason_options":[{"t":"겉면은 여섯 면으로 이루어져 있기 때문에","correct":true},{"t":"보이는 세 면만 겉면이기 때문에","mis":"M6-1-u6-X03"}],"explanation":["직육면체는 직사각형 6개로 둘러싸여 있고 마주 보는 면은 합동이에요.","겉넓이는 감싸는 양, 부피는 담기는 양이에요.","두 양은 서로 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_basic#5','math',6,1,'u6','L01','g6_1_math_u6_L01_basic','lesson_basic','M6-1-u6-C1',2,'mc','auto','한 변이 1 m인 정사각형의 넓이는 몇 cm²인가요?',ARRAY['M6-1-u6-X14','M6-1-u6-X13']::text[],true,'{"seq":5,"concept":"M6-1-u6-C1","difficulty":2,"kind":"mc","stem":"한 변이 1 m인 정사각형의 넓이는 몇 cm²인가요?","options":[{"t":"10000 cm²","correct":true},{"t":"100 cm²","mis":"M6-1-u6-X14"},{"t":"1000 cm²","mis":"M6-1-u6-X14"},{"t":"1000000 cm²","mis":"M6-1-u6-X13"}],"explanation":["넓이는 길이를 두 번 곱해 구하므로 단위를 바꿀 때도 두 방향 모두 바꿔요.","1 m = 100 cm이므로 100 × 100 = 10000이에요.","그래서 10000 cm²예요."],"variant_rule":{"alt":[{"stem":"2 m²는 몇 cm²인가요?","options":[{"t":"20000 cm²","correct":true},{"t":"200 cm²","mis":"M6-1-u6-X14"},{"t":"2000 cm²","mis":"M6-1-u6-X14"},{"t":"2000000 cm²","mis":"M6-1-u6-X13"}],"explanation":["넓이는 길이를 두 번 곱해 구하므로 단위를 바꿀 때도 두 방향 모두 바꿔요.","1 m² = 10000 cm²이므로 10000 × 2 = 20000이에요.","그래서 20000 cm²예요."]},{"stem":"3 m²는 몇 cm²인가요?","options":[{"t":"30000 cm²","correct":true},{"t":"300 cm²","mis":"M6-1-u6-X14"},{"t":"3000 cm²","mis":"M6-1-u6-X14"},{"t":"3000000 cm²","mis":"M6-1-u6-X13"}],"explanation":["넓이는 길이를 두 번 곱해 구하므로 단위를 바꿀 때도 두 방향 모두 바꿔요.","1 m² = 10000 cm²이므로 10000 × 3 = 30000이에요.","그래서 30000 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_basic#6','math',6,1,'u6','L01','g6_1_math_u6_L01_basic','lesson_basic','M6-1-u6-C1',2,'sa','auto','직육면체의 겨냥도에서 색칠한 면(윗면)의 넓이는 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u6-C1","difficulty":2,"kind":"sa","stem":"직육면체의 겨냥도에서 색칠한 면(윗면)의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["색칠한 면은 직사각형이에요.","두 변의 길이를 곱하면 4 × 3 = 12예요.","그래서 12 cm²예요."],"mis":"M6-1-u6-X18","asset":{"type":"geo","items":[{"w":168.0,"h":94.0,"pts":{"ㄱ":[36.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,36.0,"w"],"ㄷ":[96.0,36.0,"sw"],"ㅁ":[36.0,48.0,"ne"],"ㅇ":[132.0,48.0,"e"],"ㅂ":[0,84.0,"sw"],"ㅅ":[96.0,84.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[48.0,97.0],"4 cm"],[[136.0,72.0],"3 cm"],[[158.0,24.0],"2 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체의 겨냥도에서 색칠한 면(앞면)의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["색칠한 면은 직사각형이에요.","두 변의 길이를 곱하면 5 × 3 = 15예요.","그래서 15 cm²예요."],"asset":{"type":"geo","items":[{"w":180.0,"h":106.0,"pts":{"ㄱ":[24.0,0,"nw"],"ㄹ":[144.0,0,"ne"],"ㄴ":[0,24.0,"w"],"ㄷ":[120.0,24.0,"sw"],"ㅁ":[24.0,72.0,"ne"],"ㅇ":[144.0,72.0,"e"],"ㅂ":[0,96.0,"sw"],"ㅅ":[120.0,96.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"poly":[["ㄴ","ㅂ","ㅅ","ㄷ"]],"lab":[[[60.0,109.0],"5 cm"],[[154.0,90.0],"2 cm"],[[170.0,36.0],"3 cm"]]}],"tag":false}},{"stem":"직육면체의 겨냥도에서 색칠한 면(오른쪽 옆면)의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["색칠한 면은 직사각형이에요.","두 변의 길이를 곱하면 3 × 5 = 15예요.","그래서 15 cm²예요."],"asset":{"type":"geo","items":[{"w":168.0,"h":166.0,"pts":{"ㄱ":[36.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,36.0,"w"],"ㄷ":[96.0,36.0,"sw"],"ㅁ":[36.0,120.0,"ne"],"ㅇ":[132.0,120.0,"e"],"ㅂ":[0,156.0,"sw"],"ㅅ":[96.0,156.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"poly":[["ㄷ","ㅅ","ㅇ","ㄹ"]],"lab":[[[48.0,169.0],"4 cm"],[[136.0,144.0],"3 cm"],[[158.0,60.0],"5 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_basic#7','math',6,1,'u6','L01','g6_1_math_u6_L01_basic','lesson_basic','M6-1-u6-C1',2,'mc','auto','직육면체에서 넓이가 서로 같은 면은 모두 몇 쌍인가요?',ARRAY['M6-1-u6-X07']::text[],true,'{"seq":7,"concept":"M6-1-u6-C1","difficulty":2,"kind":"mc","stem":"직육면체에서 넓이가 서로 같은 면은 모두 몇 쌍인가요?","options":[{"t":"세 쌍","correct":true},{"t":"한 쌍","mis":"M6-1-u6-X07"},{"t":"두 쌍","mis":"M6-1-u6-X07"},{"t":"여섯 쌍","mis":"M6-1-u6-X07"}],"explanation":["직육면체에서 마주 보는 두 면은 합동이에요.","마주 보는 면의 짝은 위아래·앞뒤·양옆 세 쌍이에요.","그래서 「세 쌍」이에요."],"asset":{"type":"geo","items":[{"w":132.0,"h":84.0,"pts":{"ㄱ":[36.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,36.0,"w"],"ㄷ":[96.0,36.0,"sw"],"ㅁ":[36.0,48.0,"ne"],"ㅇ":[132.0,48.0,"e"],"ㅂ":[0,84.0,"sw"],"ㅅ":[96.0,84.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체에서 한 면과 모양과 크기가 같은 면은 몇 개 더 있나요?","options":[{"t":"1개","correct":true},{"t":"2개","mis":"M6-1-u6-X07"},{"t":"3개","mis":"M6-1-u6-X07"},{"t":"5개","mis":"M6-1-u6-X07"}],"explanation":["직육면체에서 마주 보는 두 면은 합동이에요.","마주 보는 면의 짝은 위아래·앞뒤·양옆 세 쌍이에요.","그래서 「1개」예요."],"asset":{"type":"geo","items":[{"w":132.0,"h":84.0,"pts":{"ㄱ":[36.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,36.0,"w"],"ㄷ":[96.0,36.0,"sw"],"ㅁ":[36.0,48.0,"ne"],"ㅇ":[132.0,48.0,"e"],"ㅂ":[0,84.0,"sw"],"ㅅ":[96.0,84.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"직육면체에서 넓이가 서로 다른 면은 최대 몇 가지인가요?","options":[{"t":"3가지","correct":true},{"t":"2가지","mis":"M6-1-u6-X07"},{"t":"4가지","mis":"M6-1-u6-X07"},{"t":"6가지","mis":"M6-1-u6-X07"}],"explanation":["직육면체에서 마주 보는 두 면은 합동이에요.","마주 보는 면의 짝은 위아래·앞뒤·양옆 세 쌍이에요.","그래서 「3가지」예요."],"asset":{"type":"geo","items":[{"w":132.0,"h":84.0,"pts":{"ㄱ":[36.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,36.0,"w"],"ㄷ":[96.0,36.0,"sw"],"ㅁ":[36.0,48.0,"ne"],"ㅇ":[132.0,48.0,"e"],"ㅂ":[0,84.0,"sw"],"ㅅ":[96.0,84.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_basic#8','math',6,1,'u6','L01','g6_1_math_u6_L01_basic','lesson_basic','M6-1-u6-C1',2,'match','auto','상황에 알맞은 양을 이어 보세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u6-C1","difficulty":2,"kind":"match","stem":"상황에 알맞은 양을 이어 보세요.","pairs":[{"l":"상자를 포장지로 감쌀 때","r":"겉넓이"},{"l":"상자에 쌀을 가득 담을 때","r":"부피"},{"l":"상자의 모서리를 따라 테이프를 붙일 때","r":"모든 모서리의 길이의 합"}],"mis":"M6-1-u6-X01","explanation":["겉면을 감싸면 겉넓이, 안을 채우면 부피예요.","선을 따라 붙이거나 두르면 길이(둘레·모서리의 합)예요.","무엇을 재는지 먼저 생각해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 상황에 알맞은 양을 이어 보세요.","pairs":[{"l":"청사초롱 겉면에 한지를 붙일 때","r":"겉넓이"},{"l":"청사초롱 안의 공간을 알 때","r":"부피"},{"l":"청사초롱 바닥에 한 바퀴 끈을 두를 때","r":"한 밑면의 둘레"}],"explanation":["겉면을 감싸면 겉넓이, 안을 채우면 부피예요.","선을 따라 붙이거나 두르면 길이(둘레·모서리의 합)예요.","무엇을 재는지 먼저 생각해요."]},{"stem":"이번에는 다른 보기예요. 상황에 알맞은 양을 이어 보세요.","pairs":[{"l":"필통 겉면에 색종이를 붙일 때","r":"겉넓이"},{"l":"필통에 쌓기나무를 가득 넣을 때","r":"부피"},{"l":"필통의 모든 모서리에 철사를 댈 때","r":"모든 모서리의 길이의 합"}],"explanation":["겉면을 감싸면 겉넓이, 안을 채우면 부피예요.","선을 따라 붙이거나 두르면 길이(둘레·모서리의 합)예요.","무엇을 재는지 먼저 생각해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_basic#9','math',6,1,'u6','L01','g6_1_math_u6_L01_basic','lesson_basic','M6-1-u6-C1',2,'ox','auto','겉면이 넓은 상자일수록 언제나 더 많이 담을 수 있어요.',ARRAY['M6-1-u6-X17']::text[],true,'{"seq":9,"concept":"M6-1-u6-C1","difficulty":2,"kind":"ox","stem":"겉면이 넓은 상자일수록 언제나 더 많이 담을 수 있어요.","answer":"X","reason_options":[{"t":"겉넓이와 부피는 서로 다른 양이라 겉면이 넓어도 덜 담길 수 있기 때문에","correct":true},{"t":"겉면이 넓으면 안쪽 공간도 반드시 크기 때문에","mis":"M6-1-u6-X17"}],"mis":"M6-1-u6-X17","explanation":["직육면체는 직사각형 6개로 둘러싸여 있고 마주 보는 면은 합동이에요.","겉넓이는 감싸는 양, 부피는 담기는 양이에요.","두 양은 서로 달라요."],"variant_rule":{"alt":[{"stem":"직육면체에서 마주 보는 두 면은 넓이가 서로 달라요.","answer":"X","reason_options":[{"t":"마주 보는 두 면은 합동이라 넓이가 같기 때문에","correct":true},{"t":"위에 있는 면이 언제나 더 넓기 때문에","mis":"M6-1-u6-X07"}],"explanation":["직육면체는 직사각형 6개로 둘러싸여 있고 마주 보는 면은 합동이에요.","겉넓이는 감싸는 양, 부피는 담기는 양이에요.","두 양은 서로 달라요."]},{"stem":"포장지의 양을 알려면 상자에 담기는 공간의 크기를 재야 해요.","answer":"X","reason_options":[{"t":"포장지의 양은 겉면의 넓이(겉넓이)와 관계있기 때문에","correct":true},{"t":"포장지는 상자 안에 넣는 것이기 때문에","mis":"M6-1-u6-X01"}],"explanation":["직육면체는 직사각형 6개로 둘러싸여 있고 마주 보는 면은 합동이에요.","겉넓이는 감싸는 양, 부피는 담기는 양이에요.","두 양은 서로 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_basic#10','math',6,1,'u6','L01','g6_1_math_u6_L01_basic','lesson_basic','M6-1-u6-C1',3,'error','auto','똑같은 종이로 만든 두 상자를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u6-X17','M6-1-u6-X01']::text[],true,'{"seq":10,"concept":"M6-1-u6-C1","difficulty":3,"kind":"error","stem":"똑같은 종이로 만든 두 상자를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「겉면이 더 넓은 상자에 언제나 더 많이 담을 수 있어.」","correct":true,"mis_target":"M6-1-u6-X17"},{"t":"도윤 — 「포장지의 양은 겉넓이와 관계있어.」","mis":"M6-1-u6-X01"},{"t":"서아 — 「담기는 양은 부피로 비교해야 해.」","mis":"M6-1-u6-X01"}],"explanation":["겉넓이는 감싸는 종이의 양, 부피는 담기는 공간의 크기예요.","두 양은 서로 달라서 겉면이 넓어도 덜 담길 수 있어요.","하린은 두 양을 같은 것으로 여겼어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 똑같은 종이로 만든 두 상자를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「겉면이 더 넓은 상자에 언제나 더 많이 담을 수 있어.」","correct":true,"mis_target":"M6-1-u6-X17"},{"t":"예준 — 「포장지의 양은 겉넓이와 관계있어.」","mis":"M6-1-u6-X01"},{"t":"나린 — 「담기는 양은 부피로 비교해야 해.」","mis":"M6-1-u6-X01"}],"explanation":["겉넓이는 감싸는 종이의 양, 부피는 담기는 공간의 크기예요.","두 양은 서로 달라서 겉면이 넓어도 덜 담길 수 있어요.","수아는 두 양을 같은 것으로 여겼어요."]},{"stem":"이번에는 다른 보기예요. 똑같은 종이로 만든 두 상자를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「겉면이 더 넓은 상자에 언제나 더 많이 담을 수 있어.」","correct":true,"mis_target":"M6-1-u6-X17"},{"t":"유진 — 「포장지의 양은 겉넓이와 관계있어.」","mis":"M6-1-u6-X01"},{"t":"라온 — 「담기는 양은 부피로 비교해야 해.」","mis":"M6-1-u6-X01"}],"explanation":["겉넓이는 감싸는 종이의 양, 부피는 담기는 공간의 크기예요.","두 양은 서로 달라서 겉면이 넓어도 덜 담길 수 있어요.","가온은 두 양을 같은 것으로 여겼어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_challenge#1','math',6,1,'u6','L01','g6_1_math_u6_L01_challenge','lesson_challenge','M6-1-u6-C1',2,'mc','auto','창고에 상자를 얼마나 쌓아 넣을 수 있는지 알려면 무엇을 알아야 하나요?',ARRAY['M6-1-u6-X01','M6-1-u6-X18']::text[],true,'{"seq":1,"concept":"M6-1-u6-C1","difficulty":2,"kind":"mc","stem":"창고에 상자를 얼마나 쌓아 넣을 수 있는지 알려면 무엇을 알아야 하나요?","options":[{"t":"창고의 부피","correct":true},{"t":"창고 벽의 넓이","mis":"M6-1-u6-X01"},{"t":"창고 바닥의 둘레","mis":"M6-1-u6-X18"},{"t":"창고 문의 개수","mis":"M6-1-u6-X18"}],"explanation":["감싸고 붙이고 칠하는 일은 겉면의 넓이, 곧 겉넓이와 관계있어요.","담고 채우고 넣는 일은 공간의 크기, 곧 부피와 관계있어요.","그래서 「창고의 부피」예요."],"variant_rule":{"alt":[{"stem":"선물 상자를 포장지로 겹치지 않게 감쌀 때 필요한 종이의 양과 관계있는 것은 어느 것인가요?","options":[{"t":"겉넓이","correct":true},{"t":"부피","mis":"M6-1-u6-X01"},{"t":"모서리의 수","mis":"M6-1-u6-X18"},{"t":"꼭짓점의 수","mis":"M6-1-u6-X18"}],"explanation":["감싸고 붙이고 칠하는 일은 겉면의 넓이, 곧 겉넓이와 관계있어요.","담고 채우고 넣는 일은 공간의 크기, 곧 부피와 관계있어요.","그래서 「겉넓이」예요."]},{"stem":"다음 중 부피를 알아야 하는 상황은 어느 것인가요?","options":[{"t":"상자 안에 모래를 얼마나 담을지 알 때","correct":true},{"t":"상자에 포장지를 붙일 때","mis":"M6-1-u6-X01"},{"t":"상자의 겉면을 색칠할 때","mis":"M6-1-u6-X01"},{"t":"상자를 감쌀 종이를 살 때","mis":"M6-1-u6-X01"}],"explanation":["감싸고 붙이고 칠하는 일은 겉면의 넓이, 곧 겉넓이와 관계있어요.","담고 채우고 넣는 일은 공간의 크기, 곧 부피와 관계있어요.","그래서 「상자 안에 모래를 얼마나 담을지 알 때」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_challenge#2','math',6,1,'u6','L01','g6_1_math_u6_L01_challenge','lesson_challenge','M6-1-u6-C1',2,'sa','auto','직육면체의 겨냥도에서 색칠한 면(앞면)의 넓이는 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u6-C1","difficulty":2,"kind":"sa","stem":"직육면체의 겨냥도에서 색칠한 면(앞면)의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["색칠한 면은 직사각형이에요.","두 변의 길이를 곱하면 6 × 3 = 18이에요.","그래서 18 cm²예요."],"mis":"M6-1-u6-X18","asset":{"type":"geo","items":[{"w":226.0,"h":128.7,"pts":{"ㄱ":[47.5,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,47.5,"w"],"ㄷ":[142.5,47.5,"sw"],"ㅁ":[47.5,71.2,"ne"],"ㅇ":[190.0,71.2,"e"],"ㅂ":[0,118.7,"sw"],"ㅅ":[142.5,118.7,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"poly":[["ㄴ","ㅂ","ㅅ","ㄷ"]],"lab":[[[71.2,131.7],"6 cm"],[[188.2,101.0],"4 cm"],[[216.0,35.6],"3 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체의 겨냥도에서 색칠한 면(오른쪽 옆면)의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["색칠한 면은 직사각형이에요.","두 변의 길이를 곱하면 4 × 3 = 12예요.","그래서 12 cm²예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":128.7,"pts":{"ㄱ":[47.5,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,47.5,"w"],"ㄷ":[142.5,47.5,"sw"],"ㅁ":[47.5,71.2,"ne"],"ㅇ":[190.0,71.2,"e"],"ㅂ":[0,118.7,"sw"],"ㅅ":[142.5,118.7,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"poly":[["ㄷ","ㅅ","ㅇ","ㄹ"]],"lab":[[[71.2,131.7],"6 cm"],[[188.2,101.0],"4 cm"],[[216.0,35.6],"3 cm"]]}],"tag":false}},{"stem":"직육면체의 겨냥도에서 색칠한 면(윗면)의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["색칠한 면은 직사각형이에요.","두 변의 길이를 곱하면 5 × 3 = 15예요.","그래서 15 cm²예요."],"asset":{"type":"geo","items":[{"w":192.0,"h":142.0,"pts":{"ㄱ":[36.0,0,"nw"],"ㄹ":[156.0,0,"ne"],"ㄴ":[0,36.0,"w"],"ㄷ":[120.0,36.0,"sw"],"ㅁ":[36.0,96.0,"ne"],"ㅇ":[156.0,96.0,"e"],"ㅂ":[0,132.0,"sw"],"ㅅ":[120.0,132.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[60.0,145.0],"5 cm"],[[160.0,120.0],"3 cm"],[[182.0,48.0],"4 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_challenge#3','math',6,1,'u6','L01','g6_1_math_u6_L01_challenge','lesson_challenge','M6-1-u6-C1',3,'mc','auto','가로 2 m, 세로 1 m인 직사각형의 넓이는 몇 cm²인가요?',ARRAY['M6-1-u6-X14','M6-1-u6-X18']::text[],true,'{"seq":3,"concept":"M6-1-u6-C1","difficulty":3,"kind":"mc","stem":"가로 2 m, 세로 1 m인 직사각형의 넓이는 몇 cm²인가요?","options":[{"t":"20000 cm²","correct":true},{"t":"200 cm²","mis":"M6-1-u6-X14"},{"t":"300 cm²","mis":"M6-1-u6-X18"},{"t":"2 cm²","mis":"M6-1-u6-X14"}],"explanation":["넓이는 길이를 두 번 곱해 구하므로 단위를 바꿀 때도 두 방향 모두 바꿔요.","200 cm × 100 cm이므로 200 × 100 = 20000이에요.","그래서 20000 cm²예요."],"variant_rule":{"alt":[{"stem":"3 m²는 몇 cm²인가요?","options":[{"t":"30000 cm²","correct":true},{"t":"300 cm²","mis":"M6-1-u6-X14"},{"t":"3000 cm²","mis":"M6-1-u6-X14"},{"t":"3000000 cm²","mis":"M6-1-u6-X13"}],"explanation":["넓이는 길이를 두 번 곱해 구하므로 단위를 바꿀 때도 두 방향 모두 바꿔요.","1 m² = 10000 cm²이므로 10000 × 3 = 30000이에요.","그래서 30000 cm²예요."]},{"stem":"2 m²는 몇 cm²인가요?","options":[{"t":"20000 cm²","correct":true},{"t":"200 cm²","mis":"M6-1-u6-X14"},{"t":"2000 cm²","mis":"M6-1-u6-X14"},{"t":"2000000 cm²","mis":"M6-1-u6-X13"}],"explanation":["넓이는 길이를 두 번 곱해 구하므로 단위를 바꿀 때도 두 방향 모두 바꿔요.","1 m² = 10000 cm²이므로 10000 × 2 = 20000이에요.","그래서 20000 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_challenge#4','math',6,1,'u6','L01','g6_1_math_u6_L01_challenge','lesson_challenge','M6-1-u6-C1',3,'match','auto','상황에 알맞은 양을 이어 보세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u6-C1","difficulty":3,"kind":"match","stem":"상황에 알맞은 양을 이어 보세요.","pairs":[{"l":"청사초롱 겉면에 한지를 붙일 때","r":"겉넓이"},{"l":"청사초롱 안의 공간을 알 때","r":"부피"},{"l":"청사초롱 바닥에 한 바퀴 끈을 두를 때","r":"한 밑면의 둘레"}],"mis":"M6-1-u6-X01","explanation":["겉면을 감싸면 겉넓이, 안을 채우면 부피예요.","선을 따라 붙이거나 두르면 길이(둘레·모서리의 합)예요.","무엇을 재는지 먼저 생각해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 상황에 알맞은 양을 이어 보세요.","pairs":[{"l":"필통 겉면에 색종이를 붙일 때","r":"겉넓이"},{"l":"필통에 쌓기나무를 가득 넣을 때","r":"부피"},{"l":"필통의 모든 모서리에 철사를 댈 때","r":"모든 모서리의 길이의 합"}],"explanation":["겉면을 감싸면 겉넓이, 안을 채우면 부피예요.","선을 따라 붙이거나 두르면 길이(둘레·모서리의 합)예요.","무엇을 재는지 먼저 생각해요."]},{"stem":"이번에는 다른 보기예요. 상황에 알맞은 양을 이어 보세요.","pairs":[{"l":"상자를 포장지로 감쌀 때","r":"겉넓이"},{"l":"상자에 쌀을 가득 담을 때","r":"부피"},{"l":"상자의 모서리를 따라 테이프를 붙일 때","r":"모든 모서리의 길이의 합"}],"explanation":["겉면을 감싸면 겉넓이, 안을 채우면 부피예요.","선을 따라 붙이거나 두르면 길이(둘레·모서리의 합)예요.","무엇을 재는지 먼저 생각해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_challenge#5','math',6,1,'u6','L01','g6_1_math_u6_L01_challenge','lesson_challenge','M6-1-u6-C1',3,'sa','auto','가로 4 cm, 세로 3 cm, 높이 6 cm인 직육면체 모양 청사초롱을 만들었어요. 위와 아래는 뚫려 있고 옆면 네 개에만 한지를 붙여요. 붙일 한지는 몇 cm²인가요? (겹치는 부분은 없어요) 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u6-C1","difficulty":3,"kind":"sa","stem":"가로 4 cm, 세로 3 cm, 높이 6 cm인 직육면체 모양 청사초롱을 만들었어요. 위와 아래는 뚫려 있고 옆면 네 개에만 한지를 붙여요. 붙일 한지는 몇 cm²인가요? (겹치는 부분은 없어요) 숫자로 쓰세요.","answer":["84"],"explanation":["옆면은 4 × 6인 면 2개와 3 × 6인 면 2개예요.","4 × 6 × 2 + 3 × 6 × 2 = 84예요.","그래서 84 cm²예요."],"mis":"M6-1-u6-X07","asset":{"type":"geo","items":[{"w":168.0,"h":190.0,"pts":{"ㄱ":[36.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,36.0,"w"],"ㄷ":[96.0,36.0,"sw"],"ㅁ":[36.0,144.0,"ne"],"ㅇ":[132.0,144.0,"e"],"ㅂ":[0,180.0,"sw"],"ㅅ":[96.0,180.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[48.0,193.0],"4 cm"],[[136.0,168.0],"3 cm"],[[158.0,72.0],"6 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 5 cm, 세로 3 cm, 높이 6 cm인 직육면체 모양 청사초롱을 만들었어요. 위와 아래는 뚫려 있고 옆면 네 개에만 한지를 붙여요. 붙일 한지는 몇 cm²인가요? (겹치는 부분은 없어요) 숫자로 쓰세요.","answer":["96"],"explanation":["옆면은 5 × 6인 면 2개와 3 × 6인 면 2개예요.","5 × 6 × 2 + 3 × 6 × 2 = 96이에요.","그래서 96 cm²예요."],"asset":{"type":"geo","items":[{"w":192.0,"h":190.0,"pts":{"ㄱ":[36.0,0,"nw"],"ㄹ":[156.0,0,"ne"],"ㄴ":[0,36.0,"w"],"ㄷ":[120.0,36.0,"sw"],"ㅁ":[36.0,144.0,"ne"],"ㅇ":[156.0,144.0,"e"],"ㅂ":[0,180.0,"sw"],"ㅅ":[120.0,180.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[60.0,193.0],"5 cm"],[[160.0,168.0],"3 cm"],[[182.0,72.0],"6 cm"]]}],"tag":false}},{"stem":"가로 6 cm, 세로 4 cm, 높이 5 cm인 직육면체 모양 청사초롱을 만들었어요. 위와 아래는 뚫려 있고 옆면 네 개에만 한지를 붙여요. 붙일 한지는 몇 cm²인가요? (겹치는 부분은 없어요) 숫자로 쓰세요.","answer":["100"],"explanation":["옆면은 6 × 5인 면 2개와 4 × 5인 면 2개예요.","6 × 5 × 2 + 4 × 5 × 2 = 100이에요.","그래서 100 cm²예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":176.3,"pts":{"ㄱ":[47.5,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,47.5,"w"],"ㄷ":[142.5,47.5,"sw"],"ㅁ":[47.5,118.8,"ne"],"ㅇ":[190.0,118.8,"e"],"ㅂ":[0,166.3,"sw"],"ㅅ":[142.5,166.3,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[71.2,179.3],"6 cm"],[[188.2,148.6],"4 cm"],[[216.0,59.4],"5 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_challenge#6','math',6,1,'u6','L01','g6_1_math_u6_L01_challenge','lesson_challenge','M6-1-u6-C1',3,'mc','auto','직육면체에서 넓이가 서로 다른 면은 최대 몇 가지인가요?',ARRAY['M6-1-u6-X07']::text[],true,'{"seq":6,"concept":"M6-1-u6-C1","difficulty":3,"kind":"mc","stem":"직육면체에서 넓이가 서로 다른 면은 최대 몇 가지인가요?","options":[{"t":"3가지","correct":true},{"t":"2가지","mis":"M6-1-u6-X07"},{"t":"4가지","mis":"M6-1-u6-X07"},{"t":"6가지","mis":"M6-1-u6-X07"}],"explanation":["직육면체에서 마주 보는 두 면은 합동이에요.","마주 보는 면의 짝은 위아래·앞뒤·양옆 세 쌍이에요.","그래서 「3가지」예요."],"asset":{"type":"geo","items":[{"w":132.0,"h":84.0,"pts":{"ㄱ":[36.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,36.0,"w"],"ㄷ":[96.0,36.0,"sw"],"ㅁ":[36.0,48.0,"ne"],"ㅇ":[132.0,48.0,"e"],"ㅂ":[0,84.0,"sw"],"ㅅ":[96.0,84.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체에서 넓이가 서로 같은 면은 모두 몇 쌍인가요?","options":[{"t":"세 쌍","correct":true},{"t":"한 쌍","mis":"M6-1-u6-X07"},{"t":"두 쌍","mis":"M6-1-u6-X07"},{"t":"여섯 쌍","mis":"M6-1-u6-X07"}],"explanation":["직육면체에서 마주 보는 두 면은 합동이에요.","마주 보는 면의 짝은 위아래·앞뒤·양옆 세 쌍이에요.","그래서 「세 쌍」이에요."],"asset":{"type":"geo","items":[{"w":132.0,"h":84.0,"pts":{"ㄱ":[36.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,36.0,"w"],"ㄷ":[96.0,36.0,"sw"],"ㅁ":[36.0,48.0,"ne"],"ㅇ":[132.0,48.0,"e"],"ㅂ":[0,84.0,"sw"],"ㅅ":[96.0,84.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"직육면체에서 한 면과 모양과 크기가 같은 면은 몇 개 더 있나요?","options":[{"t":"1개","correct":true},{"t":"2개","mis":"M6-1-u6-X07"},{"t":"3개","mis":"M6-1-u6-X07"},{"t":"5개","mis":"M6-1-u6-X07"}],"explanation":["직육면체에서 마주 보는 두 면은 합동이에요.","마주 보는 면의 짝은 위아래·앞뒤·양옆 세 쌍이에요.","그래서 「1개」예요."],"asset":{"type":"geo","items":[{"w":132.0,"h":84.0,"pts":{"ㄱ":[36.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,36.0,"w"],"ㄷ":[96.0,36.0,"sw"],"ㅁ":[36.0,48.0,"ne"],"ㅇ":[132.0,48.0,"e"],"ㅂ":[0,84.0,"sw"],"ㅅ":[96.0,84.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_challenge#7','math',6,1,'u6','L01','g6_1_math_u6_L01_challenge','lesson_challenge','M6-1-u6-C1',3,'error','auto','똑같은 종이로 만든 두 상자를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u6-X17','M6-1-u6-X01']::text[],true,'{"seq":7,"concept":"M6-1-u6-C1","difficulty":3,"kind":"error","stem":"똑같은 종이로 만든 두 상자를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「겉면이 더 넓은 상자에 언제나 더 많이 담을 수 있어.」","correct":true,"mis_target":"M6-1-u6-X17"},{"t":"예준 — 「포장지의 양은 겉넓이와 관계있어.」","mis":"M6-1-u6-X01"},{"t":"나린 — 「담기는 양은 부피로 비교해야 해.」","mis":"M6-1-u6-X01"}],"explanation":["겉넓이는 감싸는 종이의 양, 부피는 담기는 공간의 크기예요.","두 양은 서로 달라서 겉면이 넓어도 덜 담길 수 있어요.","수아는 두 양을 같은 것으로 여겼어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 똑같은 종이로 만든 두 상자를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「겉면이 더 넓은 상자에 언제나 더 많이 담을 수 있어.」","correct":true,"mis_target":"M6-1-u6-X17"},{"t":"유진 — 「포장지의 양은 겉넓이와 관계있어.」","mis":"M6-1-u6-X01"},{"t":"라온 — 「담기는 양은 부피로 비교해야 해.」","mis":"M6-1-u6-X01"}],"explanation":["겉넓이는 감싸는 종이의 양, 부피는 담기는 공간의 크기예요.","두 양은 서로 달라서 겉면이 넓어도 덜 담길 수 있어요.","가온은 두 양을 같은 것으로 여겼어요."]},{"stem":"이번에는 다른 보기예요. 똑같은 종이로 만든 두 상자를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「겉면이 더 넓은 상자에 언제나 더 많이 담을 수 있어.」","correct":true,"mis_target":"M6-1-u6-X17"},{"t":"시우 — 「포장지의 양은 겉넓이와 관계있어.」","mis":"M6-1-u6-X01"},{"t":"은우 — 「담기는 양은 부피로 비교해야 해.」","mis":"M6-1-u6-X01"}],"explanation":["겉넓이는 감싸는 종이의 양, 부피는 담기는 공간의 크기예요.","두 양은 서로 달라서 겉면이 넓어도 덜 담길 수 있어요.","여울은 두 양을 같은 것으로 여겼어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_challenge#8','math',6,1,'u6','L01','g6_1_math_u6_L01_challenge','lesson_challenge','M6-1-u6-C1',4,'sa','auto','가로 8 cm, 세로 6 cm, 높이 10 cm인 직육면체 모양 청사초롱을 만들었어요. 위와 아래는 뚫려 있고 옆면 네 개에만 한지를 붙여요. 붙일 한지는 몇 cm²인가요? (겹치는 부분은 없어요) 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u6-C1","difficulty":4,"kind":"sa","stem":"가로 8 cm, 세로 6 cm, 높이 10 cm인 직육면체 모양 청사초롱을 만들었어요. 위와 아래는 뚫려 있고 옆면 네 개에만 한지를 붙여요. 붙일 한지는 몇 cm²인가요? (겹치는 부분은 없어요) 숫자로 쓰세요.","answer":["280"],"explanation":["옆면은 8 × 10인 면 2개와 6 × 10인 면 2개예요.","8 × 10 × 2 + 6 × 10 × 2 = 280이에요.","그래서 280 cm²예요."],"mis":"M6-1-u6-X07","asset":{"type":"geo","items":[{"w":201.0,"h":205.0,"pts":{"ㄱ":[45.0,0,"nw"],"ㄹ":[165.0,0,"ne"],"ㄴ":[0,45.0,"w"],"ㄷ":[120.0,45.0,"sw"],"ㅁ":[45.0,150.0,"ne"],"ㅇ":[165.0,150.0,"e"],"ㅂ":[0,195.0,"sw"],"ㅅ":[120.0,195.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[60.0,208.0],"8 cm"],[[164.5,178.5],"6 cm"],[[191.0,75.0],"10 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 10 cm, 세로 5 cm, 높이 12 cm인 직육면체 모양 청사초롱을 만들었어요. 위와 아래는 뚫려 있고 옆면 네 개에만 한지를 붙여요. 붙일 한지는 몇 cm²인가요? (겹치는 부분은 없어요) 숫자로 쓰세요.","answer":["360"],"explanation":["옆면은 10 × 12인 면 2개와 5 × 12인 면 2개예요.","10 × 12 × 2 + 5 × 12 × 2 = 360이에요.","그래서 360 cm²예요."],"asset":{"type":"geo","items":[{"w":192.2,"h":191.2,"pts":{"ㄱ":[31.2,0,"nw"],"ㄹ":[156.2,0,"ne"],"ㄴ":[0,31.2,"w"],"ㄷ":[125.0,31.2,"sw"],"ㅁ":[31.2,150.0,"ne"],"ㅇ":[156.2,150.0,"e"],"ㅂ":[0,181.2,"sw"],"ㅅ":[125.0,181.2,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[62.5,194.2],"10 cm"],[[162.6,171.6],"5 cm"],[[182.2,75.0],"12 cm"]]}],"tag":false}},{"stem":"가로 6 cm, 세로 6 cm, 높이 9 cm인 직육면체 모양 청사초롱을 만들었어요. 위와 아래는 뚫려 있고 옆면 네 개에만 한지를 붙여요. 붙일 한지는 몇 cm²인가요? (겹치는 부분은 없어요) 숫자로 쓰세요.","answer":["216"],"explanation":["옆면은 6 × 9인 면 2개와 6 × 9인 면 2개예요.","6 × 9 × 2 + 6 × 9 × 2 = 216이에요.","그래서 216 cm²예요."],"asset":{"type":"geo","items":[{"w":186.0,"h":210.0,"pts":{"ㄱ":[50.0,0,"nw"],"ㄹ":[150.0,0,"ne"],"ㄴ":[0,50.0,"w"],"ㄷ":[100.0,50.0,"sw"],"ㅁ":[50.0,150.0,"ne"],"ㅇ":[150.0,150.0,"e"],"ㅂ":[0,200.0,"sw"],"ㅅ":[100.0,200.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[50.0,213.0],"6 cm"],[[147.0,181.0],"6 cm"],[[176.0,75.0],"9 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_challenge#9','math',6,1,'u6','L01','g6_1_math_u6_L01_challenge','lesson_challenge','M6-1-u6-C1',4,'sa','auto','직육면체에서 서로 다른 세 면의 넓이가 12 cm², 20 cm², 15 cm²예요. 여섯 면의 넓이를 모두 더하면 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u6-C1","difficulty":4,"kind":"sa","stem":"직육면체에서 서로 다른 세 면의 넓이가 12 cm², 20 cm², 15 cm²예요. 여섯 면의 넓이를 모두 더하면 몇 cm²인가요? 숫자로 쓰세요.","answer":["94"],"explanation":["마주 보는 면은 합동이라 같은 넓이의 면이 두 개씩 있어요.","12 + 20 + 15 = 47, 47 × 2 = 94예요.","그래서 94 cm²예요."],"mis":"M6-1-u6-X07","variant_rule":{"alt":[{"stem":"직육면체에서 서로 다른 세 면의 넓이가 24 cm², 18 cm², 12 cm²예요. 여섯 면의 넓이를 모두 더하면 몇 cm²인가요? 숫자로 쓰세요.","answer":["108"],"explanation":["마주 보는 면은 합동이라 같은 넓이의 면이 두 개씩 있어요.","24 + 18 + 12 = 54, 54 × 2 = 108이에요.","그래서 108 cm²예요."]},{"stem":"직육면체에서 서로 다른 세 면의 넓이가 30 cm², 20 cm², 24 cm²예요. 여섯 면의 넓이를 모두 더하면 몇 cm²인가요? 숫자로 쓰세요.","answer":["148"],"explanation":["마주 보는 면은 합동이라 같은 넓이의 면이 두 개씩 있어요.","30 + 20 + 24 = 74, 74 × 2 = 148이에요.","그래서 148 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_challenge#10','math',6,1,'u6','L01','g6_1_math_u6_L01_challenge','lesson_challenge','M6-1-u6-C1',4,'essay','teacher','여울이는 「겉면이 넓은 상자가 언제나 더 많이 담긴다.」고 말했어요. 이 말이 맞는지 판단하고, 겉넓이와 부피가 어떤 양인지 넣어 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u6-C1","difficulty":4,"kind":"essay","stem":"여울이는 「겉면이 넓은 상자가 언제나 더 많이 담긴다.」고 말했어요. 이 말이 맞는지 판단하고, 겉넓이와 부피가 어떤 양인지 넣어 까닭을 써 보세요.","answer_guide":{"answer":"예: 맞지 않다. 겉넓이는 상자를 감싸는 종이의 양(겉면의 넓이)이고 부피는 상자 안에 담기는 공간의 크기라서 서로 다른 양이다. 그래서 겉면이 넓어도 담기는 양은 더 적을 수 있다.","scoring_points":["맞지 않다고 판단했는가","겉넓이 = 겉면의 넓이(감싸는 양)라고 썼는가","부피 = 담기는 공간의 크기라고 쓰고 두 양이 다르다고 설명했는가"]},"explanation":["겉넓이는 감싸는 양, 부피는 담기는 양이에요.","두 양은 서로 달라요.","그래서 겉면이 넓다고 언제나 더 많이 담기지는 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L02_basic#1','math',6,1,'u6','L02','g6_1_math_u6_L02_basic','lesson_basic','M6-1-u6-C2',1,'mc','auto','직육면체의 겉넓이를 서로 다른 세 면의 넓이의 합에 2를 곱해 구해도 되는 까닭은 무엇인가요?',ARRAY['M6-1-u6-X03','M6-1-u6-X07']::text[],true,'{"seq":1,"concept":"M6-1-u6-C2","difficulty":1,"kind":"mc","stem":"직육면체의 겉넓이를 서로 다른 세 면의 넓이의 합에 2를 곱해 구해도 되는 까닭은 무엇인가요?","options":[{"t":"마주 보는 면이 합동이라 넓이가 같은 면이 두 개씩 있기 때문에","correct":true},{"t":"보이는 면이 세 개뿐이기 때문에","mis":"M6-1-u6-X03"},{"t":"직육면체에는 면이 세 개 있기 때문에","mis":"M6-1-u6-X07"},{"t":"가로와 세로가 언제나 같기 때문에","mis":"M6-1-u6-X07"}],"explanation":["겉넓이는 여섯 면 전부의 넓이 합이에요.","마주 보는 면이 합동이라 같은 넓이가 두 번씩 있어요.","그래서 세 면의 합 × 2 = 여섯 면의 합이에요."],"variant_rule":{"alt":[{"stem":"겉넓이를 구할 때 흔히 하는 잘못은 어느 것인가요?","options":[{"t":"겨냥도에 보이는 세 면만 더한다","correct":true},{"t":"여섯 면을 모두 더한다","mis":"M6-1-u6-X03"},{"t":"마주 보는 면이 합동임을 이용한다","mis":"M6-1-u6-X07"},{"t":"서로 다른 세 면의 합을 2배 한다","mis":"M6-1-u6-X04"}],"explanation":["겉넓이는 여섯 면 전부의 넓이 합이에요.","마주 보는 면이 합동이라 같은 넓이가 두 번씩 있어요.","그래서 세 면의 합 × 2 = 여섯 면의 합이에요."]},{"stem":"여섯 면의 넓이를 각각 더한 값과 서로 다른 세 면의 합을 2배 한 값은 어떤 관계인가요?","options":[{"t":"언제나 같아요","correct":true},{"t":"2배 한 값이 언제나 커요","mis":"M6-1-u6-X04"},{"t":"여섯 면을 더한 값이 언제나 커요","mis":"M6-1-u6-X04"},{"t":"직육면체마다 달라요","mis":"M6-1-u6-X07"}],"explanation":["겉넓이는 여섯 면 전부의 넓이 합이에요.","마주 보는 면이 합동이라 같은 넓이가 두 번씩 있어요.","그래서 세 면의 합 × 2 = 여섯 면의 합이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L02_basic#2','math',6,1,'u6','L02','g6_1_math_u6_L02_basic','lesson_basic','M6-1-u6-C2',1,'sa','auto','가로 3 cm, 세로 2 cm, 높이 5 cm인 직육면체에서 서로 다른 세 면의 넓이의 합은 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u6-C2","difficulty":1,"kind":"sa","stem":"가로 3 cm, 세로 2 cm, 높이 5 cm인 직육면체에서 서로 다른 세 면의 넓이의 합은 몇 cm²인가요? 숫자로 쓰세요.","answer":["31"],"explanation":["서로 다른 세 면은 가로 × 세로, 가로 × 높이, 세로 × 높이인 면이에요.","3 × 2 + 3 × 5 + 2 × 5 = 31이에요.","그래서 31 cm²예요."],"mis":"M6-1-u6-X18","asset":{"type":"geo","items":[{"w":132.0,"h":154.0,"pts":{"ㄱ":[24.0,0,"nw"],"ㄹ":[96.0,0,"ne"],"ㄴ":[0,24.0,"w"],"ㄷ":[72.0,24.0,"sw"],"ㅁ":[24.0,120.0,"ne"],"ㅇ":[96.0,120.0,"e"],"ㅂ":[0,144.0,"sw"],"ㅅ":[72.0,144.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[36.0,157.0],"3 cm"],[[106.0,138.0],"2 cm"],[[122.0,60.0],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 4 cm, 세로 3 cm, 높이 2 cm인 직육면체에서 서로 다른 세 면의 넓이의 합은 몇 cm²인가요? 숫자로 쓰세요.","answer":["26"],"explanation":["서로 다른 세 면은 가로 × 세로, 가로 × 높이, 세로 × 높이인 면이에요.","4 × 3 + 4 × 2 + 3 × 2 = 26이에요.","그래서 26 cm²예요."],"asset":{"type":"geo","items":[{"w":168.0,"h":94.0,"pts":{"ㄱ":[36.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,36.0,"w"],"ㄷ":[96.0,36.0,"sw"],"ㅁ":[36.0,48.0,"ne"],"ㅇ":[132.0,48.0,"e"],"ㅂ":[0,84.0,"sw"],"ㅅ":[96.0,84.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[48.0,97.0],"4 cm"],[[136.0,72.0],"3 cm"],[[158.0,24.0],"2 cm"]]}],"tag":false}},{"stem":"가로 5 cm, 세로 2 cm, 높이 3 cm인 직육면체에서 서로 다른 세 면의 넓이의 합은 몇 cm²인가요? 숫자로 쓰세요.","answer":["31"],"explanation":["서로 다른 세 면은 가로 × 세로, 가로 × 높이, 세로 × 높이인 면이에요.","5 × 2 + 5 × 3 + 2 × 3 = 31이에요.","그래서 31 cm²예요."],"asset":{"type":"geo","items":[{"w":180.0,"h":106.0,"pts":{"ㄱ":[24.0,0,"nw"],"ㄹ":[144.0,0,"ne"],"ㄴ":[0,24.0,"w"],"ㄷ":[120.0,24.0,"sw"],"ㅁ":[24.0,72.0,"ne"],"ㅇ":[144.0,72.0,"e"],"ㅂ":[0,96.0,"sw"],"ㅅ":[120.0,96.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[60.0,109.0],"5 cm"],[[154.0,90.0],"2 cm"],[[170.0,36.0],"3 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L02_basic#3','math',6,1,'u6','L02','g6_1_math_u6_L02_basic','lesson_basic','M6-1-u6-C2',1,'ox','auto','직육면체의 겉넓이는 겨냥도에 보이는 세 면의 넓이를 더한 것이에요.',ARRAY['M6-1-u6-X03']::text[],true,'{"seq":3,"concept":"M6-1-u6-C2","difficulty":1,"kind":"ox","stem":"직육면체의 겉넓이는 겨냥도에 보이는 세 면의 넓이를 더한 것이에요.","answer":"X","reason_options":[{"t":"겉넓이는 보이지 않는 면까지 여섯 면 전부의 넓이이기 때문에","correct":true},{"t":"보이지 않는 면은 겉면이 아니기 때문에","mis":"M6-1-u6-X03"}],"mis":"M6-1-u6-X03","explanation":["겉넓이는 여섯 면 전부의 넓이 합이에요.","마주 보는 면이 합동이라 세 면의 합 × 2로도 구해요.","단위는 넓이 단위 cm²를 써요."],"variant_rule":{"alt":[{"stem":"직육면체에서 넓이가 같은 면은 세 쌍이에요.","answer":"O","reason_options":[{"t":"마주 보는 면이 합동인 짝이 위아래·앞뒤·양옆 세 쌍이기 때문에","correct":true},{"t":"모든 면의 넓이가 같기 때문에","mis":"M6-1-u6-X07"}],"explanation":["겉넓이는 여섯 면 전부의 넓이 합이에요.","마주 보는 면이 합동이라 세 면의 합 × 2로도 구해요.","단위는 넓이 단위 cm²를 써요."]},{"stem":"겉넓이의 단위는 cm²처럼 넓이의 단위를 써요.","answer":"O","reason_options":[{"t":"겉넓이는 여섯 면의 넓이를 더한 넓이이기 때문에","correct":true},{"t":"겉넓이는 길이라서 cm를 쓰기 때문에","mis":"M6-1-u6-X02"}],"explanation":["겉넓이는 여섯 면 전부의 넓이 합이에요.","마주 보는 면이 합동이라 세 면의 합 × 2로도 구해요.","단위는 넓이 단위 cm²를 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L02_basic#4','math',6,1,'u6','L02','g6_1_math_u6_L02_basic','lesson_basic','M6-1-u6-C2',1,'sa','auto','직육면체에서 한 면의 넓이가 15 cm²예요. 이 면과 마주 보는 면까지 두 면의 넓이의 합은 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u6-C2","difficulty":1,"kind":"sa","stem":"직육면체에서 한 면의 넓이가 15 cm²예요. 이 면과 마주 보는 면까지 두 면의 넓이의 합은 몇 cm²인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["마주 보는 면은 합동이라 넓이가 같아요.","15 × 2 = 30이에요.","그래서 30 cm²예요."],"mis":"M6-1-u6-X07","variant_rule":{"alt":[{"stem":"직육면체에서 한 면의 넓이가 12 cm²예요. 이 면과 마주 보는 면까지 두 면의 넓이의 합은 몇 cm²인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["마주 보는 면은 합동이라 넓이가 같아요.","12 × 2 = 24예요.","그래서 24 cm²예요."]},{"stem":"직육면체에서 한 면의 넓이가 24 cm²예요. 이 면과 마주 보는 면까지 두 면의 넓이의 합은 몇 cm²인가요? 숫자로 쓰세요.","answer":["48"],"explanation":["마주 보는 면은 합동이라 넓이가 같아요.","24 × 2 = 48이에요.","그래서 48 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L02_basic#5','math',6,1,'u6','L02','g6_1_math_u6_L02_basic','lesson_basic','M6-1-u6-C2',2,'sa','auto','가로 3 cm, 세로 2 cm, 높이 5 cm인 직육면체의 겉넓이는 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u6-C2","difficulty":2,"kind":"sa","stem":"가로 3 cm, 세로 2 cm, 높이 5 cm인 직육면체의 겉넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["62"],"explanation":["서로 다른 세 면의 넓이는 3 × 2 + 3 × 5 + 2 × 5 = 31이에요.","마주 보는 면이 합동이라 31 × 2 = 62(cm²)예요.","그래서 겉넓이는 62 cm²예요."],"mis":"M6-1-u6-X03","asset":{"type":"geo","items":[{"w":132.0,"h":154.0,"pts":{"ㄱ":[24.0,0,"nw"],"ㄹ":[96.0,0,"ne"],"ㄴ":[0,24.0,"w"],"ㄷ":[72.0,24.0,"sw"],"ㅁ":[24.0,120.0,"ne"],"ㅇ":[96.0,120.0,"e"],"ㅂ":[0,144.0,"sw"],"ㅅ":[72.0,144.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[36.0,157.0],"3 cm"],[[106.0,138.0],"2 cm"],[[122.0,60.0],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 4 cm, 세로 3 cm, 높이 6 cm인 직육면체의 겉넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["108"],"explanation":["서로 다른 세 면의 넓이는 4 × 3 + 4 × 6 + 3 × 6 = 54예요.","마주 보는 면이 합동이라 54 × 2 = 108(cm²)예요.","그래서 겉넓이는 108 cm²예요."],"asset":{"type":"geo","items":[{"w":168.0,"h":190.0,"pts":{"ㄱ":[36.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,36.0,"w"],"ㄷ":[96.0,36.0,"sw"],"ㅁ":[36.0,144.0,"ne"],"ㅇ":[132.0,144.0,"e"],"ㅂ":[0,180.0,"sw"],"ㅅ":[96.0,180.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[48.0,193.0],"4 cm"],[[136.0,168.0],"3 cm"],[[158.0,72.0],"6 cm"]]}],"tag":false}},{"stem":"가로 5 cm, 세로 4 cm, 높이 2 cm인 직육면체의 겉넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["76"],"explanation":["서로 다른 세 면의 넓이는 5 × 4 + 5 × 2 + 4 × 2 = 38이에요.","마주 보는 면이 합동이라 38 × 2 = 76(cm²)예요.","그래서 겉넓이는