INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L02_basic#9','math',6,1,'u6','L02','g6_1_math_u6_L02_basic','lesson_basic','M6-1-u6-C2',2,'ox','auto','서로 다른 세 면의 넓이의 합을 2배 하면 겉넓이가 돼요.',ARRAY['M6-1-u6-X04']::text[],true,'{"seq":9,"concept":"M6-1-u6-C2","difficulty":2,"kind":"ox","stem":"서로 다른 세 면의 넓이의 합을 2배 하면 겉넓이가 돼요.","answer":"O","reason_options":[{"t":"마주 보는 면이 합동이라 같은 넓이가 두 번씩 있기 때문에","correct":true},{"t":"여섯 면을 다 더한 뒤 또 2배 해야 하기 때문에","mis":"M6-1-u6-X04"}],"mis":"M6-1-u6-X04","explanation":["겉넓이는 여섯 면 전부의 넓이 합이에요.","마주 보는 면이 합동이라 세 면의 합 × 2로도 구해요.","단위는 넓이 단위 cm²를 써요."],"variant_rule":{"alt":[{"stem":"여섯 면을 각각 더한 값과 세 면의 합 × 2의 값은 서로 달라요.","answer":"X","reason_options":[{"t":"두 방법은 같은 여섯 면을 더하는 것이라 값이 같기 때문에","correct":true},{"t":"방법이 다르면 답도 달라지기 때문에","mis":"M6-1-u6-X04"}],"explanation":["겉넓이는 여섯 면 전부의 넓이 합이에요.","마주 보는 면이 합동이라 세 면의 합 × 2로도 구해요.","단위는 넓이 단위 cm²를 써요."]},{"stem":"직육면체에서 넓이가 같은 면은 세 쌍이에요.","answer":"O","reason_options":[{"t":"마주 보는 면이 합동인 짝이 위아래·앞뒤·양옆 세 쌍이기 때문에","correct":true},{"t":"모든 면의 넓이가 같기 때문에","mis":"M6-1-u6-X07"}],"explanation":["겉넓이는 여섯 면 전부의 넓이 합이에요.","마주 보는 면이 합동이라 세 면의 합 × 2로도 구해요.","단위는 넓이 단위 cm²를 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L02_basic#10','math',6,1,'u6','L02','g6_1_math_u6_L02_basic','lesson_basic','M6-1-u6-C2',3,'error','auto','가로 3 cm, 세로 2 cm, 높이 5 cm인 직육면체의 겉넓이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u6-X03','M6-1-u6-X18','M6-1-u6-X04']::text[],true,'{"seq":10,"concept":"M6-1-u6-C2","difficulty":3,"kind":"error","stem":"가로 3 cm, 세로 2 cm, 높이 5 cm인 직육면체의 겉넓이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「겨냥도에 보이는 세 면의 넓이를 더한 31 cm²가 겉넓이야.」","correct":true,"mis_target":"M6-1-u6-X03"},{"t":"도윤 — 「서로 다른 세 면의 넓이의 합은 31 cm²야.」","mis":"M6-1-u6-X18"},{"t":"서아 — 「겉넓이는 62 cm²야.」","mis":"M6-1-u6-X04"}],"explanation":["겨냥도에서는 세 면만 보이지만 겉넓이는 여섯 면 전부의 넓이예요.","31 × 2 = 62이므로 겉넓이는 62 cm²예요.","하린은 보이는 세 면만 더해 절반만 셌어요."],"asset":{"type":"geo","items":[{"w":132.0,"h":154.0,"pts":{"ㄱ":[24.0,0,"nw"],"ㄹ":[96.0,0,"ne"],"ㄴ":[0,24.0,"w"],"ㄷ":[72.0,24.0,"sw"],"ㅁ":[24.0,120.0,"ne"],"ㅇ":[96.0,120.0,"e"],"ㅂ":[0,144.0,"sw"],"ㅅ":[72.0,144.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[36.0,157.0],"3 cm"],[[106.0,138.0],"2 cm"],[[122.0,60.0],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 4 cm, 세로 3 cm, 높이 6 cm인 직육면체의 겉넓이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「겨냥도에 보이는 세 면의 넓이를 더한 54 cm²가 겉넓이야.」","correct":true,"mis_target":"M6-1-u6-X03"},{"t":"예준 — 「서로 다른 세 면의 넓이의 합은 54 cm²야.」","mis":"M6-1-u6-X18"},{"t":"나린 — 「겉넓이는 108 cm²야.」","mis":"M6-1-u6-X04"}],"explanation":["겨냥도에서는 세 면만 보이지만 겉넓이는 여섯 면 전부의 넓이예요.","54 × 2 = 108이므로 겉넓이는 108 cm²예요.","수아는 보이는 세 면만 더해 절반만 셌어요."],"asset":{"type":"geo","items":[{"w":168.0,"h":190.0,"pts":{"ㄱ":[36.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,36.0,"w"],"ㄷ":[96.0,36.0,"sw"],"ㅁ":[36.0,144.0,"ne"],"ㅇ":[132.0,144.0,"e"],"ㅂ":[0,180.0,"sw"],"ㅅ":[96.0,180.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[48.0,193.0],"4 cm"],[[136.0,168.0],"3 cm"],[[158.0,72.0],"6 cm"]]}],"tag":false}},{"stem":"가로 5 cm, 세로 4 cm, 높이 2 cm인 직육면체의 겉넓이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「겨냥도에 보이는 세 면의 넓이를 더한 38 cm²가 겉넓이야.」","correct":true,"mis_target":"M6-1-u6-X03"},{"t":"유진 — 「서로 다른 세 면의 넓이의 합은 38 cm²야.」","mis":"M6-1-u6-X18"},{"t":"라온 — 「겉넓이는 76 cm²야.」","mis":"M6-1-u6-X04"}],"explanation":["겨냥도에서는 세 면만 보이지만 겉넓이는 여섯 면 전부의 넓이예요.","38 × 2 = 76이므로 겉넓이는 76 cm²예요.","가온은 보이는 세 면만 더해 절반만 셌어요."],"asset":{"type":"geo","items":[{"w":204.0,"h":106.0,"pts":{"ㄱ":[48.0,0,"nw"],"ㄹ":[168.0,0,"ne"],"ㄴ":[0,48.0,"w"],"ㄷ":[120.0,48.0,"sw"],"ㅁ":[48.0,48.0,"ne"],"ㅇ":[168.0,48.0,"e"],"ㅂ":[0,96.0,"sw"],"ㅅ":[120.0,96.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[60.0,109.0],"5 cm"],[[166.0,78.0],"4 cm"],[[194.0,24.0],"2 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L02_challenge#1','math',6,1,'u6','L02','g6_1_math_u6_L02_challenge','lesson_challenge','M6-1-u6-C2',2,'sa','auto','가로 6 cm, 세로 4 cm, 높이 3 cm인 직육면체에서 가장 좁은 면 한 개의 넓이는 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u6-C2","difficulty":2,"kind":"sa","stem":"가로 6 cm, 세로 4 cm, 높이 3 cm인 직육면체에서 가장 좁은 면 한 개의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["세 가지 면의 넓이는 6 × 4 = 24, 6 × 3 = 18, 4 × 3 = 12예요.","그중 가장 좁은 것은 12예요.","그래서 12 cm²예요."],"mis":"M6-1-u6-X18","asset":{"type":"geo","items":[{"w":226.0,"h":128.7,"pts":{"ㄱ":[47.5,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,47.5,"w"],"ㄷ":[142.5,47.5,"sw"],"ㅁ":[47.5,71.2,"ne"],"ㅇ":[190.0,71.2,"e"],"ㅂ":[0,118.7,"sw"],"ㅅ":[142.5,118.7,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[71.2,131.7],"6 cm"],[[188.2,101.0],"4 cm"],[[216.0,35.6],"3 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 7 cm, 세로 5 cm, 높이 2 cm인 직육면체에서 가장 좁은 면 한 개의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["세 가지 면의 넓이는 7 × 5 = 35, 7 × 2 = 14, 5 × 2 = 10이에요.","그중 가장 좁은 것은 10이에요.","그래서 10 cm²예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":100.0,"pts":{"ㄱ":[50.0,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,50.0,"w"],"ㄷ":[140.0,50.0,"sw"],"ㅁ":[50.0,40.0,"ne"],"ㅇ":[190.0,40.0,"e"],"ㅂ":[0,90.0,"sw"],"ㅅ":[140.0,90.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[70.0,103.0],"7 cm"],[[187.0,71.0],"5 cm"],[[216.0,20.0],"2 cm"]]}],"tag":false}},{"stem":"가로 8 cm, 세로 3 cm, 높이 4 cm인 직육면체에서 가장 좁은 면 한 개의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["세 가지 면의 넓이는 8 × 3 = 24, 8 × 4 = 32, 3 × 4 = 12예요.","그중 가장 좁은 것은 12예요.","그래서 12 cm²예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":120.0,"pts":{"ㄱ":[30.0,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,30.0,"w"],"ㄷ":[160.0,30.0,"sw"],"ㅁ":[30.0,80.0,"ne"],"ㅇ":[190.0,80.0,"e"],"ㅂ":[0,110.0,"sw"],"ㅅ":[160.0,110.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[80.0,123.0],"8 cm"],[[197.0,101.0],"3 cm"],[[216.0,40.0],"4 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L02_challenge#2','math',6,1,'u6','L02','g6_1_math_u6_L02_challenge','lesson_challenge','M6-1-u6-C2',2,'mc','auto','여섯 면의 넓이를 각각 더한 값과 서로 다른 세 면의 합을 2배 한 값은 어떤 관계인가요?',ARRAY['M6-1-u6-X04','M6-1-u6-X07']::text[],true,'{"seq":2,"concept":"M6-1-u6-C2","difficulty":2,"kind":"mc","stem":"여섯 면의 넓이를 각각 더한 값과 서로 다른 세 면의 합을 2배 한 값은 어떤 관계인가요?","options":[{"t":"언제나 같아요","correct":true},{"t":"2배 한 값이 언제나 커요","mis":"M6-1-u6-X04"},{"t":"여섯 면을 더한 값이 언제나 커요","mis":"M6-1-u6-X04"},{"t":"직육면체마다 달라요","mis":"M6-1-u6-X07"}],"explanation":["겉넓이는 여섯 면 전부의 넓이 합이에요.","마주 보는 면이 합동이라 같은 넓이가 두 번씩 있어요.","그래서 세 면의 합 × 2 = 여섯 면의 합이에요."],"variant_rule":{"alt":[{"stem":"직육면체의 겉넓이를 서로 다른 세 면의 넓이의 합에 2를 곱해 구해도 되는 까닭은 무엇인가요?","options":[{"t":"마주 보는 면이 합동이라 넓이가 같은 면이 두 개씩 있기 때문에","correct":true},{"t":"보이는 면이 세 개뿐이기 때문에","mis":"M6-1-u6-X03"},{"t":"직육면체에는 면이 세 개 있기 때문에","mis":"M6-1-u6-X07"},{"t":"가로와 세로가 언제나 같기 때문에","mis":"M6-1-u6-X07"}],"explanation":["겉넓이는 여섯 면 전부의 넓이 합이에요.","마주 보는 면이 합동이라 같은 넓이가 두 번씩 있어요.","그래서 세 면의 합 × 2 = 여섯 면의 합이에요."]},{"stem":"겉넓이를 구할 때 흔히 하는 잘못은 어느 것인가요?","options":[{"t":"겨냥도에 보이는 세 면만 더한다","correct":true},{"t":"여섯 면을 모두 더한다","mis":"M6-1-u6-X03"},{"t":"마주 보는 면이 합동임을 이용한다","mis":"M6-1-u6-X07"},{"t":"서로 다른 세 면의 합을 2배 한다","mis":"M6-1-u6-X04"}],"explanation":["겉넓이는 여섯 면 전부의 넓이 합이에요.","마주 보는 면이 합동이라 같은 넓이가 두 번씩 있어요.","그래서 세 면의 합 × 2 = 여섯 면의 합이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L02_challenge#3','math',6,1,'u6','L02','g6_1_math_u6_L02_challenge','lesson_challenge','M6-1-u6-C2',3,'sa','auto','가로 9 cm, 세로 5 cm, 높이 4 cm인 직육면체 모양 선물 상자의 겉넓이는 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u6-C2","difficulty":3,"kind":"sa","stem":"가로 9 cm, 세로 5 cm, 높이 4 cm인 직육면체 모양 선물 상자의 겉넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["202"],"explanation":["서로 다른 세 면의 넓이는 9 × 5 + 9 × 4 + 5 × 4 = 101이에요.","마주 보는 면이 합동이라 101 × 2 = 202(cm²)예요.","그래서 겉넓이는 202 cm²예요."],"mis":"M6-1-u6-X03","asset":{"type":"geo","items":[{"w":226.0,"h":117.4,"pts":{"ㄱ":[41.3,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,41.3,"w"],"ㄷ":[148.7,41.3,"sw"],"ㅁ":[41.3,66.1,"ne"],"ㅇ":[190.0,66.1,"e"],"ㅂ":[0,107.4,"sw"],"ㅅ":[148.7,107.4,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[74.3,120.4],"9 cm"],[[191.3,92.8],"5 cm"],[[216.0,33.0],"4 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 10 cm, 세로 6 cm, 높이 5 cm인 직육면체 모양 선물 상자의 겉넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["280"],"explanation":["서로 다른 세 면의 넓이는 10 × 6 + 10 × 5 + 6 × 5 = 140이에요.","마주 보는 면이 합동이라 140 × 2 = 280(cm²)예요.","그래서 겉넓이는 280 cm²예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":126.9,"pts":{"ㄱ":[43.8,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,43.8,"w"],"ㄷ":[146.2,43.8,"sw"],"ㅁ":[43.8,73.1,"ne"],"ㅇ":[190.0,73.1,"e"],"ㅂ":[0,116.9,"sw"],"ㅅ":[146.2,116.9,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[73.1,129.9],"10 cm"],[[190.1,101.0],"6 cm"],[[216.0,36.5],"5 cm"]]}],"tag":false}},{"stem":"가로 8 cm, 세로 7 cm, 높이 4 cm인 직육면체 모양 선물 상자의 겉넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["232"],"explanation":["서로 다른 세 면의 넓이는 8 × 7 + 8 × 4 +