INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L02_challenge#7','math',6,1,'u6','L02','g6_1_math_u6_L02_challenge','lesson_challenge','M6-1-u6-C2',3,'mc','auto','가로 7 cm, 세로 4 cm, 높이 5 cm인 직육면체의 겉넓이를 서로 다른 세 면으로 구하는 바른 식은 어느 것인가요?',ARRAY['M6-1-u6-X03','M6-1-u6-X04','M6-1-u6-X18']::text[],true,'{"seq":7,"concept":"M6-1-u6-C2","difficulty":3,"kind":"mc","stem":"가로 7 cm, 세로 4 cm, 높이 5 cm인 직육면체의 겉넓이를 서로 다른 세 면으로 구하는 바른 식은 어느 것인가요?","options":[{"t":"(7 × 4 + 7 × 5 + 4 × 5) × 2","correct":true},{"t":"7 × 4 + 7 × 5 + 4 × 5","mis":"M6-1-u6-X03"},{"t":"(7 × 4 + 7 × 5 + 4 × 5) × 2 × 2","mis":"M6-1-u6-X04"},{"t":"(7 + 4 + 5) × 2","mis":"M6-1-u6-X18"}],"explanation":["마주 보는 면이 합동이라 넓이가 같은 면이 세 쌍 있어요.","서로 다른 세 면의 넓이를 더한 뒤 2배 하면 여섯 면을 모두 더한 것과 같아요.","바른 식은 (7 × 4 + 7 × 5 + 4 × 5) × 2예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":157.8,"pts":{"ㄱ":[42.2,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,42.2,"w"],"ㄷ":[147.8,42.2,"sw"],"ㅁ":[42.2,105.6,"ne"],"ㅇ":[190.0,105.6,"e"],"ㅂ":[0,147.8,"sw"],"ㅅ":[147.8,147.8,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[73.9,160.8],"7 cm"],[[190.9,132.7],"4 cm"],[[216.0,52.8],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 8 cm, 세로 6 cm, 높이 3 cm인 직육면체의 겉넓이를 서로 다른 세 면으로 구하는 바른 식은 어느 것인가요?","options":[{"t":"(8 × 6 + 8 × 3 + 6 × 3) × 2","correct":true},{"t":"8 × 6 + 8 × 3 + 6 × 3","mis":"M6-1-u6-X03"},{"t":"(8 × 6 + 8 × 3 + 6 × 3) × 2 × 2","mis":"M6-1-u6-X04"},{"t":"(8 + 6 + 3) × 2","mis":"M6-1-u6-X18"}],"explanation":["마주 보는 면이 합동이라 넓이가 같은 면이 세 쌍 있어요.","서로 다른 세 면의 넓이를 더한 뒤 2배 하면 여섯 면을 모두 더한 것과 같아요.","바른 식은 (8 × 6 + 8 × 3 + 6 × 3) × 2예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":113.6,"pts":{"ㄱ":[51.8,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,51.8,"w"],"ㄷ":[138.2,51.8,"sw"],"ㅁ"