INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L03_basic#7','math',6,1,'u6','L03','g6_1_math_u6_L03_basic','lesson_basic','M6-1-u6-C3',2,'sa','auto','가로 4 cm, 세로 2 cm, 높이 3 cm인 직육면체의 겉넓이를 두 밑면과 옆면으로 나누어 구하면 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u6-C3","difficulty":2,"kind":"sa","stem":"가로 4 cm, 세로 2 cm, 높이 3 cm인 직육면체의 겉넓이를 두 밑면과 옆면으로 나누어 구하면 몇 cm²인가요? 숫자로 쓰세요.","answer":["52"],"explanation":["두 밑면은 4 × 2 × 2 = 16(cm²)예요.","옆면의 가로는 한 밑면의 둘레 4 + 2 + 4 + 2 = 12, 옆면은 12 × 3 = 36(cm²)예요.","겉넓이는 16 + 36 = 52(cm²)예요."],"mis":"M6-1-u6-X05","asset":{"type":"geo","items":[{"w":282.0,"h":126.0,"pts":{},"show":[],"poly":[[[36,0],[108.0,0],[108.0,36.0],[36,36.0]],[[36,90.0],[108.0,90.0],[108.0,126.0],[36,126.0]],[[36,36.0],[108.0,36.0],[108.0,90.0],[36,90.0]],[[108.0,36.0],[144.0,36.0],[144.0,90.0],[108.0,90.0]],[[144.0,36.0],[216.0,36.0],[216.0,90.0],[144.0,90.0]],[[216.0,36.0],[252.0,36.0],[252.0,90.0],[216.0,90.0]]],"lab":[[[72.0,-10],"4 cm"],[[14,18.0],"2 cm"],[[276.0,63.0],"3 cm"],[[126.0,26.0],"2 cm"],[[180.0,26.0],"4 cm"],[[234.0,26.0],"2 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 5 cm, 세로 3 cm, 높이 4 cm인 직육면체의 겉넓이를 두 밑면과 옆면으로 나누어 구하면 몇 cm²인가요? 숫자로 쓰세요.","answer":["94"],"explanation":["두 밑면은 5 × 3 × 2 = 30(cm²)예요.","옆면의 가로는 한 밑면의 둘레 5 + 3 + 5 + 3 = 16, 옆면은 16 × 4 = 64(cm²)예요.","겉넓이는 30 + 64 = 94(cm²)예요."],"asset":{"type":"geo","items":[{"w":336.0,"h":168.7,"pts":{},"show":[],"poly":[[[36,0],[120.4,0],[120.4,50.6],[36,50.6]],[[36,118.1],[120.4,118.1],[120.4,168.7],[36,168.7]],[[36,50.6],[120.4,50.6],[120.4,118.1],[36,118.1]],[[120.4,50.6],[171.0,50.6],[171.0,118.1],[120.4,118.1]],[[171.0,50.6],[255.4,50.6],[255.4,118.1],[171.0,118.1]],[[255.4,50.6],[306.0,50.6],[306.0,118.1],[255.4,118.1]]],"lab":[[[78.2,-10],"5 cm"],[[14,25.3],"3 cm"],[[330.0,84.3],"4 cm"],[[145.7,40.6],"3 cm"],[[213.2,40.6],"5 cm"],[[280.7,40.6],"3 cm"]]}],"tag":false}},{"stem":"가로 6 cm, 세로 2 cm, 높이 5 cm인 직육면체의 겉넓이를 두 밑면과 옆면으로 나누어 구하면 몇 cm²인가요? 숫자로 쓰세요.","answer":["104"],"explanation":["두 밑면은 6 × 2 × 2 = 24(cm²)예요.","옆면의 가로는 한 밑면의 둘레 6 + 2 + 6 + 2 = 16, 옆면은 16 × 5 = 80(cm²)예요.","겉넓이는 24 + 80 = 104(cm²)예요."],"asset":{"type":"geo","items":[{"w":336.0,"h":152.0,"pts":{},"show":[],"poly":[[[36,0],[137.2,0],[137.2,33.8],[36,33.8]],[[36,118.2],[137.2,118.2],[137.2,152.0],[36,152.0]],[[36,33.8],[137.2,33.8],[137.2,118.2],[36,118.2]],[[137.2,33.8],[171.0,33.8],[171.0,118.2],[137.2,118.2]],[[171.0,33.8],[272.2,33.8],[272.2,118.2],[171.0,118.2]],[[272.2,33.8],[306.0,33.8],[306.0,118.2],[272.2,118.2]]],"lab":[[[86.6,-10],"6 cm"],[[14,16.9],"2 cm"],[[330.0,76.0],"5 cm"],[[154.1,23.8],"2 cm"],[[221.6,23.8],"6 cm"],[[289.1,23.8],"2 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L03_basic#8','math',6,1,'u6','L03','g6_1_math_u6_L03_basic','lesson_basic','M6-1-u6-C3',2,'sa','auto','한 모서리가 5 cm인 정육면체의 겉넓이는 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u6-C3","difficulty":2,"kind":"sa","stem":"한 모서리가 5 cm인 정육면체의 겉넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["150"],"explanation":["정육면체는 여섯 면이 모두 합동인 정사각형이에요.","한 면은 5 × 5 = 25, 여섯 면은 25 × 6 = 150이에요.","그래서 150 cm²예요."],"mis":"M6-1-u6-X06","asset":{"type":"geo","items":[{"w":216.0,"h":190.0,"pts":{"ㄱ":[60.0,0,"nw"],"ㄹ":[180.0,0,"ne"],"ㄴ":[0,60.0,"w"],"ㄷ":[120.0,60.0,"sw"],"ㅁ":[60.0,120.0,"ne"],"ㅇ":[180.0,120.0,"e"],"ㅂ":[0,180.0,"sw"],"ㅅ":[120.0,180.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[60.0,193.0],"5 cm"],[[172.0,156.0],"5 cm"],[[206.0,60.0],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"한 모서리가 4 cm인 정육면체의 겉넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["96"],"explanation":["정육면체는 여섯 면이 모두 합동인 정사각형이에요.","한 면은 4 × 4 = 16, 여섯 면은 16 × 6 = 96이에요.","그래서 96 cm²예요."],"asset":{"type":"geo","items":[{"w":180.0,"h":154.0,"pts":{"ㄱ":[48.0,0,"nw"],"ㄹ":[144.0,0,"ne"],"ㄴ":[0,48.0,"w"],"ㄷ":[96.0,48.0,"sw"],"ㅁ":[48.0,96.0,"ne"],"ㅇ":[144.0,96.0,"e"],"ㅂ":[0,144.0,"sw"],"ㅅ":[96.0,144.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[48.0,157.0],"4 cm"],[[142.0,126.0],"4 cm"],[[170.0,48.0],"4 cm"]]}],"tag":false}},{"stem":"한 모서리가 6 cm인 정육면체의 겉넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["216"],"explanation":["정육면체는 여섯 면이 모두 합동인 정사각형이에요.","한 면은 6 × 6 = 36, 여섯 면은 36 × 6 = 216이에요.","그래서 216 cm²예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":200.0,"pts":{"ㄱ":[63.3,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,63.3,"w"],"ㄷ":[126.7,63.3,"sw"],"ㅁ":[63.3,126.7,"ne"],"ㅇ":[190.0,126.7,"e"],"ㅂ":[0,190.0,"sw"],"ㅅ":[126.7,190.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[63.4,203.0],"6 cm"],[[180.3,164.3],"6 cm"],[[216.0,63.4],"6 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L03_basic#9','math',6,1,'u6','L03','g6_1_math_u6_L03_basic','lesson_basic','M6-1-u6-C3',2,'ox','auto','겉넓이가 작은 상자일수록 포장지가 덜 들어요.',ARRAY['M6-1-u6-X01']::text[],true,'{"seq":9,"concept":"M6-1-u6-C3","difficulty":2,"kind":"ox","stem":"겉넓이가 작은 상자일수록 포장지가 덜 들어요.","answer":"O","reason_options":[{"t":"포장지의 양은 겉넓이와 같기 때문에","correct":true},{"t":"포장지의 양은 상자의 높이로만 정해지기 때문에","mis":"M6-1-u6-X01"}],"mis":"M6-1-u6-X01","explanation":["겉넓이 = 두 밑면 + 옆면이고, 옆면의 가로는 한 밑면의 둘레예요.","정육면체는 한 면의 넓이 × 6이에요.","겉넓이가 작을수록 포장지가 덜 들어요."],"variant_rule":{"alt":[{"stem":"한 모서리가 2배가 되면 정육면체의 겉넓이도 2배가 돼요.","answer":"X","reason_options":[{"t":"한 면의 넓이가 2 × 2 = 4배가 되어 겉넓이도 4배가 되기 때문에","correct":true},{"t":"모서리가 2배면 무엇이든 2배가 되기 때문에","mis":"M6-1-u6-X18"}],"explanation":["겉넓이 = 두 밑면 + 옆면이고, 옆면의 가로는 한 밑면의 둘레예요.","정육면체는 한 면의 넓이 × 6이에요.","겉넓이가 작을수록 포장지가 덜 들어요."]},{"stem":"겉넓이는 두 밑면의 넓이와 옆면의 넓이를 더해서 구할 수 있어요.","answer":"O","reason_options":[{"t":"두 밑면과 옆면 네 개가 겉면 여섯 면 전부이기 때문에","correct":true},{"t":"옆면은 겉면이 아니기 때문에","mis":"M6-1-u6-X03"}],"explanation":["겉넓이 = 두 밑면 + 옆면이고, 옆면의 가로는 한 밑면의 둘레예요.","정육면체는 한 면의 넓이 × 6이에요.","겉넓이가 작을수록 포장지가 덜 들어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L03_basic#10','math',6,1,'u6','L03','g6_1_math_u6_L03_basic','lesson_basic','M6-1-u6-C3',3,'error','auto','가로 4 cm, 세로 2 cm, 높이 3 cm인 직육면체의 겉넓이를 두 밑면과 옆면으로 구했어요. 잘못 구한 친구는 누구인가요?',ARRAY['M6-1-u6-X05','M6-1-u6-X18']::text[],true,'{"seq":10,"concept":"M6-1-u6-C3","difficulty":3,"kind":"error","stem":"가로 4 cm, 세로 2 cm, 높이 3 cm인 직육면체의 겉넓이를 두 밑면과 옆면으로 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"하린 — 「옆면의 가로는 한 변 4 cm라서 옆면은 4 × 3 = 12(cm²)야.」","correct":true,"mis_target":"M6-1-u6-X05"},{"t":"도윤 — 「두 밑면은 4 × 2 × 2 = 16(cm²)야.」","mis":"M6-1-u6-X18"},{"t":"서아 — 「옆면의 가로는 4 + 2 + 4 + 2 = 12(cm)야.」","mis":"M6-1-u6-X18"}],"explanation":["옆면을 펼친 직사각형의 가로는 한 밑면의 둘레예요.","4 + 2 + 4 + 2 = 12, 옆면은 12 × 3 = 36(cm²)예요.","하린은 둘레가 아니라 한 변만 썼어요."],"asset":{"type":"geo","items":[{"w":282.0,"h":126.0,"pts":{},"show":[],"poly":[[[36,0],[108.0,0],[108.0,36.0],[36,36.0]],[[36,90.0],[108.0,90.0],[108.0,126.0],[36,126.0]],[[36,36.0],[108.0,36.0],[108.0,90.0],[36,90.0]],[[108.0,36.0],[144.0,36.0],[144.0,90.0],[108.0,90.0]],[[144.0,36.0],[216.0,36.0],[216.0,90.0],[144.0,90.0]],[[216.0,36.0],[252.0,36.0],[252.0,90.0],[216.0,90.0]]],"lab":[[[72.0,-10],"4 cm"],[[14,18.0],"2 cm"],[[276.0,63.0],"3 cm"],[[126.0,26.0],"2 cm"],[[180.0,26.0],"4 cm"],[[234.0,26.0],"2 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 5 cm, 세로 3 cm, 높이 4 cm인 직육면체의 겉넓이를 두 밑면과 옆면으로 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"수아 — 「옆면의 가로는 한 변 5 cm라서 옆면은 5 × 4 = 20(cm²)야.」","correct":true,"mis_target":"M6-1-u6-X05"},{"t":"예준 — 「두 밑면은 5 × 3 × 2 = 30(cm²)야.」","mis":"M6-1-u6-X18"},{"t":"나린 — 「옆면의 가로는 5 + 3 + 5 + 3 = 16(cm)야.」","mis":"M6-1-u6-X18"}],"explanation":["옆면을 펼친 직사각형의 가로는 한 밑면의 둘레예요.","5 + 3 + 5 + 3 = 16, 옆면은 16 × 4 = 64(cm²)예요.","수아는 둘레가 아니라 한 변만 썼어요."],"asset":{"type":"geo","items":[{"w":336.0,"h":168.7,"pts":{},"show":[],"poly":[[[36,0],[120.4,0],[120.4,50.6],[36,50.6]],[[36,118.1],[120.4,118.1],[120.4,168.7],[36,168.7]],[[36,50.6],[120.4,50.6],[120.4,118.1],[36,118.1]],[[120.4,50.6],[171.0,50.6],[171.0,118.1],[120.4,118.1]],[[171.0,50.6],[255.4,50.6],[255.4,118.1],[171.0,118.1]],[[255.4,50.6],[306.0,50.6],[306.0,118.1],[255.4,118.1]]],"lab":[[[78.2,-10],"5 cm"],[[14,25.3],"3 cm"],[[330.0,84.3],"4 cm"],[[145.7,40.6],"3 cm"],[[213.2,40.6],"5 cm"],[[280.7,40.6],"3 cm"]]}],"tag":false}},{"stem":"가로 6 cm, 세로 2 cm, 높이 5 cm인 직육면체의 겉넓이를 두 밑면과 옆면으로 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"가온 — 「옆면의 가로는 한 변 6 cm라서 옆면은 6 × 5 = 30(cm²)야.」","correct":true,"mis_target":"M6-1-u6-X05"},{"t":"유진 — 「두 밑면은 6 × 2 × 2 = 24(cm²)야.」","mis":"M6-1-u6-X18"},{"t":"라온 — 「옆면의 가로는 6 + 2 + 6 + 2 = 16(cm)야.」","mis":"M6-1-u6-X18"}],"explanation":["옆면을 펼친 직사각형의 가로는 한 밑면의 둘레예요.","6 + 2 + 6 + 2 = 16, 옆면은 16 × 5 = 80(cm²)예요.","가온은 둘레가 아니라 한 변만 썼어요."],"asset":{"type":"geo","items":[{"w":336.0,"h":152.0,"pts":{},"show":[],"poly":[[[36,0],[137.2,0],[137.2,33.8],[36,33.8]],[[36,118.2],[137.2,118.2],[137.2,152.0],[36,152.0]],[[36,33.8],[137.2,33.8],[137.2,118.2],[36,118.2]],[[137.2,33.8],[171.0,33.8],[171.0,118.2],[137.2,118.2]],[[171.0,33.8],[272.2,33.8],[272.2,118.2],[171.0,118.2]],[[272.2,33.8],[306.0,33.8],[306.0,118.2],[272.2,118.2]]],"lab":[[[86.6,-10],"6 cm"],[[14,16.9],"2 cm"],[[330.0,76.0],"5 cm"],[[154.1,23.8],"2 cm"],[[221.6,23.8],"6 cm"],[[289.1,23.8],"2 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
