INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L03_challenge#2','math',6,1,'u6','L03','g6_1_math_u6_L03_challenge','lesson_challenge','M6-1-u6-C3',2,'sa','auto','겉넓이가 294 cm²인 정육면체가 있어요. 한 면의 넓이는 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u6-C3","difficulty":2,"kind":"sa","stem":"겉넓이가 294 cm²인 정육면체가 있어요. 한 면의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["49"],"explanation":["정육면체는 여섯 면의 넓이가 모두 같아요.","294 ÷ 6 = 49예요.","그래서 한 면은 49 cm²예요."],"mis":"M6-1-u6-X06","variant_rule":{"alt":[{"stem":"겉넓이가 150 cm²인 정육면체가 있어요. 한 면의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["정육면체는 여섯 면의 넓이가 모두 같아요.","150 ÷ 6 = 25예요.","그래서 한 면은 25 cm²예요."]},{"stem":"겉넓이가 384 cm²인 정육면체가 있어요. 한 면의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["64"],"explanation":["정육면체는 여섯 면의 넓이가 모두 같아요.","384 ÷ 6 = 64예요.","그래서 한 면은 64 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
