INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L03_challenge#5','math',6,1,'u6','L03','g6_1_math_u6_L03_challenge','lesson_challenge','M6-1-u6-C3',3,'sa','auto','가로 8 cm, 세로 6 cm, 높이 4 cm인 뚜껑 없는 상자의 겉면(안쪽은 빼고)에 색종이를 붙여요. 붙일 넓이는 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u6-C3","difficulty":3,"kind":"sa","stem":"가로 8 cm, 세로 6 cm, 높이 4 cm인 뚜껑 없는 상자의 겉면(안쪽은 빼고)에 색종이를 붙여요. 붙일 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["160"],"explanation":["뚜껑이 없으니 밑면은 하나뿐이에요: 8 × 6 = 48(cm²).","옆면은 한 밑면의 둘레 28과 높이 4를 곱해 28 × 4 = 112(cm²)예요.","48 + 112 = 160이므로 160 cm²예요."],"mis":"M6-1-u6-X03","asset":{"type":"geo","items":[{"w":226.0,"h":130.9,"pts":{"ㄱ":[51.8,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,51.8,"w"],"ㄷ":[138.2,51.8,"sw"],"ㅁ":[51.8,69.1,"ne"],"ㅇ":[190.0,69.1,"e"],"ㅂ":[0,120.9,"sw"],"ㅅ":[138.2,120.9,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[69.1,133.9],"8 cm"],[[186.1,101.0],"6 cm"],[[216.0,34.5],"4 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 10 cm, 세로 5 cm, 높이 3 cm인 뚜껑 없는 상자의 겉면(안쪽은 빼고)에 색종이를 붙여요. 붙일 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["140"],"explanation":["뚜껑이 없으니 밑면은 하나뿐이에요: 10 × 5 = 50(cm²).","옆면은 한 밑면의 둘레 30과 높이 3을 곱해 30 × 3 = 90(cm²)예요.","50 + 90 = 140이므로 140 cm²예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":93.6,"pts":{"ㄱ":[38.0,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,38.0,"w"],"ㄷ":[152.0,38.0,"sw"],"ㅁ":[38.0,45.6,"ne"],"ㅇ":[190.0,45.6,"e"],"ㅂ":[0,83.6,"sw"],"ㅅ":[152.0,83.6,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[76.0,96.6],"10 cm"],[[193.0,70.6],"5 cm"],[[216.0,22.8],"3 cm"]]}],"tag":false}},{"stem":"가로 9 cm, 세로 6 cm, 높이 5 cm인 뚜껑 없는 상자의 겉면(안쪽은 빼고)에 색종이를 붙여요. 붙일 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["204"],"explanation":["뚜껑이 없으니 밑면은 하나뿐이에요: 9 × 6 = 54(cm²).","옆면은 한 밑면의 둘레 30과 높이 5를 곱해 30 × 5 = 150(cm²)예요.","54 + 150 = 204이므로 204 cm²예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":136.7,"pts":{"ㄱ":[47.5,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,47.5,"w"],"ㄷ":[142.5,47.5,"sw"],"ㅁ":[47.5,79.2,"ne"],"ㅇ":[190.0,79.2,"e"],"ㅂ":[0,126.7,"sw"],"ㅅ":[142.5,126.7,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[71.2,139.7],"9 cm"],[[188.2,109.0],"6 cm"],[[216.0,39.6],"5 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L03_challenge#6','math',6,1,'u6','L03','g6_1_math_u6_L03_challenge','lesson_challenge','M6-1-u6-C3',3,'error','auto','가로 10 cm, 세로 7 cm, 높이 4 cm인 직육면체의 겉넓이를 두 밑면과 옆면으로 구했어요. 잘못 구한 친구는 누구인가요?',ARRAY['M6-1-u6-X05','M6-1-u6-X18']::text[],true,'{"seq":6,"concept":"M6-1-u6-C3","difficulty":3,"kind":"error","stem":"가로 10 cm, 세로 7 cm, 높이 4 cm인 직육면체의 겉넓이를 두 밑면과 옆면으로 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"수아 — 「옆면의 가로는 한 변 10 cm라서 옆면은 10 × 4 = 40(cm²)야.」","correct":true,"mis_target":"M6-1-u6-X05"},{"t":"예준 — 「두 밑면은 10 × 7 × 2 = 140(cm²)야.」","mis":"M6-1-u6-X18"},{"t":"나린 — 「옆면의 가로는 10 + 7 + 10 + 7 = 34(cm)야.」","mis":"M6-1-u6-X18"}],"explanation":["옆면을 펼친 직사각형의 가로는 한 밑면의 둘레예요.","10 + 7 + 10 + 7 = 34, 옆면은 34 × 4 = 136(cm²)예요.","수아는 둘레가 아니라 한 변만 썼어요."],"asset":{"type":"geo","items":[{"w":336.0,"h":143.0,"pts":{},"show":[],"poly":[[[36,0],[115.4,0],[115.4,55.6],[36,55.6]],[[36,87.4],[115.4,87.4],[115.4,143.0],[36,143.0]],[[36,55.6],[115.4,55.6],[115.4,87.4],[36,87.4]],[[115.4,55.6],[171.0,55.6],[171.0,87.4],[115.4,87.4]],[[171.0,55.6],[250.4,55.6],[250.4,87.4],[171.0,87.4]],[[250.4,55.6],[306.0,55.6],[306.0,87.4],[250.4,87.4]]],"lab":[[[75.7,-10],"10 cm"],[[14,27.8],"7 cm"],[[330.0,71.5],"4 cm"],[[143.2,45.6],"7 cm"],[[210.7,45.6],"10 cm"],[[278.2,45.6],"7 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 8 cm, 세로 5 cm, 높이 6 cm인 직육면체의 겉넓이를 두 밑면과 옆면으로 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"가온 — 「옆면의 가로는 한 변 8 cm라서 옆면은 8 × 6 = 48(cm²)야.」","correct":true,"mis_target":"M6-1-u6-X05"},{"t":"유진 — 「두 밑면은 8 × 5 × 2 = 80(cm²)야.」","mis":"M6-1-u6-X18"},{"t":"라온 — 「옆면의 가로는 8 + 5 + 8 + 5 = 26(cm)야.」","mis":"M6-1-u6-X18"}],"explanation":["옆면을 펼친 직사각형의 가로는 한 밑면의 둘레예요.","8 + 5 + 8 + 5 = 26, 옆면은 26 × 6 = 156(cm²)예요.","가온은 둘레가 아니라 한 변만 썼어요."],"asset":{"type":"geo","items":[{"w":336.0,"h":166.1,"pts":{},"show":[],"poly":[[[36,0],[119.1,0],[119.1,51.9],[36,51.9]],[[36,114.2],[119.1,114.2],[119.1,166.1],[36,166.1]],[[36,51.9],[119.1,51.9],[119.1,114.2],[36,114.2]],[[119.1,51.9],[171.0,51.9],[171.0,114.2],[119.1,114.2]],[[171.0,51.9],[254.1,51.9],[254.1,114.2],[171.0,114.2]],[[254.1,51.9],[306.0,51.9],[306.0,114.2],[254.1,114.2]]],"lab":[[[77.5,-10],"8 cm"],[[14,25.9],"5 cm"],[[330.0,83.0],"6 cm"],[[145.1,41.9],"5 cm"],[[212.6,41.9],"8 cm"],[[280.1,41.9],"5 cm"]]}],"tag":false}},{"stem":"가로 12 cm, 세로 4 cm, 높이 5 cm인 직육면체의 겉넓이를 두 밑면과 옆면으로 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"여울 — 「옆면의 가로는 한 변 12 cm라서 옆면은 12 × 5 = 60(cm²)야.」","correct":true,"mis_target":"M6-1-u6-X05"},{"t":"시우 — 「두 밑면은 12 × 4 × 2 = 96(cm²)야.」","mis":"M6-1-u6-X18"},{"t":"은우 — 「옆면의 가로는 12 + 4 + 12 + 4 = 32(cm)야.」","mis":"M6-1-u6-X18"}],"explanation":["옆면을 펼친 직사각형의 가로는 한 밑면의 둘레예요.","12 + 4 + 12 + 4 = 32, 옆면은 32 × 5 = 160(cm²)예요.","여울은 둘레가 아니라 한 변만 썼어요."],"asset":{"type":"geo","items":[{"w":336.0,"h":109.8,"pts":{},"show":[],"poly":[[[36,0],[137.2,0],[137.2,33.8],[36,33.8]],[[36,76.0],[137.2,76.0],[137.2,109.8],[36,109.8]],[[36,33.8],[137.2,33.8],[137.2,76.0],[36,76.0]],[[137.2,33.8],[171.0,33.8],[171.0,76.0],[137.2,76.0]],[[171.0,33.8],[272.2,33.8],[272.2,76.0],[171.0,76.0]],[[272.2,33.8],[306.0,33.8],[306.0,76.0],[272.2,76.0]]],"lab":[[[86.6,-10],"12 cm"],[[14,16.9],"4 cm"],[[330.0,54.9],"5 cm"],[[154.1,23.8],"4 cm"],[[221.6,23.8],"12 cm"],[[289.1,23.8],"4 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L03_challenge#7','math',6,1,'u6','L03','g6_1_math_u6_L03_challenge','lesson_challenge','M6-1-u6-C3',3,'mc','auto','정육면체의 겉넓이를 바르게 구한 식은 어느 것인가요? (한 모서리 5 cm)',ARRAY['M6-1-u6-X06','M6-1-u6-X04']::text[],true,'{"seq":7,"concept":"M6-1-u6-C3","difficulty":3,"kind":"mc","stem":"정육면체의 겉넓이를 바르게 구한 식은 어느 것인가요? (한 모서리 5 cm)","options":[{"t":"5 × 5 × 6","correct":true},{"t":"5 × 5 × 4","mis":"M6-1-u6-X06"},{"t":"5 × 6","mis":"M6-1-u6-X06"},{"t":"5 × 5 × 2","mis":"M6-1-u6-X04"}],"explanation":["정육면체는 여섯 면이 모두 합동인 정사각형이에요.","그래서 한 면의 넓이만 구해 6배 하면 겉넓이예요.","정답은 「5 × 5 × 6」이에요."],"variant_rule":{"alt":[{"stem":"정육면체의 겉넓이를 한 면의 넓이의 6배로 구할 수 있는 까닭은 무엇인가요?","options":[{"t":"여섯 면이 모두 합동인 정사각형이라 넓이가 같기 때문에","correct":true},{"t":"보이는 면이 여섯 개이기 때문에","mis":"M6-1-u6-X03"},{"t":"모서리가 여섯 개이기 때문에","mis":"M6-1-u6-X06"},{"t":"옆면이 여섯 개이기 때문에","mis":"M6-1-u6-X05"}],"explanation":["정육면체는 여섯 면이 모두 합동인 정사각형이에요.","그래서 한 면의 넓이만 구해 6배 하면 겉넓이예요.","정답은 「여섯 면이 모두 합동인 정사각형이라 넓이가 같기 때문에」예요."]},{"stem":"정육면체의 겉넓이를 구하는 바른 방법은 어느 것인가요?","options":[{"t":"한 면의 넓이 × 6","correct":true},{"t":"한 면의 넓이 × 4","mis":"M6-1-u6-X06"},{"t":"한 모서리 × 6","mis":"M6-1-u6-X06"},{"t":"한 면의 넓이 × 2","mis":"M6-1-u6-X04"}],"explanation":["정육면체는 여섯 면이 모두 합동인 정사각형이에요.","그래서 한 면의 넓이만 구해 6배 하면 겉넓이예요.","정답은 「한 면의 넓이 × 6」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L03_challenge#8','math',6,1,'u6','L03','g6_1_math_u6_L03_challenge','lesson_challenge','M6-1-u6-C3',4,'sa','auto','겉넓이가 294 cm²인 정육면체가 있어요. 한 모서리는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u6-C3","difficulty":4,"kind":"sa","stem":"겉넓이가 294 cm²인 정육면체가 있어요. 한 모서리는 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["한 면의 넓이는 294 ÷ 6 = 49예요.","같은 수를 두 번 곱해 49가 되는 수는 7 × 7 = 49이므로 7이에요.","그래서 한 모서리는 7 cm예요."],"mis":"M6-1-u6-X06","variant_rule":{"alt":[{"stem":"겉넓이가 486 cm²인 정육면체가 있어요. 한 모서리는 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["한 면의 넓이는 486 ÷ 6 = 81이에요.","같은 수를 두 번 곱해 81이 되는 수는 9 × 9 = 81이므로 9예요.","그래서 한 모서리는 9 cm예요."]},{"stem":"겉넓이가 864 cm²인 정육면체가 있어요. 한 모서리는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["한 면의 넓이는 864 ÷ 6 = 144예요.","같은 수를 두 번 곱해 144가 되는 수는 12 × 12 = 144이므로 12예요.","그래서 한 모서리는 12 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L03_challenge#9','math',6,1,'u6','L03','g6_1_math_u6_L03_challenge','lesson_challenge','M6-1-u6-C3',4,'sa','auto','정육면체의 한 모서리를 2배로 늘이면 겉넓이는 처음의 몇 배가 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u6-C3","difficulty":4,"kind":"sa","stem":"정육면체의 한 모서리를 2배로 늘이면 겉넓이는 처음의 몇 배가 되나요? 숫자로 쓰세요.","answer":["4"],"explanation":["한 모서리 2 cm일 때 겉넓이는 2 × 2 × 6 = 24(cm²)예요.","2배인 4 cm일 때는 4 × 4 × 6 = 96(cm²)예요.","96 ÷ 24 = 4이므로 4배예요. 한 면의 넓이가 2 × 2 = 4배가 되기 때문이에요."],"mis":"M6-1-u6-X06","variant_rule":{"alt":[{"stem":"정육면체의 한 모서리를 3배로 늘이면 겉넓이는 처음의 몇 배가 되나요? 숫자로 쓰세요.","answer":["9"],"explanation":["한 모서리 2 cm일 때 겉넓이는 2 × 2 × 6 = 24(cm²)예요.","3배인 6 cm일 때는 6 × 6 × 6 = 216(cm²)예요.","216 ÷ 24 = 9이므로 9배예요. 한 면의 넓이가 3 × 3 = 9배가 되기 때문이에요."]},{"stem":"정육면체의 한 모서리를 4배로 늘이면 겉넓이는 처음의 몇 배가 되나요? 숫자로 쓰세요.","answer":["16"],"explanation":["한 모서리 2 cm일 때 겉넓이는 2 × 2 × 6 = 24(cm²)예요.","4배인 8 cm일 때는 8 × 8 × 6 = 384(cm²)예요.","384 ÷ 24 = 16이므로 16배예요. 한 면의 넓이가 4 × 4 = 16배가 되기 때문이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L03_challenge#10','math',6,1,'u6','L03','g6_1_math_u6_L03_challenge','lesson_challenge','M6-1-u6-C3',4,'essay','teacher','가로 20 cm, 세로 15 cm, 높이 4 cm인 상자 가와 가로 10 cm, 세로 15 cm, 높이 8 cm인 상자 나를 포장지로 감싸요. 두 상자의 겉넓이를 두 밑면과 옆면으로 나누어 구하고, 포장지가 덜 드는 상자를 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u6-C3","difficulty":4,"kind":"essay","stem":"가로 20 cm, 세로 15 cm, 높이 4 cm인 상자 가와 가로 10 cm, 세로 15 cm, 높이 8 cm인 상자 나를 포장지로 감싸요. 두 상자의 겉넓이를 두 밑면과 옆면으로 나누어 구하고, 포장지가 덜 드는 상자를 써 보세요.","answer_guide":{"answer":"예: 가는 두 밑면 20 × 15 × 2 = 600, 옆면 둘레 20 + 15 + 20 + 15 = 70, 70 × 4 = 280, 600 + 280 = 880(cm²). 나는 두 밑면 10 × 15 × 2 = 300, 옆면 둘레 10 + 15 + 10 + 15 = 50, 50 × 8 = 400, 300 + 400 = 700(cm²). 나의 겉넓이가 더 작으므로 나가 포장지가 덜 든다.","scoring_points":["가의 겉넓이 880 cm²를 구했는가","나의 겉넓이 700 cm²를 구했는가","옆면의 가로를 둘레로 쓰고 나라고 답했는가"]},"explanation":["가는 600 + 280 = 880이에요.","나는 300 + 400 = 700이에요.","겉넓이가 작은 나가 포장지가 덜 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L04_basic#1','math',6,1,'u6','L04','g6_1_math_u6_L04_basic','lesson_basic','M6-1-u6-C4',1,'mc','auto','한 모서리가 1 cm인 정육면체의 부피를 무엇이라고 하나요?',ARRAY['M6-1-u6-X02']::text[],true,'{"seq":1,"concept":"M6-1-u6-C4","difficulty":1,"kind":"mc","stem":"한 모서리가 1 cm인 정육면체의 부피를 무엇이라고 하나요?","options":[{"t":"1 cm³","correct":true},{"t":"1 cm²","mis":"M6-1-u6-X02"},{"t":"1 cm","mis":"M6-1-u6-X02"},{"t":"3 cm","mis":"M6-1-u6-X02"}],"explanation":["부피의 표준 단위로 한 모서리가 1 cm인 정육면체를 써요.","그 부피를 1 cm³라 쓰고 「1 세제곱센티미터」라고 읽어요.","정답은 「1 cm³」예요."],"variant_rule":{"alt":[{"stem":"「1 cm³」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"1 세제곱센티미터","correct":true},{"t":"1 제곱센티미터","mis":"M6-1-u6-X02"},{"t":"1 센티미터","mis":"M6-1-u6-X02"},{"t":"3 센티미터","mis":"M6-1-u6-X02"}],"explanation":["부피의 표준 단위로 한 모서리가 1 cm인 정육면체를 써요.","그 부피를 1 cm³라 쓰고 「1 세제곱센티미터」라고 읽어요.","정답은 「1 세제곱센티미터」예요."]},{"stem":"1 cm³는 어떤 정육면체의 부피인가요?","options":[{"t":"한 모서리가 1 cm인 정육면체","correct":true},{"t":"한 면의 넓이가 6 cm²인 정육면체","mis":"M6-1-u6-X02"},{"t":"모든 모서리의 길이의 합이 1 cm인 정육면체","mis":"M6-1-u6-X18"},{"t":"한 모서리가 3 cm인 정육면체","mis":"M6-1-u6-X02"}],"explanation":["부피의 표준 단위로 한 모서리가 1 cm인 정육면체를 써요.","그 부피를 1 cm³라 쓰고 「1 세제곱센티미터」라고 읽어요.","정답은 「한 모서리가 1 cm인 정육면체」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L04_basic#2','math',6,1,'u6','L04','g6_1_math_u6_L04_basic','lesson_basic','M6-1-u6-C4',1,'sa','auto','부피가 1 cm³인 쌓기나무 5개로 쌓은 도형의 부피는 몇 cm³인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u6-C4","difficulty":1,"kind":"sa","stem":"부피가 1 cm³인 쌓기나무 5개로 쌓은 도형의 부피는 몇 cm³인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["1 cm³인 쌓기나무 한 개의 부피가 1 cm³예요.","5개이면 1 × 5 = 5예요.","그래서 5 cm³예요."],"mis":"M6-1-u6-X10","variant_rule":{"alt":[{"stem":"부피가 1 cm³인 쌓기나무 7개로 쌓은 도형의 부피는 몇 cm³인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["1 cm³인 쌓기나무 한 개의 부피가 1 cm³예요.","7개이면 1 × 7 = 7이에요.","그래서 7 cm³예요."]},{"stem":"부피가 1 cm³인 쌓기나무 9개로 쌓은 도형의 부피는 몇 cm³인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["1 cm³인 쌓기나무 한 개의 부피가 1 cm³예요.","9개이면 1 × 9 = 9예요.","그래서 9 cm³예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L04_basic#3','math',6,1,'u6','L04','g6_1_math_u6_L04_basic','lesson_basic','M6-1-u6-C4',1,'mc','auto','두 상자의 부피를 쌓기나무 개수로 비교할 수 있게 쌓은 방법은 어느 것인가요?',ARRAY['M6-1-u6-X08','M6-1-u6-X09']::text[],true,'{"seq":3,"concept":"M6-1-u6-C4","difficulty":1,"kind":"mc","stem":"두 상자의 부피를 쌓기나무 개수로 비교할 수 있게 쌓은 방법은 어느 것인가요?","options":[{"t":"크기가 같은 쌓기나무로 쌓는다","correct":true},{"t":"크기가 다른 쌓기나무로 쌓는다","mis":"M6-1-u6-X08"},{"t":"구슬로 채운다","mis":"M6-1-u6-X09"},{"t":"눈으로 어림해 본다","mis":"M6-1-u6-X08"}],"explanation":["부피를 개수로 비교하려면 같은 크기의 단위로 세어야 해요.","단위는 빈틈없이 채워지는 것이어야 해요.","정답은 「크기가 같은 쌓기나무로 쌓는다」예요."],"variant_rule":{"alt":[{"stem":"구슬로 상자를 채워서 부피를 잴 수 없는 까닭은 무엇인가요?","options":[{"t":"구슬 사이에 빈 공간이 생기기 때문에","correct":true},{"t":"구슬이 무겁기 때문에","mis":"M6-1-u6-X09"},{"t":"구슬이 둥글어 예쁘기 때문에","mis":"M6-1-u6-X09"},{"t":"구슬은 셀 수 없기 때문에","mis":"M6-1-u6-X09"}],"explanation":["부피를 개수로 비교하려면 같은 크기의 단위로 세어야 해요.","단위는 빈틈없이 채워지는 것이어야 해요.","정답은 「구슬 사이에 빈 공간이 생기기 때문에」예요."]},{"stem":"부피를 재는 단위로 알맞은 것은 어느 것인가요?","options":[{"t":"빈틈없이 쌓을 수 있는 같은 크기의 정육면체","correct":true},{"t":"크기가 제각각인 상자","mis":"M6-1-u6-X08"},{"t":"크기가 같은 구슬","mis":"M6-1-u6-X09"},{"t":"길이가 같은 막대","mis":"M6-1-u6-X02"}],"explanation":["부피를 개수로 비교하려면 같은 크기의 단위로 세어야 해요.","단위는 빈틈없이 채워지는 것이어야 해요.","정답은 「빈틈없이 쌓을 수 있는 같은 크기의 정육면체」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L04_basic#4','math',6,1,'u6','L04','g6_1_math_u6_L04_basic','lesson_basic','M6-1-u6-C4',1,'ox','auto','크기가 다른 쌓기나무로 쌓았어도 개수가 같으면 부피가 같아요.',ARRAY['M6-1-u6-X08']::text[],true,'{"seq":4,"concept":"M6-1-u6-C4","difficulty":1,"kind":"ox","stem":"크기가 다른 쌓기나무로 쌓았어도 개수가 같으면 부피가 같아요.","answer":"X","reason_options":[{"t":"쌓기나무의 크기가 다르면 같은 개수라도 부피가 다르기 때문에","correct":true},{"t":"개수가 같으면 언제나 부피가 같기 때문에","mis":"M6-1-u6-X08"}],"mis":"M6-1-u6-X08","explanation":["부피는 입체도형이 공간에서 차지하는 크기예요.","같은 크기의 단위(1 cm³)로 빈틈없이 세어야 비교할 수 있어요.","1 cm³ 쌓기나무의 개수가 곧 부피예요."],"variant_rule":{"alt":[{"stem":"부피가 1 cm³인 쌓기나무 12개로 쌓은 모양의 부피는 12 cm³예요.","answer":"O","reason_options":[{"t":"1 cm³ 쌓기나무의 개수가 곧 부피이기 때문에","correct":true},{"t":"쌓기나무의 개수와 부피는 관계가 없기 때문에","mis":"M6-1-u6-X10"}],"explanation":["부피는 입체도형이 공간에서 차지하는 크기예요.","같은 크기의 단위(1 cm³)로 빈틈없이 세어야 비교할 수 있어요.","1 cm³ 쌓기나무의 개수가 곧 부피예요."]},{"stem":"부피는 입체도형이 공간에서 차지하는 크기예요.","answer":"O","reason_options":[{"t":"부피는 담기는 공간의 크기를 나타내기 때문에","correct":true},{"t":"부피는 겉면의 넓이를 나타내기 때문에","mis":"M6-1-u6-X01"}],"explanation":["부피는 입체도형이 공간에서 차지하는 크기예요.","같은 크기의 단위(1 cm³)로 빈틈없이 세어야 비교할 수 있어요.","1 cm³ 쌓기나무의 개수가 곧 부피예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L04_basic#5','math',6,1,'u6','L04','g6_1_math_u6_L04_basic','lesson_basic','M6-1-u6-C4',2,'sa','auto','부피가 1 cm³인 쌓기나무로 빈틈없이 쌓은 직육면체예요. 부피는 몇 cm³인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u6-C4","difficulty":2,"kind":"sa","stem":"부피가 1 cm³인 쌓기나무로 빈틈없이 쌓은 직육면체예요. 부피는 몇 cm³인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["한 층에는 3 × 2 = 6개가 있어요.","2층이므로 6 × 2 = 12개예요.","그래서 부피는 12 cm³예요."],"mis":"M6-1-u6-X10","asset":{"type":"geo","items":[{"w":96.0,"h":72.0,"pts":{"ㄱ":[24.0,0,"nw"],"ㄹ":[96.0,0,"ne"],"ㄴ":[0,24.0,"w"],"ㄷ":[72.0,24.0,"sw"],"ㅁ":[24.0,48.0,"ne"],"ㅇ":[96.0,48.0,"e"],"ㅂ":[0,72.0,"sw"],"ㅅ":[72.0,72.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"],[[24.0,24.0],[24.0,72.0]],[[24.0,24.0],[48.0,0]],[[48.0,24.0],[48.0,72.0]],[[48.0,24.0],[72.0,0]],[[0,48.0],[72.0,48.0]],[[72.0,48.0],[96.0,24.0]],[[12.0,12.0],[84.0,12.0]],[[84.0,12.0],[84.0,60.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 부피가 1 cm³인 쌓기나무로 빈틈없이 쌓은 직육면체예요. 부피는 몇 cm³인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["한 층에는 4 × 2 = 8개가 있어요.","2층이므로 8 × 2 = 16개예요.","그래서 부피는 16 cm³예요."],"asset":{"type":"geo","items":[{"w":120.0,"h":72.0,"pts":{"ㄱ":[24.0,0,"nw"],"ㄹ":[120.0,0,"ne"],"ㄴ":[0,24.0,"w"],"ㄷ":[96.0,24.0,"sw"],"ㅁ":[24.0,48.0,"ne"],"ㅇ":[120.0,48.0,"e"],"ㅂ":[0,72.0,"sw"],"ㅅ":[96.0,72.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"],[[24.0,24.0],[24.0,72.0]],[[24.0,24.0],[48.0,0]],[[48.0,24.0],[48.0,72.0]],[[48.0,24.0],[72.0,0]],[[72.0,24.0],[72.0,72.0]],[[72.0,24.0],[96.0,0]],[[0,48.0],[96.0,48.0]],[[96.0,48.0],[120.0,24.0]],[[12.0,12.0],[108.0,12.0]],[[108.0,12.0],[108.0,60.0]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 부피가 1 cm³인 쌓기나무로 빈틈없이 쌓은 직육면체예요. 부피는 몇 cm³인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["한 층에는 3 × 3 = 9개가 있어요.","2층이므로 9 × 2 = 18개예요.","그래서 부피는 18 cm³예요."],"asset":{"type":"geo","items":[{"w":108.0,"h":84.0,"pts":{"ㄱ":[36.0,0,"nw"],"ㄹ":[108.0,0,"ne"],"ㄴ":[0,36.0,"w"],"ㄷ":[72.0,36.0,"sw"],"ㅁ":[36.0,48.0,"ne"],"ㅇ":[108.0,48.0,"e"],"ㅂ":[0,84.0,"sw"],"ㅅ":[72.0,84.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"],[[24.0,36.0],[24.0,84.0]],[[24.0,36.0],[60.0,0]],[[48.0,36.0],[48.0,84.0]],[[48.0,36.0],[84.0,0]],[[0,60.0],[72.0,60.0]],[[72.0,60.0],[108.0,24.0]],[[12.0,24.0],[84.0,24.0]],[[84.0,24.0],[84.0,72.0]],[[24.0,12.0],[96.0,12.0]],[[96.0,12.0],[96.0,60.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L04_basic#6','math',6,1,'u6','L04','g6_1_math_u6_L04_basic','lesson_basic','M6-1-u6-C4',2,'sa','auto','부피가 1 cm³인 쌓기나무를 한 층에 8개씩 2층으로 쌓았어요. 전체 부피는 몇 cm³인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u6-C4","difficulty":2,"kind":"sa","stem":"부피가 1 cm³인 쌓기나무를 한 층에 8개씩 2층으로 쌓았어요. 전체 부피는 몇 cm³인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["한 층에 8개, 2층이에요.","8 × 2 = 16개예요.","그래서 16 cm³예요."],"mis":"M6-1-u6-X10","variant_rule":{"alt":[{"stem":"부피가 1 cm³인 쌓기나무를 한 층에 6개씩 3층으로 쌓았어요. 전체 부피는 몇 cm³인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["한 층에 6개, 3층이에요.","6 × 3 = 18개예요.","그래서 18 cm³예요."]},{"stem":"부피가 1 cm³인 쌓기나무를 한 층에 9개씩 2층으로 쌓았어요. 전체 부피는 몇 cm³인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["한 층에 9개, 2층이에요.","9 × 2 = 18개예요.","그래서 18 cm³예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L04_basic#7','math',6,1,'u6','L04','g6_1_math_u6_L04_basic','lesson_basic','M6-1-u6-C4',2,'sa','auto','하린은 부피가 1 cm³인 쌓기나무 6개, 도윤은 같은 쌓기나무 7개로 모양을 만들었어요. 도윤이 만든 모양의 부피는 하린의 것보다 몇 cm³ 더 큰가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u6-C4","difficulty":2,"kind":"sa","stem":"하린은 부피가 1 cm³인 쌓기나무 6개, 도윤은 같은 쌓기나무 7개로 모양을 만들었어요. 도윤이 만든 모양의 부피는 하린의 것보다 몇 cm³ 더 큰가요? 숫자로 쓰세요.","answer":["1"],"explanation":["같은 1 cm³ 쌓기나무로 쌓았으니 개수가 곧 부피예요.","7 − 6 = 1이에요.","그래서 1 cm³ 더 커요."],"mis":"M6-1-u6-X18","variant_rule":{"alt":[{"stem":"수아는 부피가 1 cm³인 쌓기나무 9개, 예준은 같은 쌓기나무 12개로 모양을 만들었어요. 예준이 만든 모양의 부피는 수아의 것보다 몇 cm³ 더 큰가요? 숫자로 쓰세요.","answer":["3"],"explanation":["같은 1 cm³ 쌓기나무로 쌓았으니 개수가 곧 부피예요.","12 − 9 = 3이에요.","그래서 3 cm³ 더 커요."]},{"stem":"가온은 부피가 1 cm³인 쌓기나무 15개, 유진은 같은 쌓기나무 20개로 모양을 만들었어요. 유진이 만든 모양의 부피는 가온의 것보다 몇 cm³ 더 큰가요? 숫자로 쓰세요.","answer":["5"],"explanation":["같은 1 cm³ 쌓기나무로 쌓았으니 개수가 곧 부피예요.","20 − 15 = 5예요.","그래서 5 cm³ 더 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L04_basic#8','math',6,1,'u6','L04','g6_1_math_u6_L04_basic','lesson_basic','M6-1-u6-C4',2,'mc','auto','같은 크기의 쌓기나무로 필통 모양을 쌓았어요. 하린은 60개, 도윤은 54개, 서아는 72개를 썼어요. 부피가 가장 큰 필통을 쌓은 친구는 누구인가요?',ARRAY['M6-1-u6-X18','M6-1-u6-X08']::text[],true,'{"seq":8,"concept":"M6-1-u6-C4","difficulty":2,"kind":"mc","stem":"같은 크기의 쌓기나무로 필통 모양을 쌓았어요. 하린은 60개, 도윤은 54개, 서아는 72개를 썼어요. 부피가 가장 큰 필통을 쌓은 친구는 누구인가요?","options":[{"t":"서아","correct":true},{"t":"하린","mis":"M6-1-u6-X18"},{"t":"도윤","mis":"M6-1-u6-X18"},{"t":"모두 같아요","mis":"M6-1-u6-X08"}],"explanation":["크기가 같은 쌓기나무로 쌓았으니 개수로 부피를 비교할 수 있어요.","가장 큰 수는 72예요.","그래서 서아예요."],"variant_rule":{"alt":[{"stem":"같은 크기의 쌓기나무로 필통 모양을 쌓았어요. 수아는 48개, 예준은 56개, 나린은 52개를 썼어요. 부피가 가장 큰 필통을 쌓은 친구는 누구인가요?","options":[{"t":"예준","correct":true},{"t":"수아","mis":"M6-1-u6-X18"},{"t":"나린","mis":"M6-1-u6-X18"},{"t":"모두 같아요","mis":"M6-1-u6-X08"}],"explanation":["크기가 같은 쌓기나무로 쌓았으니 개수로 부피를 비교할 수 있어요.","가장 큰 수는 56이에요.","그래서 예준이에요."]},{"stem":"같은 크기의 쌓기나무로 필통 모양을 쌓았어요. 가온은 36개, 유진은 45개, 라온은 40개를 썼어요. 부피가 가장 큰 필통을 쌓은 친구는 누구인가요?","options":[{"t":"유진","correct":true},{"t":"가온","mis":"M6-1-u6-X18"},{"t":"라온","mis":"M6-1-u6-X18"},{"t":"모두 같아요","mis":"M6-1-u6-X08"}],"explanation":["크기가 같은 쌓기나무로 쌓았으니 개수로 부피를 비교할 수 있어요.","가장 큰 수는 45예요.","그래서 유진이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L04_basic#9','math',6,1,'u6','L04','g6_1_math_u6_L04_basic','lesson_basic','M6-1-u6-C4',2,'ox','auto','구슬로 상자를 가득 채우면 상자의 부피를 정확히 잴 수 있어요.',ARRAY['M6-1-u6-X09']::text[],true,'{"seq":9,"concept":"M6-1-u6-C4","difficulty":2,"kind":"ox","stem":"구슬로 상자를 가득 채우면 상자의 부피를 정확히 잴 수 있어요.","answer":"X","reason_options":[{"t":"구슬 사이에 빈 공간이 생기기 때문에","correct":true},{"t":"구슬은 크기가 모두 같기 때문에","mis":"M6-1-u6-X09"}],"mis":"M6-1-u6-X09","explanation":["부피는 입체도형이 공간에서 차지하는 크기예요.","같은 크기의 단위(1 cm³)로 빈틈없이 세어야 비교할 수 있어요.","1 cm³ 쌓기나무의 개수가 곧 부피예요."],"variant_rule":{"alt":[{"stem":"1 cm³는 한 모서리가 1 cm인 정육면체의 부피예요.","answer":"O","reason_options":[{"t":"부피의 표준 단위를 그렇게 정했기 때문에","correct":true},{"t":"한 면의 넓이가 1 cm²이면 무엇이든 1 cm³이기 때문에","mis":"M6-1-u6-X02"}],"explanation":["부피는 입체도형이 공간에서 차지하는 크기예요.","같은 크기의 단위(1 cm³)로 빈틈없이 세어야 비교할 수 있어요.","1 cm³ 쌓기나무의 개수가 곧 부피예요."]},{"stem":"크기가 다른 쌓기나무로 쌓았어도 개수가 같으면 부피가 같아요.","answer":"X","reason_options":[{"t":"쌓기나무의 크기가 다르면 같은 개수라도 부피가 다르기 때문에","correct":true},{"t":"개수가 같으면 언제나 부피가 같기 때문에","mis":"M6-1-u6-X08"}],"explanation":["부피는 입체도형이 공간에서 차지하는 크기예요.","같은 크기의 단위(1 cm³)로 빈틈없이 세어야 비교할 수 있어요.","1 cm³ 쌓기나무의 개수가 곧 부피예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L04_basic#10','math',6,1,'u6','L04','g6_1_math_u6_L04_basic','lesson_basic','M6-1-u6-C4',3,'error','auto','하린은 크기가 제각각인 쌓기나무 60개로, 도윤은 크기가 같은 쌓기나무 60개로 두 상자와 똑같은 모양을 쌓았어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u6-X08','M6-1-u6-X18']::text[],true,'{"seq":10,"concept":"M6-1-u6-C4","difficulty":3,"kind":"error","stem":"하린은 크기가 제각각인 쌓기나무 60개로, 도윤은 크기가 같은 쌓기나무 60개로 두 상자와 똑같은 모양을 쌓았어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아 — 「둘 다 60개이니 두 상자의 부피는 같아.」","correct":true,"mis_target":"M6-1-u6-X08"},{"t":"하린 — 「내 쌓기나무는 크기가 달라서 개수로 부피를 비교할 수 없어.」","mis":"M6-1-u6-X18"},{"t":"도윤 — 「같은 크기 쌓기나무여야 개수로 부피를 비교할 수 있어.」","mis":"M6-1-u6-X18"}],"explanation":["크기가 서로 다른 단위로 센 개수는 비교할 수 없어요.","하린의 60개와 도윤의 60개는 부피가 다를 수 있어요.","서아는 크기를 따지지 않고 개수만 보았어요."],"variant_rule":{"alt":[{"stem":"수아는 크기가 제각각인 쌓기나무 48개로, 예준은 크기가 같은 쌓기나무 48개로 두 상자와 똑같은 모양을 쌓았어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"나린 — 「둘 다 48개이니 두 상자의 부피는 같아.」","correct":true,"mis_target":"M6-1-u6-X08"},{"t":"수아 — 「내 쌓기나무는 크기가 달라서 개수로 부피를 비교할 수 없어.」","mis":"M6-1-u6-X18"},{"t":"예준 — 「같은 크기 쌓기나무여야 개수로 부피를 비교할 수 있어.」","mis":"M6-1-u6-X18"}],"explanation":["크기가 서로 다른 단위로 센 개수는 비교할 수 없어요.","수아의 48개와 예준의 48개는 부피가 다를 수 있어요.","나린은 크기를 따지지 않고 개수만 보았어요."]},{"stem":"가온은 크기가 제각각인 쌓기나무 36개로, 유진은 크기가 같은 쌓기나무 36개로 두 상자와 똑같은 모양을 쌓았어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라온 — 「둘 다 36개이니 두 상자의 부피는 같아.」","correct":true,"mis_target":"M6-1-u6-X08"},{"t":"가온 — 「내 쌓기나무는 크기가 달라서 개수로 부피를 비교할 수 없어.」","mis":"M6-1-u6-X18"},{"t":"유진 — 「같은 크기 쌓기나무여야 개수로 부피를 비교할 수 있어.」","mis":"M6-1-u6-X18"}],"explanation":["크기가 서로 다른 단위로 센 개수는 비교할 수 없어요.","가온의 36개와 유진의 36개는 부피가 다를 수 있어요.","라온은 크기를 따지지 않고 개수만 보았어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L04_challenge#1','math',6,1,'u6','L04','g6_1_math_u6_L04_challenge','lesson_challenge','M6-1-u6-C4',2,'mc','auto','부피를 비교하려고 할 때 1 cm³ 같은 표준 단위가 필요한 까닭은 무엇인가요?',ARRAY['M6-1-u6-X08','M6-1-u6-X09']::text[],true,'{"seq":1,"concept":"M6-1-u6-C4","difficulty":2,"kind":"mc","stem":"부피를 비교하려고 할 때 1 cm³ 같은 표준 단위가 필요한 까닭은 무엇인가요?","options":[{"t":"크기가 서로 다른 단위로 센 개수는 비교할 수 없기 때문에","correct":true},{"t":"개수가 많을수록 언제나 크기 때문에","mis":"M6-1-u6-X08"},{"t":"쌓기나무는 모두 1 cm³이기 때문에","mis":"M6-1-u6-X08"},{"t":"부피는 눈으로 볼 수 없기 때문에","mis":"M6-1-u6-X09"}],"explanation":["부피를 개수로 비교하려면 같은 크기의 단위로 세어야 해요.","단위는 빈틈없이 채워지는 것이어야 해요.","정답은 「크기가 서로 다른 단위로 센 개수는 비교할 수 없기 때문에」예요."],"variant_rule":{"alt":[{"stem":"구슬로 상자를 채워서 부피를 잴 수 없는 까닭은 무엇인가요?","options":[{"t":"구슬 사이에 빈 공간이 생기기 때문에","correct":true},{"t":"구슬이 무겁기 때문에","mis":"M6-1-u6-X09"},{"t":"구슬이 둥글어 예쁘기 때문에","mis":"M6-1-u6-X09"},{"t":"구슬은 셀 수 없기 때문에","mis":"M6-1-u6-X09"}],"explanation":["부피를 개수로 비교하려면 같은 크기의 단위로 세어야 해요.","단위는 빈틈없이 채워지는 것이어야 해요.","정답은 「구슬 사이에 빈 공간이 생기기 때문에」예요."]},{"stem":"부피를 재는 단위로 알맞은 것은 어느 것인가요?","options":[{"t":"빈틈없이 쌓을 수 있는 같은 크기의 정육면체","correct":true},{"t":"크기가 제각각인 상자","mis":"M6-1-u6-X08"},{"t":"크기가 같은 구슬","mis":"M6-1-u6-X09"},{"t":"길이가 같은 막대","mis":"M6-1-u6-X02"}],"explanation":["부피를 개수로 비교하려면 같은 크기의 단위로 세어야 해요.","단위는 빈틈없이 채워지는 것이어야 해요.","정답은 「빈틈없이 쌓을 수 있는 같은 크기의 정육면체」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L04_challenge#2','math',6,1,'u6','L04','g6_1_math_u6_L04_challenge','lesson_challenge','M6-1-u6-C4',2,'mc','auto','같은 크기의 쌓기나무로 필통 모양을 쌓았어요. 여울은 30개, 시우는 27개, 은우는 24개를 썼어요. 부피가 가장 작은 필통을 쌓은 친구는 누구인가요?',ARRAY['M6-1-u6-X18','M6-1-u6-X08']::text[],true,'{"seq":2,"concept":"M6-1-u6-C4","difficulty":2,"kind":"mc","stem":"같은 크기의 쌓기나무로 필통 모양을 쌓았어요. 여울은 30개, 시우는 27개, 은우는 24개를 썼어요. 부피가 가장 작은 필통을 쌓은 친구는 누구인가요?","options":[{"t":"은우","correct":true},{"t":"여울","mis":"M6-1-u6-X18"},{"t":"시우","mis":"M6-1-u6-X18"},{"t":"모두 같아요","mis":"M6-1-u6-X08"}],"explanation":["크기가 같은 쌓기나무로 쌓았으니 개수로 부피를 비교할 수 있어요.","가장 작은 수는 24예요.","그래서 은우예요."],"variant_rule":{"alt":[{"stem":"같은 크기의 쌓기나무로 필통 모양을 쌓았어요. 하린은 45개, 도윤은 50개, 서아는 42개를 썼어요. 부피가 가장 작은 필통을 쌓은 친구는 누구인가요?","options":[{"t":"서아","correct":true},{"t":"하린","mis":"M6-1-u6-X18"},{"t":"도윤","mis":"M6-1-u6-X18"},{"t":"모두 같아요","mis":"M6-1-u6-X08"}],"explanation":["크기가 같은 쌓기나무로 쌓았으니 개수로 부피를 비교할 수 있어요.","가장 작은 수는 42예요.","그래서 서아예요."]},{"stem":"같은 크기의 쌓기나무로 필통 모양을 쌓았어요. 수아는 64개, 예준은 60개, 나린은 72개를 썼어요. 부피가 가장 작은 필통을 쌓은 친구는 누구인가요?","options":[{"t":"예준","correct":true},{"t":"수아","mis":"M6-1-u6-X18"},{"t":"나린","mis":"M6-1-u6-X18"},{"t":"모두 같아요","mis":"M6-1-u6-X08"}],"explanation":["크기가 같은 쌓기나무로 쌓았으니 개수로 부피를 비교할 수 있어요.","가장 작은 수는 60이에요.","그래서 예준이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
