INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L04_challenge#4','math',6,1,'u6','L04','g6_1_math_u6_L04_challenge','lesson_challenge','M6-1-u6-C4',3,'mc','auto','부피가 1 cm³인 쌓기나무로 빈틈없이 쌓은 두 직육면체 ㉮와 ㉯예요. 바르게 비교한 것은 어느 것인가요?',ARRAY['M6-1-u6-X18','M6-1-u6-X10']::text[],true,'{"seq":4,"concept":"M6-1-u6-C4","difficulty":3,"kind":"mc","stem":"부피가 1 cm³인 쌓기나무로 빈틈없이 쌓은 두 직육면체 ㉮와 ㉯예요. 바르게 비교한 것은 어느 것인가요?","options":[{"t":"㉯가 4 cm³ 더 커요","correct":true},{"t":"㉮가 4 cm³ 더 커요","mis":"M6-1-u6-X18"},{"t":"두 부피는 같아요","mis":"M6-1-u6-X10"},{"t":"㉯가 8 cm³ 더 커요","mis":"M6-1-u6-X10"}],"explanation":["㉮는 3 × 2 = 6, 6 × 2 = 12(cm³)예요.","㉯는 2 × 2 = 4, 4 × 4 = 16(cm³)예요.","16 − 12 = 4이므로 ㉯가 4 cm³ 더 커요."],"asset":{"type":"geo","items":[{"w":72.0,"h":54.0,"pts":{"ㄱ":[18.0,0,"nw"],"ㄹ":[72.0,0,"ne"],"ㄴ":[0,18.0,"w"],"ㄷ":[54,18.0,"sw"],"ㅁ":[18.0,36,"ne"],"ㅇ":[72.0,36,"e"],"ㅂ":[0,54.0,"sw"],"ㅅ":[54,54.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"],[[18,18.0],[18,54.0]],[[18,18.0],[36.0,0]],[[36,18.0],[36,54.0]],[[36,18.0],[54.0,0]],[[0,36.0],[54,36.0]],[[54,36.0],[72.0,18]],[[9.0,9.0],[63.0,9.0]],[[63.0,9.0],[63.0,45.0]]]},{"w":54.0,"h":90.0,"pts":{"ㄱ":[18.0,0,"nw"],"ㄹ":[54.0,0,"ne"],"ㄴ":[0,18.0,"w"],"ㄷ":[36,18.0,"sw"],"ㅁ":[18.0,72,"ne"],"ㅇ":[54.0,72,"e"],"ㅂ":[0,90.0,"sw"],"ㅅ":[36,90.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"],[[18,18.0],[18,90.0]],[[18,18.0],[36.0,0]],[[0,36.0],[36,36.0]],[[36,36.0],[54.0,18]],[[0,54.0],[36,54.0]],[[36,54.0],[54.0,36]],[[0,72.0],[36,72.0]],[[36,72.0],[54.0,54]],[[9.0,9.0],[45.0,9.0]],[[45.0,9.0],[45.0,81.0]]]}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 부피가 1 cm³인 쌓기나무로 빈틈없이 쌓은 두 직육면체 ㉮와 ㉯예요. 바르게 비교한 것은 어느 것인가요?","options":[{"t":"㉯가 2 cm³ 더 커요","correct":true},{"t