],[45.0,0]],[[36,27.0],[36,81.0]],[[36,27.0],[63.0,0]],[[0,45.0],[54,45.0]],[[54,45.0],[81.0,18]],[[0,63.0],[54,63.0]],[[54,63.0],[81.0,36]],[[9.0,18.0],[63.0,18.0]],[[63.0,18.0],[63.0,72.0]],[[18.0,9.0],[72.0,9.0]],[[72.0,9.0],[72.0,63.0]]]},{"w":90.0,"h":72.0,"pts":{"ㄱ":[18.0,0,"nw"],"ㄹ":[90.0,0,"ne"],"ㄴ":[0,18.0,"w"],"ㄷ":[72,18.0,"sw"],"ㅁ":[18.0,54,"ne"],"ㅇ":[90.0,54,"e"],"ㅂ":[0,72.0,"sw"],"ㅅ":[72,72.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"],[[18,18.0],[18,72.0]],[[18,18.0],[36.0,0]],[[36,18.0],[36,72.0]],[[36,18.0],[54.0,0]],[[54,18.0],[54,72.0]],[[54,18.0],[72.0,0]],[[0,36.0],[72,36.0]],[[72,36.0],[90.0,18]],[[0,54.0],[72,54.0]],[[72,54.0],[90.0,36]],[[9.0,9.0],[81.0,9.0]],[[81.0,9.0],[81.0,63.0]]]}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L04_challenge#5','math',6,1,'u6','L04','g6_1_math_u6_L04_challenge','lesson_challenge','M6-1-u6-C4',3,'sa','auto','부피가 1 cm³인 쌓기나무를 한 층에 12개씩 3층으로 쌓았어요. 전체 부피는 몇 cm³인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u6-C4","difficulty":3,"kind":"sa","stem":"부피가 1 cm³인 쌓기나무를 한 층에 12개씩 3층으로 쌓았어요. 전체 부피는 몇 cm³인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["한 층에 12개, 3층이에요.","12 × 3 = 36개예요.","그래서 36 cm³예요."],"mis":"M6-1-u6-X10","variant_rule":{"alt":[{"stem":"부피가 1 cm³인 쌓기나무를 한 층에 15개씩 4층으로 쌓았어요. 전체 부피는 몇 cm³인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["한 층에 15개, 4층이에요.","15 × 4 = 60개예요.","그래서 60 cm³예요."]},{"stem":"부피가 1 cm³인 쌓기나무를 한 층에 24개씩 5층으로 쌓았어요. 전체 부피는 몇 cm³인가요? 숫자로 쓰세요.","answer":["120"],"explanation":["한 층에 24개, 5층이에요.","24 × 5 = 120개예요.","그래서 120 cm³예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L04_challenge#6','math',6,1,'u6','L04','g6_1_math_u6_L04_challenge','lesson_challenge','M6-1-u6-C4',3,'error','auto','수아는 크기가 제각각인 쌓기나무 72개로, 예준은 크기가 같은 쌓기나무 72개로 두 상자와 똑같은 모양을 쌓았어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u6-X08','M6-1-u6-X18']::text[],true,'{"seq":6,"concept":"M6-1-u6-C4","difficulty":3,"kind":"error","stem":"수아는 크기가 제각각인 쌓기나무 72개로, 예준은 크기가 같은 쌓기나무 72개로 두 상자와 똑같은 모양을 쌓았어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"나린 — 「둘 다 72개이니 두 상자의 부피는 같아.」","correct":true,"mis_target":"M6-1-u6-X08"},{"t":"수아 — 「내 쌓기나무는 크기가 달라서 개수로 부피를 비교할 수 없어.」","mis":"M6-1-u6-X18"},{"t":"예준 — 「같은 크기 쌓기나무여야 개수로 부피를 비교할 수 있어.」","mis":"M6-1-u6-X18"}],"explanation":["크기가 서로 다른 단위로 센 개수는 비교할 수 없어요.","수아의 72개와 예준의 72개는 부피가 다를 수 있어요.","나린은 크기를 따지지 않고 개수만 보았어요."],"variant_rule":{"alt":[{"stem":"가온은 크기가 제각각인 쌓기나무 54개로, 유진은 크기가 같은 쌓기나무 54개로 두 상자와 똑같은 모양을 쌓았어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라온 — 「둘 다 54개이니 두 상자의 부피는 같아.」","correct":true,"mis_target":"M6-1-u6-X08"},{"t":"가온 — 「내 쌓기나무는 크기가 달라서 개수로 부피를 비교할 수 없어.」","mis":"M6-1-u6-X18"},{"t":"유진 — 「같은 크기 쌓기나무여야 개수로 부피를 비교할 수 있어.」","mis":"M6-1-u6-X18"}],"explanation":["크기가 서로 다른 단위로 센 개수는 비교할 수 없어요.","가온의 54개와 유진의 54개는 부피가 다를 수 있어요.","라온은 크기를 따지지 않고 개수만 보았어요."]},{"stem":"여울은 크기가 제각각인 쌓기나무 40개로, 시우는 크기가 같은 쌓기나무 40개로 두 상자와 똑같은 모양을 쌓았어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「둘 다 40개이니 두 상자의 부피는 같아.」","correct":true,"mis_target":"M6-1-u6-X08"},{"t":"여울 — 「내 쌓기나무는 크기가 달라서 개수로 부피를 비교할 수 없어.」","mis":"M6-1-u6-X18"},{"t":"시우 — 「같은 크기 쌓기나무여야 개수로 부피를 비교할 수 있어.」","mis":"M6-1-u6-X18"}],"explanation":["크기가 서로 다른 단위로 센 개수는 비교할 수 없어요.","여울의 40개와 시우의 40개는 부피가 다를 수 있어요.","은우는 크기를 따지지 않고 개수만 보았어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L04_challenge#7','math',6,1,'u6','L04','g6_1_math_u6_L04_challenge','lesson_challenge','M6-1-u6-C4',3,'sa','auto','부피가 1 cm³인 쌓기나무 24개를 모두 써서 한 층에 가로 4개, 세로 3개씩 놓아 직육면체를 쌓았어요. 몇 층으로 쌓았나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u6-C4","difficulty":3,"kind":"sa","stem":"부피가 1 cm³인 쌓기나무 24개를 모두 써서 한 층에 가로 4개, 세로 3개씩 놓아 직육면체를 쌓았어요. 몇 층으로 쌓았나요? 숫자로 쓰세요.","answer":["2"],"explanation":["한 층에는 4 × 3 = 12개가 놓여요.","24 ÷ 12 = 2예요.","그래서 2층이에요."],"mis":"M6-1-u6-X10","variant_rule":{"alt":[{"stem":"부피가 1 cm³인 쌓기나무 36개를 모두 써서 한 층에 가로 3개, 세로 3개씩 놓아 직육면체를 쌓았어요. 몇 층으로 쌓았나요? 숫자로 쓰세요.","answer":["4"],"explanation":["한 층에는 3 × 3 = 9개가 놓여요.","36 ÷ 9 = 4예요.","그래서 4층이에요."]},{"stem":"부피가 1 cm³인 쌓기나무 40개를 모두 써서 한 층에 가로 5개, 세로 2개씩 놓아 직육면체를 쌓았어요. 몇 층으로 쌓았나요? 숫자로 쓰세요.","answer":["4"],"explanation":["한 층에는 5 × 2 = 10개가 놓여요.","40 ÷ 10 = 4예요.","그래서 4층이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
