INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L05_basic#7','math',6,1,'u6','L05','g6_1_math_u6_L05_basic','lesson_basic','M6-1-u6-C5',2,'mc','auto','(한 밑면의 넓이) × (높이)가 직육면체의 부피와 같은 까닭은 무엇인가요?',ARRAY['M6-1-u6-X04','M6-1-u6-X01','M6-1-u6-X11']::text[],true,'{"seq":7,"concept":"M6-1-u6-C5","difficulty":2,"kind":"mc","stem":"(한 밑면의 넓이) × (높이)가 직육면체의 부피와 같은 까닭은 무엇인가요?","options":[{"t":"밑면에 깔린 한 층을 높이만큼 쌓기 때문에","correct":true},{"t":"밑면을 두 배 하기 때문에","mis":"M6-1-u6-X04"},{"t":"옆면의 넓이를 더하기 때문에","mis":"M6-1-u6-X01"},{"t":"모서리의 길이를 모두 더하기 때문에","mis":"M6-1-u6-X11"}],"explanation":["가로·세로에 놓인 개수를 곱하면 한 층의 개수(한 밑면의 넓이)예요.","그 한 층을 높이만큼 쌓으면 전체 개수, 곧 부피예요.","정답은 「밑면에 깔린 한 층을 높이만큼 쌓기 때문에」예요."],"variant_rule":{"alt":[{"stem":"가로 4 cm인 모서리에 1 cm³ 쌓기나무가 몇 개 놓이는지가 중요한 까닭은 무엇인가요?","options":[{"t":"놓이는 쌓기나무 개수가 곧 그 모서리의 길이이기 때문에","correct":true},{"t":"쌓기나무는 언제나 4개씩 놓기 때문에","mis":"M6-1-u6-X10"},{"t":"가로가 가장 긴 모서리이기 때문에","mis":"M6-1-u6-X18"},{"t":"쌓기나무 개수는 길이와 관계없기 때문에","mis":"M6-1-u6-X11"}],"explanation":["가로·세로에 놓인 개수를 곱하면 한 층의 개수(한 밑면의 넓이)예요.","그 한 층을 높이만큼 쌓으면 전체 개수, 곧 부피예요.","정답은 「놓이는 쌓기나무 개수가 곧 그 모서리의 길이이기 때문에」예요."]},{"stem":"가로 × 세로가 나타내는 것은 무엇인가요? (1 cm³ 쌓기나무로 채운 직육면체)","options":[{"t":"한 층에 놓인 쌓기나무의 개수","correct":true},{"t":"전체 쌓기나무의 개수","mis":"M6-1-u6-X11"},{"t":"층의 수","mis":"M6-1-u6-X10"},{"t":"겉면의 넓이","mis":"M6-1-u6-X01"}],"explanation":["가로·세로에 놓인 개수를 곱하면 한 층의 개수(한 밑면의 넓이)예요.","그 한 층을 높이만큼 쌓으면 전체 개수, 곧 부피예요.","정답은 「한 층에 놓인 쌓기나무의 개수」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
