INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L05_basic#9','math',6,1,'u6','L05','g6_1_math_u6_L05_basic','lesson_basic','M6-1-u6-C5',2,'ox','auto','한 모서리가 3 cm인 정육면체의 부피는 3 × 3 = 9(cm³)예요.',ARRAY['M6-1-u6-X12']::text[],true,'{"seq":9,"concept":"M6-1-u6-C5","difficulty":2,"kind":"ox","stem":"한 모서리가 3 cm인 정육면체의 부피는 3 × 3 = 9(cm³)예요.","answer":"X","reason_options":[{"t":"정육면체의 부피는 한 모서리를 세 번 곱해 3 × 3 × 3 = 27(cm³)이기 때문에","correct":true},{"t":"정육면체는 두 번만 곱하면 되기 때문에","mis":"M6-1-u6-X12"}],"mis":"M6-1-u6-X12","explanation":["부피 = 가로 × 세로 × 높이 = 한 밑면의 넓이 × 높이예요.","정육면체는 한 모서리를 세 번 곱해요.","부피와 겉넓이는 서로 다른 양이에요."],"variant_rule":{"alt":[{"stem":"부피가 같은 두 직육면체는 겉넓이도 언제나 같아요.","answer":"X","reason_options":[{"t":"모양이 다르면 부피가 같아도 겉넓이는 다를 수 있기 때문에","correct":true},{"t":"부피와 겉넓이는 같은 양이기 때문에","mis":"M6-1-u6-X17"}],"explanation":["부피 = 가로 × 세로 × 높이 = 한 밑면의 넓이 × 높이예요.","정육면체는 한 모서리를 세 번 곱해요.","부피와 겉넓이는 서로 다른 양이에요."]},{"stem":"가로에 놓인 1 cm³ 쌓기나무의 개수는 가로의 길이와 같아요.","answer":"O","reason_options":[{"t":"1 cm짜리 쌓기나무가 길이만큼 딱 들어가기 때문에","correct":true},{"t":"쌓기나무 개수는 길이의 2배이기 때문에","mis":"M6-1-u6-X10"}],"explanation":["부피 = 가로 × 세로 × 높이 = 한 밑면의 넓이 × 높이예요.","정육면체는 한 모서리를 세 번 곱해요.","부피와 겉넓이는 서로 다른 양이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L05_basic#10','math',6,1,'u6','L05','g6_1_math_u6_L05_basic','lesson_basic','M6-1-u6-C5',3,'error','auto','가로 4 cm, 세로 3 cm, 높이 2 cm인 직육면체의 부피를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u6-X11','M6-1-u6-X18']::text[],true,'{"seq":10,"concept":"M6-1-u6-C5","difficulty":3,"kind":"error","stem":"가로 4 cm, 세로 3 cm, 높이 2 cm인 직육면체의 부피를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「4 + 3 + 2 = 9이니까 부피는 9 cm³야.」","correct":true,"mis_target":"M6-1-u6-X11"},{"t":"도윤 — 「한 층에 4 × 3 = 12개, 2층이니까 24 cm³야.」","mis":"M6-1-u6-X18"},{"t":"서아 — 「4 × 3 × 2 = 24이니까 24 cm³야.」","mis":"M6-1-u6-X18"}],"explanation":["부피는 가로·세로·높이를 곱해 구해요.","4 × 3 × 2 = 24(cm³)예요.","하린은 세 길이를 더했어요."],"asset":{"type":"geo","items":[{"w":168.0,"h":94.0,"pts":{"ㄱ":[36.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,36.0,"w"],"ㄷ":[96.0,36.0,"sw"],"ㅁ":[36.0,48.0,"ne"],"ㅇ":[132.0,48.0,"e"],"ㅂ":[0,84.0,"sw"],"ㅅ":[96.0,84.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[48.0,97.0],"4 cm"],[[136.0,72.0],"3 cm"],[[158.0,24.0],"2 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 5 cm, 세로 3 cm, 높이 4 cm인 직육면체의 부피를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「5 + 3 + 4 = 12이니까 부피는 12 cm³야.」","correct":true,"mis_target":"M6-1-u6-X11"},{"t":"예준 — 「한 층에 5 × 3 = 15개, 4층이니까 60 cm³야.」","mis":"M6-1-u6-X18"},{"t":"나린 — 「5 × 3 × 4 = 60이니까 60 cm³야.」","mis":"M6-1-u6-X18"}],"explanation":["부피는 가로·세로·높이를 곱해 구해요.","5 × 3 × 4 = 60(cm³)예요.","수아는 세 길이를 더했어요."],"asset":{"type":"geo","items":[{"w":192.0,"h":142.0,"pts":{"ㄱ":[36.0,0,"nw"],"ㄹ":[156.0,0,"ne"],"ㄴ":[0,36.0,"w"],"ㄷ":[120.0,36.0,"sw"],"ㅁ":[36.0,96.0,"ne"],"ㅇ":[156.0,96.0,"e"],"ㅂ":[0,132.0,"sw"],"ㅅ":[120.0,132.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"