INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L05_challenge#2','math',6,1,'u6','L05','g6_1_math_u6_L05_challenge','lesson_challenge','M6-1-u6-C5',2,'mc','auto','직육면체의 부피를 구하는 식이 아닌 것은 어느 것인가요?',ARRAY['M6-1-u6-X18']::text[],true,'{"seq":2,"concept":"M6-1-u6-C5","difficulty":2,"kind":"mc","stem":"직육면체의 부피를 구하는 식이 아닌 것은 어느 것인가요?","options":[{"t":"(한 밑면의 넓이) × 2 + (옆면의 넓이)","correct":true},{"t":"(가로) × (세로) × (높이)","mis":"M6-1-u6-X18"},{"t":"(한 밑면의 넓이) × (높이)","mis":"M6-1-u6-X18"},{"t":"(가로) × (높이) × (세로)","mis":"M6-1-u6-X18"}],"explanation":["가로·세로·높이에 놓이는 1 cm³ 쌓기나무의 개수는 각 모서리의 길이와 같아요.","세 개수를 곱하면 전체 개수, 곧 부피예요.","정답은 「(한 밑면의 넓이) × 2 + (옆면의 넓이)」예요."],"variant_rule":{"alt":[{"stem":"정육면체의 부피를 구하는 바른 식은 어느 것인가요?","options":[{"t":"(한 모서리) × (한 모서리) × (한 모서리)","correct":true},{"t":"(한 모서리) × 3","mis":"M6-1-u6-X12"},{"t":"(한 모서리) × (한 모서리) × 6","mis":"M6-1-u6-X12"},{"t":"(한 모서리) × (한 모서리)","mis":"M6-1-u6-X11"}],"explanation":["가로·세로·높이에 놓이는 1 cm³ 쌓기나무의 개수는 각 모서리의 길이와 같아요.","세 개수를 곱하면 전체 개수, 곧 부피예요.","정답은 「(한 모서리) × (한 모서리) × (한 모서리)」예요."]},{"stem":"직육면체의 부피를 구하는 바른 식은 어느 것인가요?","options":[{"t":"(가로) × (세로) × (높이)","correct":true},{"t":"(가로) + (세로) + (높이)","mis":"M6-1-u6-X11"},{"t":"(가로) × (세로)","mis":"M6-1-u6-X11"},{"t":"(가로) × (세로) × (높이) × 2","mis":"M6-1-u6-X18"}],"explanation":["가로·세로·높이에 놓이는 1 cm³ 쌓기나무의 개수는 각 모서리의 길이와 같아요.","세 개수를 곱하면 전체 개수, 곧 부피예요.","정답은 「(가로) × (세로) × (높이)」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
