INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L05_challenge#4','math',6,1,'u6','L05','g6_1_math_u6_L05_challenge','lesson_challenge','M6-1-u6-C5',3,'sa','auto','부피가 120 cm³인 직육면체 모양 상자의 가로가 6 cm, 세로가 5 cm예요. 높이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u6-C5","difficulty":3,"kind":"sa","stem":"부피가 120 cm³인 직육면체 모양 상자의 가로가 6 cm, 세로가 5 cm예요. 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["부피 = 가로 × 세로 × 높이이므로 한 밑면의 넓이는 6 × 5 = 30이에요.","120 ÷ 30 = 4예요.","그래서 높이는 4 cm예요."],"mis":"M6-1-u6-X11","asset":{"type":"geo","items":[{"w":226.0,"h":155.3,"pts":{"ㄱ":[55.9,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,55.9,"w"],"ㄷ":[134.1,55.9,"sw"],"ㅁ":[55.9,89.4,"ne"],"ㅇ":[190.0,89.4,"e"],"ㅂ":[0,145.3,"sw"],"ㅅ":[134.1,145.3,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[67.0,158.3],"6 cm"],[[184.0,123.4],"5 cm"],[[216.0,44.7],"?"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"부피가 120 cm³인 직육면체 모양 상자의 가로가 8 cm, 세로가 5 cm예요. 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["부피 = 가로 × 세로 × 높이이므로 한 밑면의 넓이는 8 × 5 = 40이에요.","120 ÷ 40 = 3이에요.","그래서 높이는 3 cm예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":109.5,"pts":{"ㄱ":[45.2,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,45.2,"w"],"ㄷ":[144.8,45.2,"sw"],"ㅁ":[45.2,54.3,"ne"],"ㅇ":[190.0,54.3,"e"],"ㅂ":[0,99.5,"sw"],"ㅅ":[144.8,99.5,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[72.4,112.5],"8 cm"],[[189.4,82.9],"5 cm"],[[216.0,27.1],"?"]]}],"tag":false}},{"stem":"부피가 420 cm³인 직육면체 모양 상자의 가로가 10 cm, 세로가 6 cm예요. 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["부피 = 가로 × 세로 × 높이이므로 한 밑면의 넓이는 10 × 6 = 60이에요.","420 ÷ 60 = 7이에요.","그래서 높이는 7 cm예요."