INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L05_challenge#9','math',6,1,'u6','L05','g6_1_math_u6_L05_challenge','lesson_challenge','M6-1-u6-C5',4,'sa','auto','가로 12 cm, 세로 8 cm, 높이 6 cm인 직육면체 모양 상자에 한 모서리가 2 cm인 정육면체 블록을 빈틈없이 채우려고 해요. 블록은 모두 몇 개 들어가나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u6-C5","difficulty":4,"kind":"sa","stem":"가로 12 cm, 세로 8 cm, 높이 6 cm인 직육면체 모양 상자에 한 모서리가 2 cm인 정육면체 블록을 빈틈없이 채우려고 해요. 블록은 모두 몇 개 들어가나요? 숫자로 쓰세요.","answer":["72"],"explanation":["가로에 12 ÷ 2 = 6개, 세로에 8 ÷ 2 = 4개, 높이에 6 ÷ 2 = 3개가 놓여요.","6 × 4 × 3 = 72예요.","그래서 72개예요."],"mis":"M6-1-u6-X10","asset":{"type":"geo","items":[{"w":226.0,"h":128.7,"pts":{"ㄱ":[47.5,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,47.5,"w"],"ㄷ":[142.5,47.5,"sw"],"ㅁ":[47.5,71.2,"ne"],"ㅇ":[190.0,71.2,"e"],"ㅂ":[0,118.7,"sw"],"ㅅ":[142.5,118.7,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[71.2,131.7],"12 cm"],[[188.2,101.0],"8 cm"],[[216.0,35.6],"6 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 15 cm, 세로 9 cm, 높이 6 cm인 직육면체 모양 상자에 한 모서리가 3 cm인 정육면체 블록을 빈틈없이 채우려고 해요. 블록은 모두 몇 개 들어가나요? 숫자로 쓰세요.","answer":["30"],"explanation":["가로에 15 ÷ 3 = 5개, 세로에 9 ÷ 3 = 3개, 높이에 6 ÷ 3 = 2개가 놓여요.","5 × 3 × 2 = 30이에요.","그래서 30개예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":112.3,"pts":{"ㄱ":[43.8,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,43.8,"w"],"ㄷ":[146.2,43.8,"sw"],"ㅁ":[43.8,58.5,"ne"],"ㅇ":[190.0,58.5,"e"],"ㅂ":[0,102.3,"sw"],"ㅅ":[146.2,102.3,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[73.1,115.3],"15 cm"],[[190.1,86.4],"9 cm"],[[216.0,29.2],"6 cm"]]}],"tag":false}},{"stem":"가로 20 cm, 세로 10 cm, 높이 8 cm인 직육면체 모양 상자에 한 모서리가 2 cm인 정육면체 블록을 빈틈없이 채우려고 해요. 블록은 모두 몇 개 들어가나요? 숫자로 쓰세요.","answer":["200"],"explanation":["가로에 20 ÷ 2 = 10개, 세로에 10 ÷ 2 = 5개, 높이에 8 ÷ 2 = 4개가 놓여요.","10 × 5 × 4 = 200이에요.","그래서 200개예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":108.8,"pts":{"ㄱ":[38.0,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,38.0,"w"],"ㄷ":[152.0,38.0,"sw"],"ㅁ":[38.0,60.8,"ne"],"ㅇ":[190.0,60.8,"e"],"ㅂ":[0,98.8,"sw"],"ㅅ":[152.0,98.8,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[76.0,111.8],"20 cm"],[[193.0,85.8],"10 cm"],[[216.0,30.4],"8 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L05_challenge#10','math',6,1,'u6','L05','g6_1_math_u6_L05_challenge','lesson_challenge','M6-1-u6-C5',4,'essay','teacher','가로 4 cm, 세로 3 cm, 높이 2 cm인 직육면체의 부피를 1 cm³ 쌓기나무로 생각하여 구하고, 부피를 가로 × 세로 × 높이로 구할 수 있는 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u6-C5","difficulty":4,"kind":"essay","stem":"가로 4 cm, 세로 3 cm, 높이 2 cm인 직육면체의 부피를 1 cm³ 쌓기나무로 생각하여 구하고, 부피를 가로 × 세로 × 높이로 구할 수 있는 까닭을 써 보세요.","answer_guide":{"answer":"예: 한 층에 가로 4개씩 세로 3줄이라 4 × 3 = 12개, 2층이라 12 × 2 = 24개이므로 24 cm³이다. 가로·세로·높이에 놓이는 1 cm³ 쌓기나무의 개수가 각 모서리의 길이와 같아서, 세 길이를 곱하면 전체 쌓기나무 개수, 곧 부피가 된다.","scoring_points":["24 cm³를 구했는가","한 층의 개수 × 층수로 설명했는가","쌓기나무 개수가 모서리 길이와 같다고 썼는가"]},"explanation":["한 층 12개, 2층이에요.","4 × 3 × 2 = 24예요.","그래서 24 cm³예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L06_basic#1','math',6,1,'u6','L06','g6_1_math_u6_L06_basic','lesson_basic','M6-1-u6-C6',1,'mc','auto','한 모서리가 1 m인 정육면체의 부피를 무엇이라고 하나요?',ARRAY['M6-1-u6-X02','M6-1-u6-X13']::text[],true,'{"seq":1,"concept":"M6-1-u6-C6","difficulty":1,"kind":"mc","stem":"한 모서리가 1 m인 정육면체의 부피를 무엇이라고 하나요?","options":[{"t":"1 m³","correct":true},{"t":"1 m²","mis":"M6-1-u6-X02"},{"t":"1 cm³","mis":"M6-1-u6-X13"},{"t":"100 cm³","mis":"M6-1-u6-X13"}],"explanation":["한 모서리가 1 m인 정육면체의 부피를 1 m³라 쓰고 「1 세제곱미터」라고 읽어요.","1 m = 100 cm이므로 100 × 100 × 100 = 1000000이에요.","정답은 「1 m³」예요."],"variant_rule":{"alt":[{"stem":"「1 m³」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"1 세제곱미터","correct":true},{"t":"1 제곱미터","mis":"M6-1-u6-X02"},{"t":"1 세제곱센티미터","mis":"M6-1-u6-X13"},{"t":"1 미터","mis":"M6-1-u6-X02"}],"explanation":["한 모서리가 1 m인 정육면체의 부피를 1 m³라 쓰고 「1 세제곱미터」라고 읽어요.","1 m = 100 cm이므로 100 × 100 × 100 = 1000000이에요.","정답은 「1 세제곱미터」예요."]},{"stem":"1 m³ = 1000000 cm³인 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"한 모서리 100 cm를 가로·세로·높이 세 방향으로 곱하기 때문에","correct":true},{"t":"100을 두 번 곱하기 때문에","mis":"M6-1-u6-X13"},{"t":"1 m = 1000 cm이기 때문에","mis":"M6-1-u6-X13"},{"t":"100에 6을 곱하기 때문에","mis":"M6-1-u6-X13"}],"explanation":["한 모서리가 1 m인 정육면체의 부피를 1 m³라 쓰고 「1 세제곱미터」라고 읽어요.","1 m = 100 cm이므로 100 × 100 × 100 = 1000000이에요.","정답은 「한 모서리 100 cm를 가로·세로·높이 세 방향으로 곱하기 때문에」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L06_basic#2','math',6,1,'u6','L06','g6_1_math_u6_L06_basic','lesson_basic','M6-1-u6-C6',1,'mc','auto','1 m³는 몇 cm³인가요?',ARRAY['M6-1-u6-X13']::text[],true,'{"seq":2,"concept":"M6-1-u6-C6","difficulty":1,"kind":"mc","stem":"1 m³는 몇 cm³인가요?","options":[{"t":"1000000 cm³","correct":true},{"t":"100 cm³","mis":"M6-1-u6-X13"},{"t":"10000 cm³","mis":"M6-1-u6-X13"},{"t":"1000 cm³","mis":"M6-1-u6-X13"}],"explanation":["1 m = 100 cm이므로 1 m³는 한 모서리 100 cm인 정육면체예요.","100 × 100 × 100 = 1000000이므로 1 m³ = 1000000 cm³예요.","그래서 1 m³는 1000000 cm³예요."],"variant_rule":{"alt":[{"stem":"2 m³는 몇 cm³인가요?","options":[{"t":"2000000 cm³","correct":true},{"t":"200 cm³","mis":"M6-1-u6-X13"},{"t":"20000 cm³","mis":"M6-1-u6-X13"},{"t":"2000 cm³","mis":"M6-1-u6-X13"}],"explanation":["1 m = 100 cm이므로 1 m³는 한 모서리 100 cm인 정육면체예요.","100 × 100 × 100 = 1000000이므로 1 m³ = 1000000 cm³예요.","1000000 × 2 = 2000000이므로 2000000 cm³예요."]},{"stem":"5 m³는 몇 cm³인가요?","options":[{"t":"5000000 cm³","correct":true},{"t":"500 cm³","mis":"M6-1-u6-X13"},{"t":"50000 cm³","mis":"M6-1-u6-X13"},{"t":"5000 cm³","mis":"M6-1-u6-X13"}],"explanation":["1 m = 100 cm이므로 1 m³는 한 모서리 100 cm인 정육면체예요.","100 × 100 × 100 = 1000000이므로 1 m³ = 1000000 cm³예요.","1000000 × 5 = 5000000이므로 5000000 cm³예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L06_basic#3','math',6,1,'u6','L06','g6_1_math_u6_L06_basic','lesson_basic','M6-1-u6-C6',1,'mc','auto','다음 중 부피를 m³로 나타내기에 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u6-X14']::text[],true,'{"seq":3,"concept":"M6-1-u6-C6","difficulty":1,"kind":"mc","stem":"다음 중 부피를 m³로 나타내기에 알맞은 것은 어느 것인가요?","options":[{"t":"교실","correct":true},{"t":"주사위","mis":"M6-1-u6-X14"},{"t":"각설탕","mis":"M6-1-u6-X14"},{"t":"지우개","mis":"M6-1-u6-X14"}],"explanation":["작은 물건의 부피는 cm³로 나타내요.","방·교실·트럭 짐칸·컨테이너처럼 큰 것은 m³로 나타내는 것이 편해요.","정답은 「교실」이에요."],"variant_rule":{"alt":[{"stem":"다음 중 부피를 cm³로 나타내기에 알맞은 것은 어느 것인가요?","options":[{"t":"필통","correct":true},{"t":"컨테이너","mis":"M6-1-u6-X14"},{"t":"교실","mis":"M6-1-u6-X14"},{"t":"트럭 짐칸","mis":"M6-1-u6-X14"}],"explanation":["작은 물건의 부피는 cm³로 나타내요.","방·교실·트럭 짐칸·컨테이너처럼 큰 것은 m³로 나타내는 것이 편해요.","정답은 「필통」이에요."]},{"stem":"이번에는 다른 보기예요. 다음 중 부피를 m³로 나타내기에 알맞은 것은 어느 것인가요?","options":[{"t":"트럭 짐칸","correct":true},{"t":"보석 상자","mis":"M6-1-u6-X14"},{"t":"우유갑","mis":"M6-1-u6-X14"},{"t":"필통","mis":"M6-1-u6-X14"}],"explanation":["작은 물건의 부피는 cm³로 나타내요.","방·교실·트럭 짐칸·컨테이너처럼 큰 것은 m³로 나타내는 것이 편해요.","정답은 「트럭 짐칸」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L06_basic#4','math',6,1,'u6','L06','g6_1_math_u6_L06_basic','lesson_basic','M6-1-u6-C6',1,'ox','auto','한 모서리가 1 m인 정육면체의 부피를 1 m³라고 해요.',ARRAY['M6-1-u6-X13']::text[],true,'{"seq":4,"concept":"M6-1-u6-C6","difficulty":1,"kind":"ox","stem":"한 모서리가 1 m인 정육면체의 부피를 1 m³라고 해요.","answer":"O","reason_options":[{"t":"부피의 큰 단위를 그렇게 정했기 때문에","correct":true},{"t":"한 모서리가 1 cm인 정육면체의 부피이기 때문에","mis":"M6-1-u6-X13"}],"mis":"M6-1-u6-X13","explanation":["1 m³ = 100 × 100 × 100 = 1000000 cm³예요.","큰 부피는 m³로 나타내면 편해요.","단위가 다르면 같은 단위로 고쳐 비교해요."],"variant_rule":{"alt":[{"stem":"1 m³는 10000 cm³예요.","answer":"X","reason_options":[{"t":"1 m³ = 100 × 100 × 100 = 1000000(cm³)이기 때문에","correct":true},{"t":"1 m² = 10000 cm²와 같은 관계이기 때문에","mis":"M6-1-u6-X13"}],"explanation":["1 m³ = 100 × 100 × 100 = 1000000 cm³예요.","큰 부피는 m³로 나타내면 편해요.","단위가 다르면 같은 단위로 고쳐 비교해요."]},{"stem":"3000000 cm³는 3 m³와 같아요.","answer":"O","reason_options":[{"t":"1 m³ = 1000000 cm³이므로 3배 하면 3000000 cm³이기 때문에","correct":true},{"t":"0의 개수와 관계없이 앞의 수만 같으면 되기 때문에","mis":"M6-1-u6-X14"}],"explanation":["1 m³ = 100 × 100 × 100 = 1000000 cm³예요.","큰 부피는 m³로 나타내면 편해요.","단위가 다르면 같은 단위로 고쳐 비교해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
