INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L06_basic#7','math',6,1,'u6','L06','g6_1_math_u6_L06_basic','lesson_basic','M6-1-u6-C6',2,'mc','auto','넓이 1 m²와 부피 1 m³를 cm 단위로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-1-u6-X13','M6-1-u6-X02']::text[],true,'{"seq":7,"concept":"M6-1-u6-C6","difficulty":2,"kind":"mc","stem":"넓이 1 m²와 부피 1 m³를 cm 단위로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"1 m² = 10000 cm², 1 m³ = 1000000 cm³","correct":true},{"t":"1 m² = 10000 cm², 1 m³ = 10000 cm³","mis":"M6-1-u6-X13"},{"t":"1 m² = 100 cm², 1 m³ = 1000 cm³","mis":"M6-1-u6-X13"},{"t":"1 m² = 1000000 cm², 1 m³ = 10000 cm³","mis":"M6-1-u6-X02"}],"explanation":["넓이는 두 방향을 곱해 1 m² = 100 × 100 = 10000(cm²)예요.","부피는 세 방향을 곱해 1 m³ = 100 × 100 × 100 = 1000000(cm³)예요.","정답은 「1 m² = 10000 cm², 1 m³ = 1000000 cm³」예요."],"variant_rule":{"alt":[{"stem":"100 × 100 × 100으로 구하는 것은 어느 것인가요?","options":[{"t":"1 m³가 몇 cm³인지","correct":true},{"t":"1 m²가 몇 cm²인지","mis":"M6-1-u6-X02"},{"t":"1 m가 몇 cm인지","mis":"M6-1-u6-X13"},{"t":"1 cm³가 몇 m³인지","mis":"M6-1-u6-X14"}],"explanation":["넓이는 두 방향을 곱해 1 m² = 100 × 100 = 10000(cm²)예요.","부피는 세 방향을 곱해 1 m³ = 100 × 100 × 100 = 1000000(cm³)예요.","정답은 「1 m³가 몇 cm³인지」예요."]},{"stem":"100 × 100으로 구하는 것은 어느 것인가요?","options":[{"t":"1 m²가 몇 cm²인지","correct":true},{"t":"1 m³가 몇 cm³인지","mis":"M6-1-u6-X13"},{"t":"1 cm³가 몇 개 모여 1 m³인지","mis":"M6-1-u6-X13"},{"t":"1 m가 몇 cm인지","mis":"M6-1-u6-X02"}],"explanation":["넓이는 두 방향을 곱해 1 m² = 100 × 100 = 10000(cm²)예요.","부피는 세 방향을 곱해 1 m³ = 100 × 100 × 100 = 1000000(cm³)예요.","정답은 「1 m²가 몇 cm²인지」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=tr