INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L06_basic#9','math',6,1,'u6','L06','g6_1_math_u6_L06_basic','lesson_basic','M6-1-u6-C6',2,'ox','auto','교실처럼 큰 공간의 부피는 cm³로 나타내는 것이 가장 편해요.',ARRAY['M6-1-u6-X14']::text[],true,'{"seq":9,"concept":"M6-1-u6-C6","difficulty":2,"kind":"ox","stem":"교실처럼 큰 공간의 부피는 cm³로 나타내는 것이 가장 편해요.","answer":"X","reason_options":[{"t":"수가 너무 커서 m³로 나타내는 것이 편하기 때문에","correct":true},{"t":"cm³가 m³보다 큰 단위이기 때문에","mis":"M6-1-u6-X14"}],"mis":"M6-1-u6-X14","explanation":["1 m³ = 100 × 100 × 100 = 1000000 cm³예요.","큰 부피는 m³로 나타내면 편해요.","단위가 다르면 같은 단위로 고쳐 비교해요."],"variant_rule":{"alt":[{"stem":"단위가 다른 두 부피는 같은 단위로 고친 뒤 비교해야 해요.","answer":"O","reason_options":[{"t":"단위가 다르면 수만 보고 크기를 알 수 없기 때문에","correct":true},{"t":"수가 큰 쪽이 언제나 부피도 크기 때문에","mis":"M6-1-u6-X14"}],"explanation":["1 m³ = 100 × 100 × 100 = 1000000 cm³예요.","큰 부피는 m³로 나타내면 편해요.","단위가 다르면 같은 단위로 고쳐 비교해요."]},{"stem":"1 m³는 10000 cm³예요.","answer":"X","reason_options":[{"t":"1 m³ = 100 × 100 × 100 = 1000000(cm³)이기 때문에","correct":true},{"t":"1 m² = 10000 cm²와 같은 관계이기 때문에","mis":"M6-1-u6-X13"}],"explanation":["1 m³ = 100 × 100 × 100 = 1000000 cm³예요.","큰 부피는 m³로 나타내면 편해요.","단위가 다르면 같은 단위로 고쳐 비교해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L06_basic#10','math',6,1,'u6','L06','g6_1_math_u6_L06_basic','lesson_basic','M6-1-u6-C6',3,'error','auto','1 m³와 cm³의 관계를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u6-X13','M6-1-u6-X18']::text[],true,'{"seq":10,"concept":"M6-1-u6-C6","difficulty":3,"kind":"error","stem":"1 m³와 cm³의 관계를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「1 m = 100 cm니까 1 m³는 100 × 100 = 10000(cm³)야.」","correct":true,"mis_target":"M6-1-u6-X13"},{"t":"도윤 — 「1 m³는 한 모서리가 1 m인 정육면체의 부피야.」","mis":"M6-1-u6-X18"},{"t":"서아 — 「1 m³에는 1 cm³ 쌓기나무가 한 층에 10000개씩 100층 들어가.」","mis":"M6-1-u6-X18"}],"explanation":["부피는 가로·세로·높이 세 방향을 곱해요.","100 × 100 × 100 = 1000000이므로 1 m³ = 1000000 cm³예요.","하린은 넓이처럼 두 번만 곱했어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 1 m³와 cm³의 관계를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「1 m = 100 cm니까 1 m³는 100 × 100 = 10000(cm³)야.」","correct":true,"mis_target":"M6-1-u6-X13"},{"t":"예준 — 「1 m³는 한 모서리가 1 m인 정육면체의 부피야.」","mis":"M6-1-u6-X18"},{"t":"나린 — 「1 m³에는 1 cm³ 쌓기나무가 한 층에 10000개씩 100층 들어가.」","mis":"M6-1-u6-X18"}],"explanation":["부피는 가로·세로·높이 세 방향을 곱해요.","100 × 100 × 100 = 1000000이므로 1 m³ = 1000000 cm³예요.","수아는 넓이처럼 두 번만 곱했어요."]},{"stem":"이번에는 다른 보기예요. 1 m³와 cm³의 관계를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「1 m = 100 cm니까 1 m³는 100 × 100 = 10000(cm³)야.」","correct":true,"mis_target":"M6-1-u6-X13"},{"t":"유진 — 「1 m³는 한 모서리가 1 m인 정육면체의 부피야.」","mis":"M6-1-u6-X18"},{"t":"라온 — 「1 m³에는 1 cm³ 쌓기나무가 한 층에 10000개씩 100층 들어가.」","mis":"M6-1-u6-X18"}],"explanation":["부피는 가로·세로·높이 세 방향을 곱해요.","100 × 100 × 100 = 1000000이므로 1 m³ = 1000000 cm³예요.","가온은 넓이처럼 두 번만 곱했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L06_challenge#1','math',6,1,'u6','L06','g6_1_math_u6_L06_challenge','lesson_challenge','M6-1-u6-C6',2,'match','auto','알맞은 단위를 이어 보세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u6-C6","difficulty":2,"kind":"match","stem":"알맞은 단위를 이어 보세요.","pairs":[{"l":"지우개의 부피","r":"cm³"},{"l":"교실의 부피","r":"m³"},{"l":"교실 바닥의 넓이","r":"m²"}],"mis":"M6-1-u6-X14","explanation":["넓이는 ², 부피는 ³인 단위를 써요.","작은 것은 cm, 큰 것은 m로 나타내는 단위가 편해요.","무엇을 재는지와 크기를 함께 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 알맞은 단위를 이어 보세요.","pairs":[{"l":"각설탕의 부피","r":"cm³"},{"l":"컨테이너의 부피","r":"m³"},{"l":"공책 표지의 넓이","r":"cm²"}],"explanation":["넓이는 ², 부피는 ³인 단위를 써요.","작은 것은 cm, 큰 것은 m로 나타내는 단위가 편해요.","무엇을 재는지와 크기를 함께 봐요."]},{"stem":"이번에는 다른 보기예요. 알맞은 단위를 이어 보세요.","pairs":[{"l":"필통의 부피","r":"cm³"},{"l":"트럭 짐칸의 부피","r":"m³"},{"l":"운동장의 넓이","r":"m²"}],"explanation":["넓이는 ², 부피는 ³인 단위를 써요.","작은 것은 cm, 큰 것은 m로 나타내는 단위가 편해요.","무엇을 재는지와 크기를 함께 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L06_challenge#2','math',6,1,'u6','L06','g6_1_math_u6_L06_challenge','lesson_challenge','M6-1-u6-C6',2,'mc','auto','8 m³는 몇 cm³인가요?',ARRAY['M6-1-u6-X13']::text[],true,'{"seq":2,"concept":"M6-1-u6-C6","difficulty":2,"kind":"mc","stem":"8 m³는 몇 cm³인가요?","options":[{"t":"8000000 cm³","correct":true},{"t":"800 cm³","mis":"M6-1-u6-X13"},{"t":"80000 cm³","mis":"M6-1-u6-X13"},{"t":"8000 cm³","mis":"M6-1-u6-X13"}],"explanation":["1 m = 100 cm이므로 1 m³는 한 모서리 100 cm인 정육면체예요.","100 × 100 × 100 = 1000000이므로 1 m³ = 1000000 cm³예요.","1000000 × 8 = 8000000이므로 8000000 cm³예요."],"variant_rule":{"alt":[{"stem":"9 m³는 몇 cm³인가요?","options":[{"t":"9000000 cm³","correct":true},{"t":"900 cm³","mis":"M6-1-u6-X13"},{"t":"90000 cm³","mis":"M6-1-u6-X13"},{"t":"9000 cm³","mis":"M6-1-u6-X13"}],"explanation":["1 m = 100 cm이므로 1 m³는 한 모서리 100 cm인 정육면체예요.","100 × 100 × 100 = 1000000이므로 1 m³ = 1000000 cm³예요.","1000000 × 9 = 9000000이므로 9000000 cm³예요."]},{"stem":"4 m³는 몇 cm³인가요?","options":[{"t":"4000000 cm³","correct":true},{"t":"400 cm³","mis":"M6-1-u6-X13"},{"t":"40000 cm³","mis":"M6-1-u6-X13"},{"t":"4000 cm³","mis":"M6-1-u6-X13"}],"explanation":["1 m = 100 cm이므로 1 m³는 한 모서리 100 cm인 정육면체예요.","100 × 100 × 100 = 1000000이므로 1 m³ = 1000000 cm³예요.","1000000 × 4 = 4000000이므로 4000000 cm³예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
