INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L06_challenge#4','math',6,1,'u6','L06','g6_1_math_u6_L06_challenge','lesson_challenge','M6-1-u6-C6',3,'sa','auto','가로 300 cm, 세로 200 cm, 높이 100 cm인 직육면체 모양 컨테이너 칸의 부피는 몇 m³인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u6-C6","difficulty":3,"kind":"sa","stem":"가로 300 cm, 세로 200 cm, 높이 100 cm인 직육면체 모양 컨테이너 칸의 부피는 몇 m³인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["부피는 300 × 200 × 100 = 6000000(cm³)예요.","1 m³ = 1000000 cm³이므로 6000000 ÷ 1000000 = 6이에요.","그래서 6 m³예요."],"mis":"M6-1-u6-X13","asset":{"type":"geo","items":[{"w":226.0,"h":105.0,"pts":{"ㄱ":[47.5,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,47.5,"w"],"ㄷ":[142.5,47.5,"sw"],"ㅁ":[47.5,47.5,"ne"],"ㅇ":[190.0,47.5,"e"],"ㅂ":[0,95.0,"sw"],"ㅅ":[142.5,95.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[71.2,108.0],"300 cm"],[[188.2,77.2],"200 cm"],[[216.0,23.8],"100 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 250 cm, 세로 160 cm, 높이 100 cm인 직육면체 모양 옷장의 부피는 몇 m³인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["부피는 250 × 160 × 100 = 4000000(cm³)예요.","1 m³ = 1000000 cm³이므로 4000000 ÷ 1000000 = 4예요.","그래서 4 m³예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":113.7,"pts":{"ㄱ":[46.1,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,46.1,"w"],"ㄷ":[143.9,46.1,"sw"],"ㅁ":[46.1,57.6,"ne"],"ㅇ":[190.0,57.6,"e"],"ㅂ":[0,103.7,"sw"],"ㅅ":[143.9,103.7,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[72.0,116.7],"250 cm"],[[189.0,86.7],"160 cm"],[[216.0,28.8],"100 cm"]]}],"tag":false}},{"stem":"가로 400 cm, 세로 250 cm, 높이 200 cm인 직육면체 모양 창고의 부피는 몇 m³인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["부피는 400 × 250 × 200 = 20000000(cm³)예요.","1 m³ = 1000000 cm³이므로 20000000 ÷ 1000000 = 20이에요.","그래서 20 m³예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":127.6,"pts":{"ㄱ":[45.2,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,45.2,"w"],"ㄷ":[144.8,45.2,"sw"],"ㅁ":[45.2,72.4,"ne"],"ㅇ":[190.0,72.4,"e"],"ㅂ":[0,117.6,"sw"],"ㅅ":[144.8,117.6,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[72.4,130.6],"400 cm"],[[189.4,101.0],"250 cm"],[[216.0,36.2],"200 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L06_challenge#5','math',6,1,'u6','L06','g6_1_math_u6_L06_challenge','lesson_challenge','M6-1-u6-C6',3,'mc','auto','1 m³ = 1000000 cm³인 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u6-X13']::text[],true,'{"seq":5,"concept":"M6-1-u6-C6","difficulty":3,"kind":"mc","stem":"1 m³ = 1000000 cm³인 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"한 모서리 100 cm를 가로·세로·높이 세 방향으로 곱하기 때문에","correct":true},{"t":"100을 두 번 곱하기 때문에","mis":"M6-1-u6-X13"},{"t":"1 m = 1000 cm이기 때문에","mis":"M6-1-u6-X13"},{"t":"100에 6을 곱하기 때문에","mis":"M6-1-u6-X13"}],"explanation":["한 모서리가 1 m인 정육면체의 부피를 1 m³라 쓰고 「1 세제곱미터」라고 읽어요.","1 m = 100 cm이므로 100 × 100 × 100 = 1000000이에요.","정답은 「한 모서리 100 cm를 가로·세로·높이 세 방향으로 곱하기 때문에」예요."],"variant_rule":{"alt":[{"stem":"한 모서리가 1 m인 정육면체의 부피를 무엇이라고 하나요?","options":[{"t":"1 m³","correct":true},{"t":"1 m²","mis":"M6-1-u6-X02"},{"t":"1 cm³","mis":"M6-1-u6-X13"},{"t":"100 cm³","mis":"M6-1-u6-X13"}],"explanation":["한 모서리가 1 m인 정육면체의 부피를 1 m³라 쓰고 「1 세제곱미터」라고 읽어요.","1 m = 100 cm이므로 100 × 100 × 100 = 1000000이에요.","정답은 「1 m³」예요."]},{"stem":"「1 m³」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"1 세제곱미터","correct":true},{"t":"1 제곱미터","mis":"M6-1-u6-X02"},{"t":"1 세제곱센티미터","mis":"M6-1-u6-X13"},{"t":"1 미터","mis":"M6-1-u6-X02"}],"explanation":["한 모서리가 1 m인 정육면체의 부피를 1 m³라 쓰고 「1 세제곱미터」라고 읽어요.","1 m = 100 cm이므로 100 × 100 × 100 = 1000000이에요.","정답은 「1 세제곱미터」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L06_challenge#6','math',6,1,'u6','L06','g6_1_math_u6_L06_challenge','lesson_challenge','M6-1-u6-C6',3,'error','auto','1 m³와 cm³의 관계를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u6-X13','M6-1-u6-X18']::text[],true,'{"seq":6,"concept":"M6-1-u6-C6","difficulty":3,"kind":"error","stem":"1 m³와 cm³의 관계를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「1 m = 100 cm니까 1 m³는 100 × 100 = 10000(cm³)야.」","correct":true,"mis_target":"M6-1-u6-X13"},{"t":"예준 — 「1 m³는 한 모서리가 1 m인 정육면체의 부피야.」","mis":"M6-1-u6-X18"},{"t":"나린 — 「1 m³에는 1 cm³ 쌓기나무가 한 층에 10000개씩 100층 들어가.」","mis":"M6-1-u6-X18"}],"explanation":["부피는 가로·세로·높이 세 방향을 곱해요.","100 × 100 × 100 = 1000000이므로 1 m³ = 1000000 cm³예요.","수아는 넓이처럼 두 번만 곱했어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 1 m³와 cm³의 관계를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「1 m = 100 cm니까 1 m³는 100 × 100 = 10000(cm³)야.」","correct":true,"mis_target":"M6-1-u6-X13"},{"t":"유진 — 「1 m³는 한 모서리가 1 m인 정육면체의 부피야.」","mis":"M6-1-u6-X18"},{"t":"라온 — 「1 m³에는 1 cm³ 쌓기나무가 한 층에 10000개씩 100층 들어가.」","mis":"M6-1-u6-X18"}],"explanation":["부피는 가로·세로·높이 세 방향을 곱해요.","100 × 100 × 100 = 1000000이므로 1 m³ = 1000000 cm³예요.","가온은 넓이처럼 두 번만 곱했어요."]},{"stem":"이번에는 다른 보기예요. 1 m³와 cm³의 관계를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「1 m = 100 cm니까 1 m³는 100 × 100 = 10000(cm³)야.」","correct":true,"mis_target":"M6-1-u6-X13"},{"t":"시우 — 「1 m³는 한 모서리가 1 m인 정육면체의 부피야.」","mis":"M6-1-u6-X18"},{"t":"은우 — 「1 m³에는 1 cm³ 쌓기나무가 한 층에 10000개씩 100층 들어가.」","mis":"M6-1-u6-X18"}],"explanation":["부피는 가로·세로·높이 세 방향을 곱해요.","100 × 100 × 100 = 1000000이므로 1 m³ = 1000000 cm³예요.","여울은 넓이처럼 두 번만 곱했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L06_challenge#7','math',6,1,'u6','L06','g6_1_math_u6_L06_challenge','lesson_challenge','M6-1-u6-C6',3,'sa','auto','12000000 cm³는 몇 m³인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u6-C6","difficulty":3,"kind":"sa","stem":"12000000 cm³는 몇 m³인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["1 m³ = 1000000 cm³예요.","12000000 ÷ 1000000 = 12예요.","그래서 12 m³예요."],"mis":"M6-1-u6-X13","variant_rule":{"alt":[{"stem":"24000000 cm³는 몇 m³인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["1 m³ = 1000000 cm³예요.","24000000 ÷ 1000000 = 24예요.","그래서 24 m³예요."]},{"stem":"9000000 cm³는 몇 m³인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["1 m³ = 1000000 cm³예요.","9000000 ÷ 1000000 = 9예요.","그래서 9 m³예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L06_challenge#8','math',6,1,'u6','L06','g6_1_math_u6_L06_challenge','lesson_challenge','M6-1-u6-C6',4,'sa','auto','가로 2 m, 세로 150 cm, 높이 100 cm인 직육면체 모양 창고의 부피는 몇 m³인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u6-C6","difficulty":4,"kind":"sa","stem":"가로 2 m, 세로 150 cm, 높이 100 cm인 직육면체 모양 창고의 부피는 몇 m³인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["단위를 m로 맞춰요: 150 cm = 1.5 m, 100 cm = 1 m예요.","2 × 1.5 × 1 = 3이에요.","그래서 3 m³예요."],"mis":"M6-1-u6-X14","variant_rule":{"alt":[{"stem":"가로 4 m, 세로 250 cm, 높이 200 cm인 직육면체 모양 컨테이너의 부피는 몇 m³인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["단위를 m로 맞춰요: 250 cm = 2.5 m, 200 cm = 2 m예요.","4 × 2.5 × 2 = 20이에요.","그래서 20 m³예요."]},{"stem":"가로 3 m, 세로 50 cm, 높이 200 cm인 직육면체 모양 화단의 부피는 몇 m³인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["단위를 m로 맞춰요: 50 cm = 0.5 m, 200 cm = 2 m예요.","3 × 0.5 × 2 = 3이에요.","그래서 3 m³예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L06_challenge#9','math',6,1,'u6','L06','g6_1_math_u6_L06_challenge','lesson_challenge','M6-1-u6-C6',4,'mc','auto','부피가 큰 것부터 차례로 바르게 늘어놓은 것은 어느 것인가요? ㉠ 1.9 m³ ㉡ 880000 cm³ ㉢ 한 모서리가 2 m인 정육면체',ARRAY['M6-1-u6-X14','M6-1-u6-X18']::text[],true,'{"seq":9,"concept":"M6-1-u6-C6","difficulty":4,"kind":"mc","stem":"부피가 큰 것부터 차례로 바르게 늘어놓은 것은 어느 것인가요? ㉠ 1.9 m³ ㉡ 880000 cm³ ㉢ 한 모서리가 2 m인 정육면체","options":[{"t":"㉢, ㉠, ㉡","correct":true},{"t":"㉠, ㉡, ㉢","mis":"M6-1-u6-X14"},{"t":"㉠, ㉢, ㉡","mis":"M6-1-u6-X14"},{"t":"㉡, ㉠, ㉢","mis":"M6-1-u6-X18"}],"explanation":["단위가 다르면 같은 단위로 고쳐 견줘요.","880000 cm³ = 0.88 m³, ㉢는 2 × 2 × 2 = 8(m³)예요.","큰 것부터 ㉢, ㉠, ㉡예요."],"variant_rule":{"alt":[{"stem":"부피가 큰 것부터 차례로 바르게 늘어놓은 것은 어느 것인가요? ㉠ 3 m³ ㉡ 2500000 cm³ ㉢ 한 모서리가 1 m인 정육면체","options":[{"t":"㉠, ㉡, ㉢","correct":true},{"t":"㉠, ㉢, ㉡","mis":"M6-1-u6-X14"},{"t":"㉡, ㉠, ㉢","mis":"M6-1-u6-X14"},{"t":"㉡, ㉢, ㉠","mis":"M6-1-u6-X18"}],"explanation":["단위가 다르면 같은 단위로 고쳐 견줘요.","2500000 cm³ = 2.5 m³, ㉢는 1 × 1 × 1 = 1(m³)예요.","큰 것부터 ㉠, ㉡, ㉢예요."]},{"stem":"부피가 큰 것부터 차례로 바르게 늘어놓은 것은 어느 것인가요? ㉠ 0.5 m³ ㉡ 700000 cm³ ㉢ 가로 2 m, 세로 1 m, 높이 1 m인 직육면체","options":[{"t":"㉢, ㉡, ㉠","correct":true},{"t":"㉠, ㉡, ㉢","mis":"M6-1-u6-X14"},{"t":"㉠, ㉢, ㉡","mis":"M6-1-u6-X14"},{"t":"㉡, ㉠, ㉢","mis":"M6-1-u6-X18"}],"explanation":["단위가 다르면 같은 단위로 고쳐 견줘요.","700000 cm³ = 0.7 m³, ㉢는 2 × 1 × 1 = 2(m³)예요.","큰 것부터 ㉢, ㉡, ㉠예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L06_challenge#10','math',6,1,'u6','L06','g6_1_math_u6_L06_challenge','lesson_challenge','M6-1-u6-C6',4,'essay','teacher','하린이는 「1 m = 100 cm이니까 1 m³ = 100 cm³야.」라고 말했어요. 잘못된 점을 고치고, 1 m³가 몇 cm³인지 까닭과 함께 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u6-C6","difficulty":4,"kind":"essay","stem":"하린이는 「1 m = 100 cm이니까 1 m³ = 100 cm³야.」라고 말했어요. 잘못된 점을 고치고, 1 m³가 몇 cm³인지 까닭과 함께 써 보세요.","answer_guide":{"answer":"예: 부피는 가로·세로·높이 세 방향의 길이를 곱한다. 1 m³는 한 모서리가 100 cm인 정육면체이므로 1 cm³ 쌓기나무가 한 층에 100 × 100 = 10000개, 100층 들어간다. 10000 × 100 = 1000000이므로 1 m³ = 1000000 cm³이다.","scoring_points":["100 cm³가 잘못이라고 했는가","세 방향(100 × 100 × 100)을 곱한다고 설명했는가","1000000 cm³를 구했는가"]},"explanation":["한 모서리 1 m = 100 cm예요.","100 × 100 × 100 = 1000000이에요.","그래서 1 m³ = 1000000 cm³예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L07_basic#1','math',6,1,'u6','L07','g6_1_math_u6_L07_basic','lesson_basic','M6-1-u6-C7',1,'mc','auto','직육면체 모양 두부를 똑같이 2조각으로 자르면 두 조각의 부피의 합은 어떻게 되나요?',ARRAY['M6-1-u6-X15','M6-1-u6-X16']::text[],true,'{"seq":1,"concept":"M6-1-u6-C7","difficulty":1,"kind":"mc","stem":"직육면체 모양 두부를 똑같이 2조각으로 자르면 두 조각의 부피의 합은 어떻게 되나요?","options":[{"t":"자르기 전과 같아요","correct":true},{"t":"절반으로 줄어요","mis":"M6-1-u6-X15"},{"t":"두 배가 돼요","mis":"M6-1-u6-X15"},{"t":"자른 면만큼 늘어나요","mis":"M6-1-u6-X16"}],"explanation":["자른 조각을 도로 붙이면 처음 두부가 되므로 부피의 합은 그대로예요.","한 번 자를 때마다 자른 자리에 마주 보는 새 면 2개가 드러나요.","그래서 겉넓이는 자른 면만큼 늘어나요."],"variant_rule":{"alt":[{"stem":"직육면체 모양 두부를 자르면 겉넓이의 합은 어떻게 되나요?","options":[{"t":"자른 면만큼 늘어나요","correct":true},{"t":"그대로예요","mis":"M6-1-u6-X16"},{"t":"줄어들어요","mis":"M6-1-u6-X16"},{"t":"절반이 돼요","mis":"M6-1-u6-X15"}],"explanation":["자른 조각을 도로 붙이면 처음 두부가 되므로 부피의 합은 그대로예요.","한 번 자를 때마다 자른 자리에 마주 보는 새 면 2개가 드러나요.","그래서 겉넓이는 자른 면만큼 늘어나요."]},{"stem":"두부를 한 번 자르면 겉면이 새로 몇 개 생기나요?","options":[{"t":"2개","correct":true},{"t":"1개","mis":"M6-1-u6-X16"},{"t":"4개","mis":"M6-1-u6-X16"},{"t":"생기지 않아요","mis":"M6-1-u6-X16"}],"explanation":["자른 조각을 도로 붙이면 처음 두부가 되므로 부피의 합은 그대로예요.","한 번 자를 때마다 자른 자리에 마주 보는 새 면 2개가 드러나요.","그래서 겉넓이는 자른 면만큼 늘어나요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L07_basic#2','math',6,1,'u6','L07','g6_1_math_u6_L07_basic','lesson_basic','M6-1-u6-C7',1,'sa','auto','가로 10 cm, 세로 10 cm, 높이 5 cm인 직육면체 모양 두부의 부피는 몇 cm³인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u6-C7","difficulty":1,"kind":"sa","stem":"가로 10 cm, 세로 10 cm, 높이 5 cm인 직육면체 모양 두부의 부피는 몇 cm³인가요? 숫자로 쓰세요.","answer":["500"],"explanation":["직육면체의 부피는 가로 × 세로 × 높이예요.","10 × 10 × 5 = 500이에요.","그래서 500 cm³예요."],"mis":"M6-1-u6-X11","asset":{"type":"geo","items":[{"w":226.0,"h":136.6,"pts":{"ㄱ":[63.3,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,63.3,"w"],"ㄷ":[126.7,63.3,"sw"],"ㅁ":[63.3,63.3,"ne"],"ㅇ":[190.0,63.3,"e"],"ㅂ":[0,126.6,"sw"],"ㅅ":[126.7,126.6,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[63.4,139.6],"10 cm"],[[180.3,100.9],"10 cm"],[[216.0,31.6],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 8 cm, 세로 6 cm, 높이 5 cm인 직육면체 모양 두부의 부피는 몇 cm³인가요? 숫자로 쓰세요.","answer":["240"],"explanation":["직육면체의 부피는 가로 × 세로 × 높이예요.","8 × 6 × 5 = 240이에요.","그래서 240 cm³예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":148.2,"pts":{"ㄱ":[51.8,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,51.8,"w"],"ㄷ":[138.2,51.8,"sw"],"ㅁ":[51.8,86.4,"ne"],"ㅇ":[190.0,86.4,"e"],"ㅂ":[0,138.2,"sw"],"ㅅ":[138.2,138.2,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[69.1,151.2],"8 cm"],[[186.1,118.3],"6 cm"],[[216.0,43.2],"5 cm"]]}],"tag":false}},{"stem":"가로 12 cm, 세로 10 cm, 높이 4 cm인 직육면체 모양 두부의 부피는 몇 cm³인가요? 숫자로 쓰세요.","answer":["480"],"explanation":["직육면체의 부피는 가로 × 세로 × 높이예요.","12 × 10 × 4 = 480이에요.","그래서 480 cm³예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":110.6,"pts":{"ㄱ":[55.9,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,55.9,"w"],"ㄷ":[134.1,55.9,"sw"],"ㅁ":[55.9,44.7,"ne"],"ㅇ":[190.0,44.7,"e"],"ㅂ":[0,100.6,"sw"],"ㅅ":[134.1,100.6,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[67.0,113.6],"12 cm"],[[184.0,78.7],"10 cm"],[[216.0,22.4],"4 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L07_basic#3','math',6,1,'u6','L07','g6_1_math_u6_L07_basic','lesson_basic','M6-1-u6-C7',1,'ox','auto','두부를 자르면 조각들의 부피의 합은 처음과 같아요.',ARRAY['M6-1-u6-X15']::text[],true,'{"seq":3,"concept":"M6-1-u6-C7","difficulty":1,"kind":"ox","stem":"두부를 자르면 조각들의 부피의 합은 처음과 같아요.","answer":"O","reason_options":[{"t":"조각을 도로 붙이면 처음 두부가 되기 때문에","correct":true},{"t":"잘라 낸 만큼 부피가 늘어나기 때문에","mis":"M6-1-u6-X15"}],"mis":"M6-1-u6-X15","explanation":["잘라도 조각을 모두 모으면 처음과 같아 부피는 변하지 않아요.","한 번 자를 때마다 새 면이 2개씩 생겨 겉넓이는 늘어나요.","부피와 겉넓이는 서로 다른 양이에요."],"variant_rule":{"alt":[{"stem":"두부를 자르면 조각들의 겉넓이의 합은 처음과 같아요.","answer":"X","reason_options":[{"t":"자른 자리에 새 겉면이 생겨 겉넓이가 늘어나기 때문에","correct":true},{"t":"부피가 그대로이니 겉넓이도 그대로이기 때문에","mis":"M6-1-u6-X16"}],"explanation":["잘라도 조각을 모두 모으면 처음과 같아 부피는 변하지 않아요.","한 번 자를 때마다 새 면이 2개씩 생겨 겉넓이는 늘어나요.","부피와 겉넓이는 서로 다른 양이에요."]},{"stem":"두부를 똑같이 4조각으로 자르면 한 조각의 부피는 처음 부피를 4로 나눈 것과 같아요.","answer":"O","reason_options":[{"t":"부피의 합은 그대로이고 똑같이 나누었기 때문에","correct":true},{"t":"자를수록 부피의 합이 줄어들기 때문에","mis":"M6-1-u6-X15"}],"explanation":["잘라도 조각을 모두 모으면 처음과 같아 부피는 변하지 않아요.","한 번 자를 때마다 새 면이 2개씩 생겨 겉넓이는 늘어나요.","부피와 겉넓이는 서로 다른 양이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L07_basic#4','math',6,1,'u6','L07','g6_1_math_u6_L07_basic','lesson_basic','M6-1-u6-C7',1,'sa','auto','가로 10 cm, 세로 10 cm, 높이 5 cm인 두부를 가로가 똑같이 나뉘도록 2조각으로 잘랐어요. 자른 면 한 개의 넓이는 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u6-C7","difficulty":1,"kind":"sa","stem":"가로 10 cm, 세로 10 cm, 높이 5 cm인 두부를 가로가 똑같이 나뉘도록 2조각으로 잘랐어요. 자른 면 한 개의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["자른 면은 세로 × 높이인 직사각형이에요.","10 × 5 = 50이에요.","그래서 50 cm²예요."],"mis":"M6-1-u6-X16","asset":{"type":"geo","items":[{"w":226.0,"h":136.6,"pts":{"ㄱ":[63.3,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,63.3,"w"],"ㄷ":[126.7,63.3,"sw"],"ㅁ":[63.3,63.3,"ne"],"ㅇ":[190.0,63.3,"e"],"ㅂ":[0,126.6,"sw"],"ㅅ":[126.7,126.6,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[63.4,139.6],"10 cm"],[[180.3,100.9],"10 cm"],[[216.0,31.6],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 8 cm, 세로 6 cm, 높이 5 cm인 두부를 가로가 똑같이 나뉘도록 2조각으로 잘랐어요. 자른 면 한 개의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["자른 면은 세로 × 높이인 직사각형이에요.","6 × 5 = 30이에요.","그래서 30 cm²예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":148.2,"pts":{"ㄱ":[51.8,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,51.8,"w"],"ㄷ":[138.2,51.8,"sw"],"ㅁ":[51.8,86.4,"ne"],"ㅇ":[190.0,86.4,"e"],"ㅂ":[0,138.2,"sw"],"ㅅ":[138.2,138.2,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[69.1,151.2],"8 cm"],[[186.1,118.3],"6 cm"],[[216.0,43.2],"5 cm"]]}],"tag":false}},{"stem":"가로 12 cm, 세로 10 cm, 높이 4 cm인 두부를 가로가 똑같이 나뉘도록 2조각으로 잘랐어요. 자른 면 한 개의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["자른 면은 세로 × 높이인 직사각형이에요.","10 × 4 = 40이에요.","그래서