INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L07_basic#5','math',6,1,'u6','L07','g6_1_math_u6_L07_basic','lesson_basic','M6-1-u6-C7',2,'sa','auto','가로 10 cm, 세로 10 cm, 높이 5 cm인 직육면체 모양 두부의 겉넓이는 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u6-C7","difficulty":2,"kind":"sa","stem":"가로 10 cm, 세로 10 cm, 높이 5 cm인 직육면체 모양 두부의 겉넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["400"],"explanation":["서로 다른 세 면의 넓이는 10 × 10 + 10 × 5 + 10 × 5 = 200이에요.","마주 보는 면이 합동이라 200 × 2 = 400(cm²)예요.","그래서 400 cm²예요."],"mis":"M6-1-u6-X03","asset":{"type":"geo","items":[{"w":226.0,"h":136.6,"pts":{"ㄱ":[63.3,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,63.3,"w"],"ㄷ":[126.7,63.3,"sw"],"ㅁ":[63.3,63.3,"ne"],"ㅇ":[190.0,63.3,"e"],"ㅂ":[0,126.6,"sw"],"ㅅ":[126.7,126.6,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[63.4,139.6],"10 cm"],[[180.3,100.9],"10 cm"],[[216.0,31.6],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 8 cm, 세로 6 cm, 높이 5 cm인 직육면체 모양 두부의 겉넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["236"],"explanation":["서로 다른 세 면의 넓이는 8 × 6 + 8 × 5 + 6 × 5 = 118이에요.","마주 보는 면이 합동이라 118 × 2 = 236(cm²)예요.","그래서 236 cm²예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":148.2,"pts":{"ㄱ":[51.8,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,51.8,"w"],"ㄷ":[138.2,51.8,"sw"],"ㅁ":[51.8,86.4,"ne"],"ㅇ":[190.0,86.4,"e"],"ㅂ":[0,138.2,"sw"],"ㅅ":[138.2,138.2,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[69.1,151.2],"8 cm"],[[186.1,118.3],"6 cm"],[[216.0,43.2],"5 cm"]]}],"tag":false}},{"stem":"가로 12 cm, 세로 10 cm, 높이 4 cm인 직육면체 모양 두부의 겉넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["416"],"explanation":["서로 다른 세 면의 넓이는 12 × 10 + 12 × 4 + 10 × 4 = 208이에요.","마주 보는 면이 합동이라 208 × 2 = 416(cm²)예요.","그래서 416 cm²예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":110.6,"pts":{"ㄱ":[55.9,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,55.9,"w"],"ㄷ":[134.1,55.9,"sw"],"ㅁ":[55.9,44.7,"ne"],"ㅇ":[190.0,44.7,"e"],"ㅂ":[0,100.6,"sw"],"ㅅ":[134.1,100.6,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[67.0,113.6],"12 cm"],[[184.0,78.7],"10 cm"],[[216.0,22.4],"4 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L07_basic#6','math',6,1,'u6','L07','g6_1_math_u6_L07_basic','lesson_basic','M6-1-u6-C7',2,'sa','auto','가로 10 cm, 세로 10 cm, 높이 5 cm인 두부(겉넓이 400 cm²)를 가로가 똑같이 나뉘도록 2조각으로 잘랐어요. 조각들의 겉넓이를 모두 더하면 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u6-C7","difficulty":2,"kind":"sa","stem":"가로 10 cm, 세로 10 cm, 높이 5 cm인 두부(겉넓이 400 cm²)를 가로가 똑같이 나뉘도록 2조각으로 잘랐어요. 조각들의 겉넓이를 모두 더하면 몇 cm²인가요? 숫자로 쓰세요.","answer":["500"],"explanation":["2조각이 되려면 1번 잘라야 하고, 한 번 자를 때마다 10 × 5 = 50(cm²)인 새 면이 2개씩 생겨요.","새 면은 1 × 2 = 2개이고, 400 + 50 × 2 = 500이에요.","그래서 500 cm²예요."],"mis":"M6-1-u6-X16","asset":{"type":"geo","items":[{"w":226.0,"h":136.6,"pts":{"ㄱ":[63.3,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,63.3,"w"],"ㄷ":[126.7,63.3,"sw"],"ㅁ":[63.3,63.3,"ne"],"ㅇ":[190.0,63.3,"e"],"ㅂ":[0,126.6,"sw"],"ㅅ":[126.7,126.6,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[63.4,139.6],"10 cm"],[[180.3,100.9],"10 cm"],[[216.0,31.6],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 8 cm, 세로 6 cm, 높이 5 cm인 두부(겉넓이 236 cm²)를 가로가 똑같이 나뉘도록 2조각으로 잘랐어요. 조각들의 겉넓이를 모두 더하면 몇 cm²인가요? 숫자로 쓰세요.","answer":["296"],"explanation":["2조각이 되려면 1번 잘라야 하고, 한 번 자를 때마다 6 × 5 = 30(cm²)인 새 면이 2개씩 생겨요.","새 면은 1 × 2 = 2개이고, 236 + 30 × 2 = 296이에요.","그래서 296 cm²예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":148.2,"pts":{"ㄱ":[51.8,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,51.8,"w"],"ㄷ":[138.2,51.8,"sw"],"ㅁ":[51.8,86.4,"ne"],"ㅇ":[190.0,86.4,"e"],"ㅂ":[0,138.2,"sw"],"ㅅ":[138.2,138.2,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[69.1,151.2],"8 cm"],[[186.1,118.3],"6 cm"],[[216.0,43.2],"5 cm"]]}],"tag":false}},{"stem":"가로 12 cm, 세로 10 cm, 높이 4 cm인 두부(겉넓이 416 cm²)를 가로가 똑같이 나뉘도록 2조각으로 잘랐어요. 조각들의 겉넓이를 모두 더하면 몇 cm²인가요? 숫자로 쓰세요.","answer":["496"],"explanation":["2조각이 되려면 1번 잘라야 하고, 한 번 자를 때마다 10 × 4 = 40(cm²)인 새 면이 2개씩 생겨요.","새 면은 1 × 2 = 2개이고, 416 + 40 × 2 = 496이에요.","그래서 496 cm²예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":110.6,"pts":{"ㄱ":[55.9,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,55.9,"w"],"ㄷ":[134.1,55.9,"sw"],"ㅁ":[55.9,44.7,"ne"],"ㅇ":[190.0,44.7,"e"],"ㅂ":[0,100.6,"sw"],"ㅅ":[134.1,100.6,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[67.0,113.6],"12 cm"],[[184.0,78.7],"10 cm"],[[216.0,22.4],"4 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L07_basic#7','math',6,1,'u6','L07','g6_1_math_u6_L07_basic','lesson_basic','M6-1-u6-C7',2,'sa','auto','가로 10 cm, 세로 10 cm, 높이 5 cm인 두부를 가로가 똑같이 나뉘도록 2조각으로 잘랐어요. 한 조각의 부피는 몇 cm³인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u6-C7","difficulty":2,"kind":"sa","stem":"가로 10 cm, 세로 10 cm, 높이 5 cm인 두부를 가로가 똑같이 나뉘도록 2조각으로 잘랐어요. 한 조각의 부피는 몇 cm³인가요? 숫자로 쓰세요.","answer":["250"],"explanation":["두부 전체의 부피는 10 × 10 × 5 = 500(cm³)예요.","똑같이 2조각이므로 500 ÷ 2 = 250이에요.","그래서 한 조각은 250 cm³예요."],"mis":"M6-1-u6-X15","asset":{"type":"geo","items":[{"w":226.0,"h":136.6,"pts":{"ㄱ":[63.3,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,63.3,"w"],"ㄷ":[126.7,63.3,"sw"],"ㅁ":[63.3,63.3,"ne"],"ㅇ":[190.0,63.3,"e"],"ㅂ":[0,126.6,"sw"],"ㅅ":[126.7,126.6,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[63.4,139.6],"10 cm"],[[180.3,100.9],"10 cm"],[[216.0,31.6],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 8 cm, 세로 6 cm, 높이 5 cm인 두부를 가로가 똑같이 나뉘도록 2조각으로 잘랐어요. 한 조각의 부피는 몇 cm³인가요? 숫자로 쓰세요.","answer":["120"],"explanation":["두부 전체의 부피는 8 × 6 × 5 = 240(cm³)예요.","똑같이 2조각이므로 240 ÷ 2 = 120이에요.","그래서 한 조각은 120 cm³예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":148.2,"pts":{"ㄱ":[51.8,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,51.8,"w"],"ㄷ":[138.2,51.8,"sw"],"ㅁ":[51.8,86.4,"ne"],"ㅇ":[190.0,86.4,"e"],"ㅂ":[0,138.2,"sw"],"ㅅ":[138.2,138.2,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[69.1,151.2],"8 cm"],[[186.1,118.3],"6 cm"],[[216.0,43.2],"5 cm"]]}],"tag":false}},{"stem":"가로 12 cm, 세로 10 cm, 높이 4 cm인 두부를 가로가 똑같이 나뉘도록 2조각으로 잘랐어요. 한 조각의 부피는 몇 cm³인가요? 숫자로 쓰세요.","answer":["240"],"explanation":["두부 전체의 부피는 12 × 10 × 4 = 480(cm³)예요.","똑같이 2조각이므로 480 ÷ 2 = 240이에요.","그래서 한 조각은 240 cm³예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":110.6,"pts":{"ㄱ":[55.9,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,55.9,"w"],"ㄷ":[134.1,55.9,"sw"],"ㅁ":[55.9,44.7,"ne"],"ㅇ":[190.0,44.7,"e"],"ㅂ":[0,100.6,"sw"],"ㅅ":[134.1,100.6,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[67.0,113.6],"12 cm"],[[184.0,78.7],"10 cm"],[[216.0,22.4],"4 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L07_basic#8','math',6,1,'u6','L07','g6_1_math_u6_L07_basic','lesson_basic','M6-1-u6-C7',2,'mc','auto','두부를 2조각, 4조각으로 자를 때 조각들의 부피의 합을 바르게 비교한 것은 어느 것인가요?',ARRAY['M6-1-u6-X15','M6-1-u6-X18']::text[],true,'{"seq":8,"concept":"M6-1-u6-C7","difficulty":2,"kind":"mc","stem":"두부를 2조각, 4조각으로 자를 때 조각들의 부피의 합을 바르게 비교한 것은 어느 것인가요?","options":[{"t":"자르기 전과 2조각·4조각 모두 같아요","correct":true},{"t":"자를수록 커져요","mis":"M6-1-u6-X15"},{"t":"자를수록 작아져요","mis":"M6-1-u6-X15"},{"t":"알 수 없어요","mis":"M6-1-u6-X18"}],"explanation":["자른 조각을 도로 붙이면 처음 두부가 되므로 부피의 합은 그대로예요.","한 번 자를 때마다 자른 자리에 마주 보는 새 면 2개가 드러나요.","그래서 겉넓이는 자른 면만큼 늘어나요."],"variant_rule":{"alt":[{"stem":"두부를 한 번 자르면 겉면이 새로 몇 개 생기나요?","options":[{"t":"2개","correct":true},{"t":"1개","mis":"M6-1-u6-X16"},{"t":"4개","mis":"M6-1-u6-X16"},{"t":"생기지 않아요","mis":"M6-1-u6-X16"}],"explanation":["자른 조각을 도로 붙이면 처음 두부가 되므로 부피의 합은 그대로예요.","한 번 자를 때마다 자른 자리에 마주 보는 새 면 2개가 드러나요.","그래서 겉넓이는 자른 면만큼 늘어나요."]},{"stem":"직육면체 모양 두부를 똑같이 2조각으로 자르면 두 조각의 부피의 합은 어떻게 되나요?","options":[{"t":"자르기 전과 같아요","correct":true},{"t":"절반으로 줄어요","mis":"M6-1-u6-X15"},{"t":"두 배가 돼요","mis":"M6-1-u6-X15"},{"t":"자른 면만큼 늘어나요","mis":"M6-1-u6-X16"}],"explanation":["자른 조각을 도로 붙이면 처음 두부가 되므로 부피의 합은 그대로예요.","한 번 자를 때마다 자른 자리에 마주 보는 새 면 2개가 드러나요.","그래서 겉넓이는 자른 면만큼 늘어나요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L07_basic#9','math',6,1,'u6','L07','g6_1_math_u6_L07_basic','lesson_basic','M6-1-u6-C7',2,'ox','auto','두부를 한 번 자르면 새 면이 1개 생겨요.',ARRAY['M6-1-u6-X16']::text[],true,'{"seq":9,"concept":"M6-1-u6-C7","difficulty":2,"kind":"ox","stem":"두부를 한 번 자르면 새 면이 1개 생겨요.","answer":"X","reason_options":[{"t":"자른 자리의 양쪽 조각에 마주 보는 새 면이 하나씩, 모두 2개 생기기 때문에","correct":true},{"t":"칼이 지나간 자리는 한 군데이기 때문에","mis":"M6-1-u6-X16"}],"mis":"M6-1-u6-X16","explanation":["잘라도 조각을 모두 모으면 처음과 같아 부피는 변하지 않아요.","한 번 자를 때마다 새 면이 2개씩 생겨 겉넓이는 늘어나요.","부피와 겉넓이는 서로 다른 양이에요."],"variant_rule":{"alt":[{"stem":"부피가 그대로이면 겉넓이도 언제나 그대로예요.","answer":"X","reason_options":[{"t":"부피와 겉넓이는 서로 다른 양이라 하나만 바뀔 수 있기 때문에","correct":true},{"t":"부피와 겉넓이는 늘 함께 바뀌기 때문에","mis":"M6-1-u6-X17"}],"explanation":["잘라도 조각을 모두 모으면 처음과 같아 부피는 변하지 않아요.","한 번 자를 때마다 새 면이 2개씩 생겨 겉넓이는 늘어나요.","부피와 겉넓이는 서로 다른 양이에요."]},{"stem":"두부를 자르면 조각들의 겉넓이의 합은 처음과 같아요.","answer":"X","reason_options":[{"t":"자른 자리에 새 겉면이 생겨 겉넓이가 늘어나기 때문에","correct":true},{"t":"부피가 그대로이니 겉넓이도 그대로이기 때문에","mis":"M6-1-u6-X16"}],"explanation":["잘라도 조각을 모두 모으면 처음과 같아 부피는 변하지 않아요.","한 번 자를 때마다 새 면이 2개씩 생겨 겉넓이는 늘어나요.","부피와 겉넓이는 서로 다른 양이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L07_basic#10','math',6,1,'u6','L07','g6_1_math_u6_L07_basic','lesson_basic','M6-1-u6-C7',3,'error','auto','가로 10 cm, 세로 10 cm, 높이 5 cm인 두부(겉넓이 400 cm²)를 가로가 똑같이 나뉘도록 2조각으로 잘랐어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u6-X15','M6-1-u6-X18']::text[],true,'{"seq":10,"concept":"M6-1-u6-C7","difficulty":3,"kind":"error","stem":"가로 10 cm, 세로 10 cm, 높이 5 cm인 두부(겉넓이 400 cm²)를 가로가 똑같이 나뉘도록 2조각으로 잘랐어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「잘랐으니까 두 조각의 부피를 더하면 500 cm³보다 작아.」","correct":true,"mis_target":"M6-1-u6-X15"},{"t":"도윤 — 「두 조각의 겉넓이를 더하면 400 + 50 × 2 = 500(cm²)야.」","mis":"M6-1-u6-X18"},{"t":"서아 — 「두 조각의 부피를 더하면 500 cm³ 그대로야.」","mis":"M6-1-u6-X18"}],"explanation":["두 조각을 도로 붙이면 처음 두부가 돼요.","그래서 부피의 합은 10 × 10 × 5 = 500(cm³) 그대로예요.","하린은 자르면 부피가 줄어든다고 잘못 생각했어요."],"asset":{"type":"geo","items":[{"w":226.0,"h":136.6,"pts":{"ㄱ":[63.3,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,63.3,"w"],"ㄷ":[126.7,63.3,"sw"],"ㅁ":[63.3,63.3,"ne"],"ㅇ":[190.0,63.3,"e"],"ㅂ":[0,126.6,"sw"],"ㅅ":[126.7,126.6,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[63.4,139.6],"10 cm"],[[180.3,100.9],"10 cm"],[[216.0,31.6],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 8 cm, 세로 6 cm, 높이 5 cm인 두부(겉넓이 236 cm²)를 가로가 똑같이 나뉘도록 2조각으로 잘랐어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「잘랐으니까 두 조각의 부피를 더하면 240 cm³보다 작아.」","correct":true,"mis_target":"M6-1-u6-X15"},{"t":"예준 — 「두 조각의 겉넓이를 더하면 236 + 30 × 2 = 296(cm²)야.」","mis":"M6-1-u6-X18"},{"t":"나린 — 「두 조각의 부피를 더하면 240 cm³ 그대로야.」","mis":"M6-1-u6-X18"}],"explanation":["두 조각을 도로 붙이면 처음 두부가 돼요.","그래서 부피의 합은 8 × 6 × 5 = 240(cm³) 그대로예요.","수아는 자르면 부피가 줄어든다고 잘못 생각했어요."],"asset":{"type":"geo","items":[{"w":226.0,"h":148.2,"pts":{"ㄱ":[51.8,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,51.8,"w"],"ㄷ":[138.2,51.8,"sw"],"ㅁ":[51.8,86.4,"ne"],"ㅇ":[190.0,86.4,"e"],"ㅂ":[0,138.2,"sw"],"ㅅ":[138.2,138.2,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[69.1,151.2],"8 cm"],[[186.1,118.3],"6 cm"],[[216.0,43.2],"5 cm"]]}],"tag":false}},{"stem":"가로 12 cm, 세로 10 cm, 높이 4 cm인 두부(겉넓이 416 cm²)를 가로가 똑같이 나뉘도록 2조각으로 잘랐어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「잘랐으니까 두 조각의 부피를 더하면 480 cm³보다 작아.」","correct":true,"mis_target":"M6-1-u6-X15"},{"t":"유진 — 「두 조각의 겉넓이를 더하면 416 + 40 × 2 = 496(cm²)야.」","mis":"M6-1-u6-X18"},{"t":"라온 — 「두 조각의 부피를 더하면 480 cm³ 그대로야.」","mis":"M6-1-u6-X18"}],"explanation":["두 조각을 도로 붙이면 처음 두부가 돼요.","그래서 부피의 합은 12 × 10 × 4 = 480(cm³) 그대로예요.","가온은 자르면 부피가 줄어든다고 잘못 생각했어요."],"asset":{"type":"geo","items":[{"w":226.0,"h":110.6,"pts":{"ㄱ":[55.9,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,55.9,"w"],"ㄷ":[134.1,55.9,"sw"],"ㅁ":[55.9,44.7,"ne"],"ㅇ":[190.0,44.7,"e"],"ㅂ":[0,100.6,"sw"],"ㅅ":[134.1,100.6,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[67.0,113.6],"12 cm"],[[184.0,78.7],"10 cm"],[[216.0,22.4],"4 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L07_challenge#1','math',6,1,'u6','L07','g6_1_math_u6_L07_challenge','lesson_challenge','M6-1-u6-C7',2,'sa','auto','가로 10 cm, 세로 10 cm, 높이 5 cm인 두부를 가로가 똑같이 나뉘도록 2조각으로 잘랐어요. 조각들의 겉넓이의 합은 처음보다 몇 cm² 늘어났나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u6-C7","difficulty":2,"kind":"sa","stem":"가로 10 cm, 세로 10 cm, 높이 5 cm인 두부를 가로가 똑같이 나뉘도록 2조각으로 잘랐어요. 조각들의 겉넓이의 합은 처음보다 몇 cm² 늘어났나요? 숫자로 쓰세요.","answer":["100"],"explanation":["1번 자르면 새 면이 1 × 2 = 2개 생겨요.","새 면 하나는 10 × 5 = 50, 50 × 2 = 100이에요.","그래서 100 cm² 늘어났어요."],"mis":"M6-1-u6-X16","asset":{"type":"geo","items":[{"w":226.0,"h":136.6,"pts":{"ㄱ":[63.3,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,63.3,"w"],"ㄷ":[126.7,63.3,"sw"],"ㅁ":[63.3,63.3,"ne"],"ㅇ":[190.0,63.3,"e"],"ㅂ":[0,126.6,"sw"],"ㅅ":[126.7,126.6,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[63.4,139.6],"10 cm"],[[180.3,100.9],"10 cm"],[[216.0,31.6],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 8 cm, 세로 6 cm, 높이 5 cm인 두부를 가로가 똑같이 나뉘도록 2조각으로 잘랐어요. 조각들의 겉넓이의 합은 처음보다 몇 cm² 늘어났나요? 숫자로 쓰세요.","answer":["60"],"explanation":["1번 자르면 새 면이 1 × 2 = 2개 생겨요.","새 면 하나는 6 × 5 = 30, 30 × 2 = 60이에요.","그래서 60 cm² 늘어났어요."],"asset":{"type":"geo","items":[{"w":226.0,"h":148.2,"pts":{"ㄱ":[51.8,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,51.8,"w"],"ㄷ":[138.2,51.8,"sw"],"ㅁ":[51.8,86.4,"ne"],"ㅇ":[190.0,86.4,"e"],"ㅂ":[0,138.2,"sw"],"ㅅ":[138.2,138.2,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[69.1,151.2],"8 cm"],[[186.1,118.3],"6 cm"],[[216.0,43.2],"5 cm"]]}],"tag":false}},{"stem":"가로 12 cm, 세로 10 cm, 높이 4 cm인 두부를 가로가 똑같이 나뉘도록 2조각으로 잘랐어요. 조각들의 겉넓이의 합은 처음보다 몇 cm² 늘어났나요? 숫자로 쓰세요.","answer":["80"],"explanation":["1번 자르면 새 면이 1 × 2 = 2개 생겨요.","새 면 하나는 10 × 4 = 40, 40 × 2 = 80이에요.","그래서 80 cm² 늘어났어요."],"asset":{"type":"geo","items":[{"w":226.0,"h":110.6,"pts":{"ㄱ":[55.9,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,55.9,"w"],"ㄷ":[134.1,55.9,"sw"],"ㅁ":[55.9,44.7,"ne"],"ㅇ":[190.0,44.7,"e"],"ㅂ":[0,100.6,"sw"],"ㅅ":[134.1,100.6,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[67.0,113.6],"12 cm"],[[184.0,78.7],"10 cm"],[[216.0,22.4],"4 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L07_challenge#2','math',6,1,'u6','L07','g6_1_math_u6_L07_challenge','lesson_challenge','M6-1-u6-C7',2,'sa','auto','가로 10 cm, 세로 8 cm, 높이 5 cm인 두부를 세로가 똑같이 나뉘도록 2조각으로 잘랐어요. 자른 면 한 개의 넓이는 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u6-C7","difficulty":2,"kind":"sa","stem":"가로 10 cm, 세로 8 cm, 높이 5 cm인 두부를 세로가 똑같이 나뉘도록 2조각으로 잘랐어요. 자른 면 한 개의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["자른 면은 가로 × 높이인 직사각형이에요.","10 × 5 = 50이에요.","그래서 50 cm²예요."],"mis":"M6-1-u6-X16","asset":{"type":"geo","items":[{"w":226.0,"h":132.2,"pts":{"ㄱ":[54.3,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,54.3,"w"],"ㄷ":[135.7,54.3,"sw"],"ㅁ":[54.3,67.9,"ne"],"ㅇ":[190.0,67.9,"e"],"ㅂ":[0,122.2,"sw"],"ㅅ":[135.7,122.2,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[67.8,135.2],"10 cm"],[[184.8,101.1],"8 cm"],[[216.0,34.0],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 12 cm, 세로 6 cm, 높이 5 cm인 두부를 높이가 똑같이 나뉘도록 2조각으로 잘랐어요. 자른 면 한 개의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["72"],"explanation":["자른 면은 가로 × 세로인 직사각형이에요.","12 × 6 = 72예요.","그래서 72 cm²예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":111.3,"pts":{"ㄱ":[38.0,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,38.0,"w"],"ㄷ":[152.0,38.0,"sw"],"ㅁ":[38.0,63.3,"ne"],"ㅇ":[190.0,63.3,"e"],"ㅂ":[0,101.3,"sw"],"ㅅ":[152.0,101.3,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[76.0,114.3],"12 cm"],[[193.0,88.3],"6 cm"],[[216.0,31.6],"5 cm"]]}],"tag":false}},{"stem":"가로 9 cm, 세로 8 cm, 높이 4 cm인 두부를 높이가 똑같이 나뉘도록 2조각으로 잘랐어요. 자른 면 한 개의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["72"],"explanation":["자른 면은 가로 × 세로인 직사각형이에요.","9 × 8 = 72예요.