INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_review_a#18','math',6,1,'u6','','g6_1_math_u6_review_a','unit_review','M6-1-u6-C2',3,'mc','auto','포장지를 겹치거나 남기지 않고 붙이려고 해요. 상자 가는 가로 20 cm, 세로 15 cm, 높이 4 cm, 상자 나는 가로 10 cm, 세로 15 cm, 높이 8 cm예요. 포장지가 덜 드는 상자는 어느 것인가요?',ARRAY['M6-1-u6-X03','M6-1-u6-X17','M6-1-u6-X18']::text[],true,'{"seq":18,"concept":"M6-1-u6-C2","difficulty":3,"kind":"mc","stem":"포장지를 겹치거나 남기지 않고 붙이려고 해요. 상자 가는 가로 20 cm, 세로 15 cm, 높이 4 cm, 상자 나는 가로 10 cm, 세로 15 cm, 높이 8 cm예요. 포장지가 덜 드는 상자는 어느 것인가요?","options":[{"t":"나","correct":true},{"t":"가","mis":"M6-1-u6-X03"},{"t":"둘이 같아요","mis":"M6-1-u6-X17"},{"t":"알 수 없어요","mis":"M6-1-u6-X18"}],"explanation":["가의 겉넓이는 20 × 15 + 20 × 4 + 15 × 4 = 440, 440 × 2 = 880(cm²)예요.","나의 겉넓이는 10 × 15 + 10 × 8 + 15 × 8 = 350, 350 × 2 = 700(cm²)예요.","겉넓이가 더 작은 나가 포장지가 덜 들어요."],"asset":{"type":"geo","items":[{"w":226.0,"h":89.4,"pts":{"ㄱ":[51.8,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,51.8,"w"],"ㄷ":[138.2,51.8,"sw"],"ㅁ":[51.8,27.6,"ne"],"ㅇ":[190.0,27.6,"e"],"ㅂ":[0,79.4,"sw"],"ㅅ":[138.2,79.4,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[69.1,92.4],"20 cm"],[[186.1,59.5],"15 cm"],[[216.0,13.8],"4 cm"]],"cap":"가"},{"w":226.0,"h":178.3,"pts":{"ㄱ":[81.4,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,81.4,"w"],"ㄷ":[108.6,81.4,"sw"],"ㅁ":[81.4,86.9,"ne"],"ㅇ":[190.0,86.9,"e"],"ㅂ":[0,168.3,"sw"],"ㅅ":[108.6,168.3,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[54.3,181.3],"10 cm"],[[171.3,133.6],"15 cm"],[[216.0,43.5],"8 cm"]],"cap":"나"}],"tag":false},"variant_rule":{"alt":[{"stem":"포장지를 겹치거나 남기지 않고 붙이려고 해요. 상자 가는 가로 9 cm, 세로 6 cm, 높이 4 cm, 상자 나는 가로 8 cm, 세로 8 cm, 높이 4 cm예