INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_review_b#14','math',6,1,'u6','','g6_1_math_u6_review_b','unit_review','M6-1-u6-C3',2,'sa','auto','가로 5 cm, 세로 3 cm, 높이 4 cm인 직육면체의 전개도예요. 옆면 네 개를 이어 붙인 큰 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M6-1-u6-C3","difficulty":2,"kind":"sa","stem":"가로 5 cm, 세로 3 cm, 높이 4 cm인 직육면체의 전개도예요. 옆면 네 개를 이어 붙인 큰 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["옆면을 펼치면 한 장의 직사각형이 되고, 그 가로는 한 밑면의 둘레와 같아요.","5 + 3 + 5 + 3 = 16이에요.","그래서 16 cm예요."],"mis":"M6-1-u6-X05","asset":{"type":"geo","items":[{"w":336.0,"h":178.7,"pts":{},"show":[],"poly":[[[36,0],[120.4,0],[120.4,50.6],[36,50.6]],[[36,118.1],[120.4,118.1],[120.4,168.7],[36,168.7]],[[36,50.6],[120.4,50.6],[120.4,118.1],[36,118.1]],[[120.4,50.6],[171.0,50.6],[171.0,118.1],[120.4,118.1]],[[171.0,50.6],[255.4,50.6],[255.4,118.1],[171.0,118.1]],[[255.4,50.6],[306.0,50.6],[306.0,118.1],[255.4,118.1]]],"lab":[[[78.2,-10],"5 cm"],[[14,25.3],"3 cm"],[[330.0,84.3],"4 cm"],[[213.2,132.1],"옆면의 가로 ?"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 10 cm, 세로 7 cm, 높이 4 cm인 직육면체의 전개도예요. 옆면 네 개를 이어 붙인 큰 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["34"],"explanation":["옆면을 펼치면 한 장의 직사각형이 되고, 그 가로는 한 밑면의 둘레와 같아요.","10 + 7 + 10 + 7 = 34예요.","그래서 34 cm예요."],"asset":{"type":"geo","items":[{"w":336.0,"h":153.0,"pts":{},"show":[],"poly":[[[36,0],[115.4,0],[115.4,55.6],[36,55.6]],[[36,87.4],[115.4,87.4],[115.4,143.0],[36,143.0]],[[36,55.6],[115.4,55.6],[115.4,87.4],[36,87.4]],[[115.4,55.6],[171.0,55.6],[171.0,87.4],[115.4,87.4]],[[171.0,55.6],[250.4,55.6],[250.4,87.4],[171.0,87.4]],[[250.4,55.6],[306.0,55.6],[306.0,87.4],[250.4,87.4]]],"lab":[[[75.7,-10],"10 cm"],[[14,27.8],"7 cm"],[[330.0,71.5],"4 cm"],[[210.7,101.4],"옆면의 가로 ?"]]}],"tag":false}},{"stem":"가로 6 cm, 세로 2 cm, 높이 5 cm인 직육면체의 전개도예요. 옆면 네 개를 이어 붙인 큰 