INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_review_b#21','math',6,1,'u6','','g6_1_math_u6_review_b','unit_review','M6-1-u6-C7',3,'sa','auto','가로 10 cm, 세로 10 cm, 높이 5 cm인 두부(겉넓이 400 cm²)를 가로가 똑같이 나뉘도록 4조각으로 잘랐어요. 조각들의 겉넓이를 모두 더하면 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":21,"concept":"M6-1-u6-C7","difficulty":3,"kind":"sa","stem":"가로 10 cm, 세로 10 cm, 높이 5 cm인 두부(겉넓이 400 cm²)를 가로가 똑같이 나뉘도록 4조각으로 잘랐어요. 조각들의 겉넓이를 모두 더하면 몇 cm²인가요? 숫자로 쓰세요.","answer":["700"],"explanation":["4조각이 되려면 3번 잘라야 하고, 한 번 자를 때마다 10 × 5 = 50(cm²)인 새 면이 2개씩 생겨요.","새 면은 3 × 2 = 6개이고, 400 + 50 × 6 = 700이에요.","그래서 700 cm²예요."],"mis":"M6-1-u6-X16","asset":{"type":"geo","items":[{"w":226.0,"h":136.6,"pts":{"ㄱ":[63.3,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,63.3,"w"],"ㄷ":[126.7,63.3,"sw"],"ㅁ":[63.3,63.3,"ne"],"ㅇ":[190.0,63.3,"e"],"ㅂ":[0,126.6,"sw"],"ㅅ":[126.7,126.6,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[63.4,139.6],"10 cm"],[[180.3,100.9],"10 cm"],[[216.0,31.6],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 8 cm, 세로 6 cm, 높이 5 cm인 두부(겉넓이 236 cm²)를 가로가 똑같이 나뉘도록 2조각으로 잘랐어요. 조각들의 겉넓이를 모두 더하면 몇 cm²인가요? 숫자로 쓰세요.","answer":["296"],"explanation":["2조각이 되려면 1번 잘라야 하고, 한 번 자를 때마다 6 × 5 = 30(cm²)인 새 면이 2개씩 생겨요.","새 면은 1 × 2 = 2개이고, 236 + 30 × 2 = 296이에요.","그래서 296 cm²예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":148.2,"pts":{"ㄱ":[51.8,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,51.8,"w"],"ㄷ":[138.2,51.8,"sw"],"ㅁ":[51.8,86.4,"ne"],"ㅇ":[190.0,86.4,"e"],"ㅂ":[0,138.2,"sw"],"ㅅ":[138.2,138.2,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[69.1,151.2],"8 cm"],[[186.1,118.3],"6 cm"],[[216.0,43.2],"5 cm"]]}],"tag":false}},{"stem":"가로 12 cm, 세로 10 cm, 높이 4 cm인 두부(겉넓이 416 cm²)를 가로가 똑같이 나뉘도록 3조각으로 잘랐어요. 조각들의 겉넓이를 모두 더하면 몇 cm²인가요? 숫자로 쓰세요.","answer":["576"],"explanation":["3조각이 되려면 2번 잘라야 하고, 한 번 자를 때마다 10 × 4 = 40(cm²)인 새 면이 2개씩 생겨요.","새 면은 2 × 2 = 4개이고, 416 + 40 × 4 = 576이에요.","그래서 576 cm²예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":110.6,"pts":{"ㄱ":[55.9,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,55.9,"w"],"ㄷ":[134.1,55.9,"sw"],"ㅁ":[55.9,44.7,"ne"],"ㅇ":[190.0,44.7,"e"],"ㅂ":[0,100.6,"sw"],"ㅅ":[134.1,100.6,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[67.0,113.6],"12 cm"],[[184.0,78.7],"10 cm"],[[216.0,22.4],"4 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_review_b#22','math',6,1,'u6','','g6_1_math_u6_review_b','unit_review','M6-1-u6-C5',3,'mc','auto','직육면체 가는 가로 6 cm, 세로 6 cm, 높이 6 cm, 나는 가로 12 cm, 세로 6 cm, 높이 3 cm예요. 옳은 것은 어느 것인가요?',ARRAY['M6-1-u6-X17','M6-1-u6-X18']::text[],true,'{"seq":22,"concept":"M6-1-u6-C5","difficulty":3,"kind":"mc","stem":"직육면체 가는 가로 6 cm, 세로 6 cm, 높이 6 cm, 나는 가로 12 cm, 세로 6 cm, 높이 3 cm예요. 옳은 것은 어느 것인가요?","options":[{"t":"부피는 같지만 겉넓이는 달라요","correct":true},{"t":"부피가 같으니 겉넓이도 같아요","mis":"M6-1-u6-X17"},{"t":"겉넓이가 다르니 부피도 달라요","mis":"M6-1-u6-X17"},{"t":"부피도 겉넓이도 달라요","mis":"M6-1-u6-X18"}],"explanation":["가의 부피는 6 × 6 × 6 = 216, 나의 부피는 12 × 6 × 3 = 216(cm³)예요.","가의 겉넓이는 216, 나의 겉넓이는 252(cm²)예요.","부피가 같아도 겉넓이는 다를 수 있어요."],"asset":{"type":"geo","items":[{"w":226.0,"h":200.0,"pts":{"ㄱ":[63.3,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,63.3,"w"],"ㄷ":[126.7,63.3,"sw"],"ㅁ":[63.3,126.7,"ne"],"ㅇ":[190.0,126.7,"e"],"ㅂ":[0,190.0,"sw"],"ㅅ":[126.7,190.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[63.4,203.0],"6 cm"],[[180.3,164.3],"6 cm"],[[216.0,63.4],"6 cm"]],"cap":"가"},{"w":226.0,"h":86.0,"pts":{"ㄱ":[38.0,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,38.0,"w"],"ㄷ":[152.0,38.0,"sw"],"ㅁ":[38.0,38.0,"ne"],"ㅇ":[190.0,38.0,"e"],"ㅂ":[0,76.0,"sw"],"ㅅ":[152.0,76.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[76.0,89.0],"12 cm"],[[193.0,63.0],"6 cm"],[[216.0,19.0],"3 cm"]],"cap":"나"}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체 가는 가로 2 cm, 세로 2 cm, 높이 8 cm, 나는 가로 4 cm, 세로 4 cm, 높이 2 cm예요. 옳은 것은 어느 것인가요?","options":[{"t":"부피는 같지만 겉넓이는 달라요","correct":true},{"t":"부피가 같으니 겉넓이도 같아요","mis":"M6-1-u6-X17"},{"t":"겉넓이가 다르니 부피도 달라요","mis":"M6-1-u6-X17"},{"t":"부피도 겉넓이도 달라요","mis":"M6-1-u6-X18"}],"explanation":["가의 부피는 2 × 2 × 8 = 32, 나의 부피는 4 × 4 × 2 = 32(cm³)예요.","가의 겉넓이는 72, 나의 겉넓이는 64(cm²)예요.","부피가 같아도 겉넓이는 다를 수 있어요."],"asset":{"type":"geo","items":[{"w":92.3,"h":178.8,"pts":{"ㄱ":[18.8,0,"nw"],"ㄹ":[56.3,0,"ne"],"ㄴ":[0,18.8,"w"],"ㄷ":[37.5,18.8,"sw"],"ㅁ":[18.8,150.0,"ne"],"ㅇ":[56.3,150.0,"e"],"ㅂ":[0,168.8,"sw"],"ㅅ":[37.5,168.8,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[18.8,181.8],"2 cm"],[[68.9,165.4],"2 cm"],[[82.3,75.0],"8 cm"]],"cap":"가"},{"w":180.0,"h":106.0,"pts":{"ㄱ":[48.0,0,"nw"],"ㄹ":[144.0,0,"ne"],"ㄴ":[0,48.0,"w"],"ㄷ":[96.0,48.0,"sw"],"ㅁ":[48.0,48.0,"ne"],"ㅇ":[144.0,48.0,"e"],"ㅂ":[0,96.0,"sw"],"ㅅ":[96.0,96.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[48.0,109.0],"4 cm"],[[142.0,78.0],"4 cm"],[[170.0,24.0],"2 cm"]],"cap":"나"}],"tag":false}},{"stem":"직육면체 가는 가로 3 cm, 세로 3 cm, 높이 12 cm, 나는 가로 6 cm, 세로 6 cm, 높이 3 cm예요. 옳은 것은 어느 것인가요?","options":[{"t":"부피는 같지만 겉넓이는 달라요","correct":true},{"t":"부피가 같으니 겉넓이도 같아요","mis":"M6-1-u6-X17"},{"t":"겉넓이가 다르니 부피도 달라요","mis":"M6-1-u6-X17"},{"t":"부피도 겉넓이도 달라요","mis":"M6-1-u6-X18"}],"explanation":["가의 부피는 3 × 3 × 12 = 108, 나의 부피는 6 × 6 × 3 = 108(cm³)예요.","가의 겉넓이는 162, 나의 겉넓이는 144(cm²)예요.","부피가 같아도 겉넓이는 다를 수 있어요."],"asset":{"type":"geo","items":[{"w":92.3,"h":178.8,"pts":{"ㄱ":[18.8,0,"nw"],"ㄹ":[56.3,0,"ne"],"ㄴ":[0,18.8,"w"],"ㄷ":[37.5,18.8,"sw"],"ㅁ":[18.8,150.0,"ne"],"ㅇ":[56.3,150.0,"e"],"ㅂ":[0,168.8,"sw"],"ㅅ":[37.5,168.8,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[18.8,181.8],"3 cm"],[[68.9,165.4],"3 cm"],[[82.3,75.0],"12 cm"]],"cap":"가"},{"w":226.0,"h":136.6,"pts":{"ㄱ":[63.3,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,63.3,"w"],"ㄷ":[126.7,63.3,"sw"],"ㅁ":[63.3,63.3,"ne"],"ㅇ":[190.0,63.3,"e"],"ㅂ":[0,126.6,"sw"],"ㅅ":[126.7,126.6,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[63.4,139.6],"6 cm"],[[180.3,100.9],"6 cm"],[[216.0,31.6],"3 cm"]],"cap":"나"}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_review_b#23','math',6,1,'u6','','g6_1_math_u6_review_b','unit_review','M6-1-u6-C3',4,'sa','auto','겉넓이가 294 cm²인 정육면체가 있어요. 한 모서리는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M6-1-u6-C3","difficulty":4,"kind":"sa","stem":"겉넓이가 294 cm²인 정육면체가 있어요. 한 모서리는 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["한 면의 넓이는 294 ÷ 6 = 49예요.","같은 수를 두 번 곱해 49가 되는 수는 7 × 7 = 49이므로 7이에요.","그래서 한 모서리는 7 cm예요."],"mis":"M6-1-u6-X06","variant_rule":{"alt":[{"stem":"한 모서리가 4 cm인 정육면체 두부를 가로·세로·높이를 모두 반으로 잘라 작은 정육면체 8조각을 만들었어요. 8조각의 겉넓이를 모두 더하면 몇 cm²인가요? 숫자로 쓰세요.","answer":["192"],"explanation":["작은 정육면체의 한 모서리는 2 cm이고 겉넓이는 2 × 2 × 6 = 24(cm²)예요.","8조각이므로 24 × 8 = 192예요.","처음 겉넓이 4 × 4 × 6 = 96의 2배예요. 그래서 192 cm²예요."],"asset":{"type":"geo","items":[{"w":180.0,"h":154.0,"pts":{"ㄱ":[48.0,0,"nw"],"ㄹ":[144.0,0,"ne"],"ㄴ":[0,48.0,"w"],"ㄷ":[96.0,48.0,"sw"],"ㅁ":[48.0,96.0,"ne"],"ㅇ":[144.0,96.0,"e"],"ㅂ":[0,144.0,"sw"],"ㅅ":[96.0,144.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[48.0,157.0],"4 cm"],[[142.0,126.0],"4 cm"],[[170.0,48.0],"4 cm"]]}],"tag":false}},{"stem":"가로 12 cm, 세로 8 cm, 높이 6 cm인 직육면체 모양 상자에 한 모서리가 2 cm인 정육면체 블록을 빈틈없이 채우려고 해요. 블록은 모두 몇 개 들어가나요? 숫자로 쓰세요.","answer":["72"],"explanation":["가로에 12 ÷ 2 = 6개, 세로에 8 ÷ 2 = 4개, 높이에 6 ÷ 2 = 3개가 놓여요.","6 × 4 × 3 = 72예요.","그래서 72개예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":128.7,"pts":{"ㄱ":[47.5,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,47.5,"w"],"ㄷ":[142.5,47.5,"sw"],"ㅁ":[47.5,71.2,"ne"],"ㅇ":[190.0,71.2,"e"],"ㅂ":[0,118.7,"sw"],"ㅅ":[142.5,118.7,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[71.2,131.7],"12 cm"],[[188.2,101.0],"8 cm"],[[216.0,35.6],"6 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_review_b#24','math',6,1,'u6','','g6_1_math_u6_review_b','unit_review','M6-1-u6-C2',4,'essay','teacher','도윤이는 가로 4 cm, 세로 3 cm, 높이 6 cm인 직육면체의 겉넓이를 4 × 3 + 4 × 6 + 3 × 6 = 54(cm²)라고 했어요. 잘못된 점을 찾고 바르게 구해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-1-u6-C2","difficulty":4,"kind":"essay","stem":"도윤이는 가로 4 cm, 세로 3 cm, 높이 6 cm인 직육면체의 겉넓이를 4 × 3 + 4 × 6 + 3 × 6 = 54(cm²)라고 했어요. 잘못된 점을 찾고 바르게 구해 보세요.","answer_guide":{"answer":"예: 겨냥도에 보이는 세 면만 더했다. 겉넓이는 여섯 면 전부의 넓이이고 마주 보는 면이 합동이므로 세 면의 합을 2배 해야 한다. 54 × 2 = 108이므로 겉넓이는 108 cm²이다.","scoring_points":["세 면만 더한 것이 잘못이라고 찾았는가","마주 보는 면이 합동이라 2배 해야 한다고 썼는가","108 cm²를 구했는가"]},"explanation":["세 면의 합은 54예요.","54 × 2 = 108이에요.","겉넓이는 108 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_review_b#25','math',6,1,'u6','','g6_1_math_u6_review_b','unit_review','M6-1-u6-C5',4,'essay','teacher','가로 4 cm, 세로 3 cm, 높이 2 cm인 직육면체의 부피를 1 cm³ 쌓기나무로 생각하여 구하고, 부피를 가로 × 세로 × 높이로 구할 수 있는 까닭을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-1-u6-C5","difficulty":4,"kind":"essay","stem":"가로 4 cm, 세로 3 cm, 높이 2 cm인 직육면체의 부피를 1 cm³ 쌓기나무로 생각하여 구하고, 부피를 가로 × 세로 × 높이로 구할 수 있는 까닭을 써 보세요.","answer_guide":{"answer":"예: 한 층에 가로 4개씩 세로 3줄이라 4 × 3 = 12개, 2층이라 12 × 2 = 24개이므로 24 cm³이다. 가로·세로·높이에 놓이는 1 cm³ 쌓기나무의 개수가 각 모서리의 길이와 같아서, 세 길이를 곱하면 전체 쌓기나무 개수, 곧 부피가 된다.","scoring_points":["24 cm³를 구했는가","한 층의 개수 × 층수로 설명했는가","쌓기나무 개수가 모서리 길이와 같다고 썼는가"]},"explanation":["한 층 12개, 2층이에요.","4 × 3 × 2 = 24예요.","그래서 24 cm³예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_review_c#1','math',6,1,'u6','','g6_1_math_u6_review_c','unit_review','M6-1-u6-C1',1,'mc','auto','선물 상자를 포장지로 겹치지 않게 감쌀 때 필요한 종이의 양과 관계있는 것은 어느 것인가요?',ARRAY['M6-1-u6-X01','M6-1-u6-X18']::text[],true,'{"seq":1,"concept":"M6-1-u6-C1","difficulty":1,"kind":"mc","stem":"선물 상자를 포장지로 겹치지 않게 감쌀 때 필요한 종이의 양과 관계있는 것은 어느 것인가요?","options":[{"t":"겉넓이","correct":true},{"t":"부피","mis":"M6-1-u6-X01"},{"t":"모서리의 수","mis":"M6-1-u6-X18"},{"t":"꼭짓점의 수","mis":"M6-1-u6-X18"}],"explanation":["감싸고 붙이고 칠하는 일은 겉면의 넓이, 곧 겉넓이와 관계있어요.","담고 채우고 넣는 일은 공간의 크기, 곧 부피와 관계있어요.","그래서 「겉넓이」예요."],"variant_rule":{"alt":[{"stem":"창고에 상자를 얼마나 쌓아 넣을 수 있는지 알려면 무엇을 알아야 하나요?","options":[{"t":"창고의 부피","correct":true},{"t":"창고 벽의 넓이","mis":"M6-1-u6-X01"},{"t":"창고 바닥의 둘레","mis":"M6-1-u6-X18"},{"t":"창고 문의 개수","mis":"M6-1-u6-X18"}],"explanation":["감싸고 붙이고 칠하는 일은 겉면의 넓이, 곧 겉넓이와 관계있어요.","담고 채우고 넣는 일은 공간의 크기, 곧 부피와 관계있어요.","그래서 「창고의 부피」예요."]},{"stem":"다음 중 부피를 알아야 하는 상황은 어느 것인가요?","options":[{"t":"상자 안에 모래를 얼마나 담을지 알 때","correct":true},{"t":"상자에 포장지를 붙일 때","mis":"M6-1-u6-X01"},{"t":"상자의 겉면을 색칠할 때","mis":"M6-1-u6-X01"},{"t":"상자를 감쌀 종이를 살 때","mis":"M6-1-u6-X01"}],"explanation":["감싸고 붙이고 칠하는 일은 겉면의 넓이, 곧 겉넓이와 관계있어요.","담고 채우고 넣는 일은 공간의 크기, 곧 부피와 관계있어요.","그래서 「상자 안에 모래를 얼마나 담을지 알 때」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_review_c#2','math',6,1,'u6','','g6_1_math_u6_review_c','unit_review','M6-1-u6-C6',1,'mc','auto','한 모서리가 1 m인 정육면체의 부피를 무엇이라고 하나요?',ARRAY['M6-1-u6-X02','M6-1-u6-X13']::text[],true,'{"seq":2,"concept":"M6-1-u6-C6","difficulty":1,"kind":"mc","stem":"한 모서리가 1 m인 정육면체의 부피를 무엇이라고 하나요?","options":[{"t":"1 m³","correct":true},{"t":"1 m²","mis":"M6-1-u6-X02"},{"t":"1 cm³","mis":"M6-1-u6-X13"},{"t":"100 cm³","mis":"M6-1-u6-X13"}],"explanation":["한 모서리가 1 m인 정육면체의 부피를 1 m³라 쓰고 「1 세제곱미터」라고 읽어요.","1 m = 100 cm이므로 100 × 100 × 100 = 1000000이에요.","정답은 「1 m³」예요."],"variant_rule":{"alt":[{"stem":"「1 m³」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"1 세제곱미터","correct":true},{"t":"1 제곱미터","mis":"M6-1-u6-X02"},{"t":"1 세제곱센티미터","mis":"M6-1-u6-X13"},{"t":"1 미터","mis":"M6-1-u6-X02"}],"explanation":["한 모서리가 1 m인 정육면체의 부피를 1 m³라 쓰고 「1 세제곱미터」라고 읽어요.","1 m = 100 cm이므로 100 × 100 × 100 = 1000000이에요.","정답은 「1 세제곱미터」예요."]},{"stem":"한 모서리가 1 cm인 정육면체의 부피를 무엇이라고 하나요?","options":[{"t":"1 cm³","correct":true},{"t":"1 cm²","mis":"M6-1-u6-X02"},{"t":"1 cm","mis":"M6-1-u6-X02"},{"t":"3 cm","mis":"M6-1-u6-X02"}],"explanation":["부피의 표준 단위로 한 모서리가 1 cm인 정육면체를 써요.","그 부피를 1 cm³라 쓰고 「1 세제곱센티미터」라고 읽어요.","정답은 「1 cm³」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_review_c#3','math',6,1,'u6','','g6_1_math_u6_review_c','unit_review','M6-1-u6-C5',1,'mc','auto','정육면체의 부피를 구하는 바른 식은 어느 것인가요?',ARRAY['M6-1-u6-X12','M6-1-u6-X11']::text[],true,'{"seq":3,"concept":"M6-1-u6-C5","difficulty":1,"kind":"mc","stem":"정육면체의 부피를 구하는 바른 식은 어느 것인가요?","options":[{"t":"(한 모서리) × (한 모서리) × (한 모서리)","correct":true},{"t":"(한 모서리) × 3","mis":"M6-1-u6-X12"},{"t":"(한 모서리) × (한 모서리) × 6","mis":"M6-1-u6-X12"},{"t":"(한 모서리) × (한 모서리)","mis":"M6-1-u6-X11"}],"explanation":["가로·세로·높이에 놓이는 1 cm³ 쌓기나무의 개수는 각 모서리의 길이와 같아요.","세 개수를 곱하면 전체 개수, 곧 부피예요.","정답은 「(한 모서리) × (한 모서리) × (한 모서리)」예요."],"variant_rule":{"alt":[{"stem":"정육면체의 겉넓이를 바르게 구한 식은 어느 것인가요? (한 모서리 5 cm)","options":[{"t":"5 × 5 × 6","correct":true},{"t":"5 × 5 × 4","mis":"M6-1-u6-X06"},{"t":"5 × 6","mis":"M6-1-u6-X06"},{"t":"5 × 5 × 2","mis":"M6-1-u6-X04"}],"explanation":["정육면체는 여섯 면이 모두 합동인 정사각형이에요.","그래서 한 면의 넓이만 구해 6배 하면 겉넓이예요.","정답은 「5 × 5 × 6」이에요."]},{"stem":"정육면체의 겉넓이를 구하는 바른 방법은 어느 것인가요?","options":[{"t":"한 면의 넓이 × 6","correct":true},{"t":"한 면의 넓이 × 4","mis":"M6-1-u6-X06"},{"t":"한 모서리 × 6","mis":"M6-1-u6-X06"},{"t":"한 면의 넓이 × 2","mis":"M6-1-u6-X04"}],"explanation":["정육면체는 여섯 면이 모두 합동인 정사각형이에요.","그래서 한 면의 넓이만 구해 6배 하면 겉넓이예요.","정답은 「한 면의 넓이 × 6」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_review_c#4','math',6,1,'u6','','g6_1_math_u6_review_c','unit_review','M6-1-u6-C5',1,'ox','auto','직육면체의 부피는 가로, 세로, 높이를 모두 더해서 구해요.',ARRAY['M6-1-u6-X11']::text[],true,'{"seq":4,"concept":"M6-1-u6-C5","difficulty":1,"kind":"ox","stem":"직육면체의 부피는 가로, 세로, 높이를 모두 더해서 구해요.","answer":"X","reason_options":[{"t":"부피는 세 길이를 곱해서 구하기 때문에","correct":true},{"t":"세 길이를 더하면 쌓기나무 개수가 되기 때문에","mis":"M6-1-u6-X11"}],"mis":"M6-1-u6-X11","explanation":["부피 = 가로 × 세로 × 높이 = 한 밑면의 넓이 × 높이예요.","정육면체는 한 모서리를 세 번 곱해요.","부피와 겉넓이는 서로 다른 양이에요."],"variant_rule":{"alt":[{"stem":"두부를 자르면 조각들의 부피의 합은 처음과 같아요.","answer":"O","reason_options":[{"t":"조각을 도로 붙이면 처음 두부가 되기 때문에","correct":true},{"t":"잘라 낸 만큼 부피가 늘어나기 때문에","mis":"M6-1-u6-X15"}],"explanation":["잘라도 조각을 모두 모으면 처음과 같아 부피는 변하지 않아요.","한 번 자를 때마다 새 면이 2개씩 생겨 겉넓이는 늘어나요.","부피와 겉넓이는 서로 다른 양이에요."]},{"stem":"겉넓이는 상자를 감싸는 종이의 양이고, 부피는 상자 안에 담기는 공간의 크기예요.","answer":"O","reason_options":[{"t":"겉면의 넓이와 공간의 크기는 서로 다른 양이기 때문에","correct":true},{"t":"둘 다 상자의 크기라서 같은 양이기 때문에","mis":"M6-1-u6-X01"}],"explanation":["직육면체는 직사각형 6개로 둘러싸여 있고 마주 보는 면은 합동이에요.","겉넓이는 감싸는 양, 부피는 담기는 양이에요.","두 양은 서로 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_review_c#5','math',6,1,'u6','','g6_1_math_u6_review_c','unit_review','M6-1-u6-C4',1,'sa','auto','부피가 1 cm³인 쌓기나무 12개로 쌓은 도형의 부피는 몇 cm³인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u6-C4","difficulty":1,"kind":"sa","stem":"부피가 1 cm³인 쌓기나무 12개로 쌓은 도형의 부피는 몇 cm³인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["1 cm³인 쌓기나무 한 개의 부피가 1 cm³예요.","12개이면 1 × 12 = 12예요.","그래서 12 cm³예요."],"mis":"M6-1-u6-X10","variant_rule":{"alt":[{"stem":"부피가 1 cm³인 쌓기나무 16개로 쌓은 도형의 부피는 몇 cm³인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["1 cm³인 쌓기나무 한 개의 부피가 1 cm³예요.","16개이면 1 × 16 = 16이에요.","그래서 16 cm³예요."]},{"stem":"부피가 1 cm³인 쌓기나무 5개로 쌓은 도형의 부피는 몇 cm³인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["1 cm³인 쌓기나무 한 개의 부피가 1 cm³예요.","5개이면 1 × 5 = 5예요.","그래서 5 cm³예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_review_c#6','math',6,1,'u6','','g6_1_math_u6_review_c','unit_review','M6-1-u6-C6',1,'mc','auto','6 m³는 몇 cm³인가요?',ARRAY['M6-1-u6-X13']::text[],true,'{"seq":6,"concept":"M6-1-u6-C6","difficulty":1,"kind":"mc","stem":"6 m³는 몇 cm³인가요?","options":[{"t":"6000000 cm³","correct":true},{"t":"600 cm³","mis":"M6-1-u6-X13"},{"t":"60000 cm³","mis":"M6-1-u6-X13"},{"t":"6000 cm³","mis":"M6-1-u6-X13"}],"explanation":["1 m = 100 cm이므로 1 m³는 한 모서리 100 cm인 정육면체예요.","100 × 100 × 100 = 1000000이므로 1 m³ = 1000000 cm³예요.","1000000 × 6 = 6000000이므로 6000000 cm³예요."],"variant_rule":{"alt":[{"stem":"9 m³는 몇 cm³인가요?","options":[{"t":"9000000 cm³","correct":true},{"t":"900 cm³","mis":"M6-1-u6-X13"},{"t":"90000 cm³","mis":"M6-1-u6-X13"},{"t":"9000 cm³","mis":"M6-1-u6-X13"}],"explanation":["1 m = 100 cm이므로 1 m³는 한 모서리 100 cm인 정육면체예요.","100 × 100 × 100 = 1000000이므로 1 m³ = 1000000 cm³예요.","1000000 × 9 = 9000000이므로 9000000 cm³예요."]},{"stem":"1 m³는 몇 cm³인가요?","options":[{"t":"1000000 cm³","correct":true},{"t":"100 cm³","mis":"M6-1-u6-X13"},{"t":"10000 cm³","mis":"M6-1-u6-X13"},{"t":"1000 cm³","mis":"M6-1-u6-X13"}],"explanation":["1 m = 100 cm이므로 1 m³는 한 모서리 100 cm인 정육면체예요.","100 × 100 × 100 = 1000000이므로 1 m³ = 1000000 cm³예요.","그래서 1 m³는 1000000 cm³예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_review_c#7','math',6,1,'u6','','g6_1_math_u6_review_c','unit_review','M6-1-u6-C7',1,'mc','auto','두부를 2조각, 4조각으로 자를 때 조각들의 부피의 합을 바르게 비교한 것은 어느 것인가요?',ARRAY['M6-1-u6-X15','M6-1-u6-X18']::text[],true,'{"seq":7,"concept":"M6-1-u6-C7","difficulty":1,"kind":"mc","stem":"두부를 2조각, 4조각으로 자를 때 조각들의 부피의 합을 바르게 비교한 것은 어느 것인가요?","options":[{"t":"자르기 전과 2조각·4조각 모두 같아요","correct":true},{"t":"자를수록 커져요","mis":"M6-1-u6-X15"},{"t":"자를수록 작아져요","mis":"M6-1-u6-X15"},{"t":"알 수 없어요","mis":"M6-1-u6-X18"}],"explanation":["자른 조각을 도로 붙이면 처음 두부가 되므로 부피의 합은 그대로예요.","한 번 자를 때마다 자른 자리에 마주 보는 새 면 2개가 드러나요.","그래서 겉넓이는 자른 면만큼 늘어나요."],"variant_rule":{"alt":[{"stem":"두부를 한 번 자르면 겉면이 새로 몇 개 생기나요?","options":[{"t":"2개","correct":true},{"t":"1개","mis":"M6-1-u6-X16"},{"t":"4개","mis":"M6-1-u6-X16"},{"t":"생기지 않아요","mis":"M6-1-u6-X16"}],"explanation":["자른 조각을 도로 붙이면 처음 두부가 되므로 부피의 합은 그대로예요.","한 번 자를 때마다 자른 자리에 마주 보는 새 면 2개가 드러나요.","그래서 겉넓이는 자른 면만큼 늘어나요."]},{"stem":"직육면체 모양 두부를 똑같이 2조각으로 자르면 두 조각의 부피의 합은 어떻게 되나요?","options":[{"t":"자르기 전과 같아요","correct":true},{"t":"절반으로 줄어요","mis":"M6-1-u6-X15"},{"t":"두 배가 돼요","mis":"M6-1-u6-X15"},{"t":"자른 면만큼 늘어나요","mis":"M6-1-u6-X16"}],"explanation":["자른 조각을 도로 붙이면 처음 두부가 되므로 부피의 합은 그대로예요.","한 번 자를 때마다 자른 자리에 마주 보는 새 면 2개가 드러나요.","그래서 겉넓이는 자른 면만큼 늘어나요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_review_c#8','math',6,1,'u6','','g6_1_math_u6_review_c','unit_review','M6-1-u6-C1',1,'sa','auto','가로 12 cm, 세로 5 cm인 직사각형의 넓이는 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u6-C1","difficulty":1,"kind":"sa","stem":"가로 12 cm, 세로 5 cm인 직사각형의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["직사각형의 넓이는 가로 × 세로예요.","12 × 5 = 60이에요.","그래서 60 cm²예요."],"mis":"M6-1-u6-X18","variant_rule":{"alt":[{"stem":"가로 7 cm, 세로 7 cm인 직사각형의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["49"],"explanation":["직사각형의 넓이는 가로 × 세로예요.","7 × 7 = 49예요.","그래서 49 cm²예요."]},{"stem":"가로 8 cm, 세로 5 cm인 직사각형의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["직사각형의 넓이는 가로 × 세로예요.","8 × 5 = 40이에요.","그래서 40 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_review_c#9','math',6,1,'u6','','g6_1_math_u6_review_c','unit_review','M6-1-u6-C2',2,'sa','auto','가로 4 cm, 세로 3 cm, 높이 6 cm인 직육면체의 겉넓이는 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u6-C2","difficulty":2,"kind":"sa","stem":"가로 4 cm, 세로 3 cm, 높이 6 cm인 직육면체의 겉넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["108"],"explanation":["서로 다른 세 면의 넓이는 4 × 3 + 4 × 6 + 3 × 6 = 54예요.","마주 보는 면이 합동이라 54 × 2 = 108(cm²)예요.","그래서 겉넓이는 108 cm²예요."],"mis":"M6-1-u6-X03","asset":{"type":"geo","items":[{"w":168.0,"h":190.0,"pts":{"ㄱ":[36.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,36.0,"w"],"ㄷ":[96.0,36.0,"sw"],"ㅁ":[36.0,144.0,"ne"],"ㅇ":[132.0,144.0,"e"],"ㅂ":[0,180.0,"sw"],"ㅅ":[96.0,180.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[48.0,193.0],"4 cm"],[[136.0,168.0],"3 cm"],[[158.0,72.0],"6 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 10 cm, 세로 7 cm, 높이 4 cm인 직육면체의 겉넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["276"],"explanation":["서로 다른 세 면의 넓이는 10 × 7 + 10 × 4 + 7 × 4 = 138이에요.","마주 보는 면이 합동이라 138 × 2 = 276(cm²)예요.","그래서 겉넓이는 276 cm²예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":115.6,"pts":{"ㄱ":[49.3,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,49.3,"w"],"ㄷ":[140.7,49.3,"sw"],"ㅁ":[49.3,56.3,"ne"],"ㅇ":[190.0,56.3,"e"],"ㅂ":[0,105.6,"sw"],"ㅅ":[140.7,105.6,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[70.3,118.6],"10 cm"],[[187.3,86.9],"7 cm"],[[216.0,28.1],"4 cm"]]}],"tag":false}},{"stem":"가로 9 cm, 세로 5 cm, 높이 4 cm인 직육면체의 겉넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["202"],"explanation":["서로 다른 세 면의 넓이는 9 × 5 + 9 × 4 + 5 × 4 = 101이에요.","마주 보는 면이 합동이라 101 × 2 = 202(cm²)예요.","