INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_review_c#17','math',6,1,'u6','','g6_1_math_u6_review_c','unit_review','M6-1-u6-C2',3,'error','auto','가로 6 cm, 세로 4 cm, 높이 5 cm인 직육면체의 겉넓이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u6-X03','M6-1-u6-X18','M6-1-u6-X04']::text[],true,'{"seq":17,"concept":"M6-1-u6-C2","difficulty":3,"kind":"error","stem":"가로 6 cm, 세로 4 cm, 높이 5 cm인 직육면체의 겉넓이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「겨냥도에 보이는 세 면의 넓이를 더한 74 cm²가 겉넓이야.」","correct":true,"mis_target":"M6-1-u6-X03"},{"t":"유진 — 「서로 다른 세 면의 넓이의 합은 74 cm²야.」","mis":"M6-1-u6-X18"},{"t":"라온 — 「겉넓이는 148 cm²야.」","mis":"M6-1-u6-X04"}],"explanation":["겨냥도에서는 세 면만 보이지만 겉넓이는 여섯 면 전부의 넓이예요.","74 × 2 = 148이므로 겉넓이는 148 cm²예요.","가온은 보이는 세 면만 더해 절반만 셌어요."],"asset":{"type":"geo","items":[{"w":226.0,"h":176.3,"pts":{"ㄱ":[47.5,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,47.5,"w"],"ㄷ":[142.5,47.5,"sw"],"ㅁ":[47.5,118.8,"ne"],"ㅇ":[190.0,118.8,"e"],"ㅂ":[0,166.3,"sw"],"ㅅ":[142.5,166.3,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[71.2,179.3],"6 cm"],[[188.2,148.6],"4 cm"],[[216.0,59.4],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 5 cm, 세로 4 cm, 높이 2 cm인 직육면체의 겉넓이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「겨냥도에 보이는 세 면의 넓이를 더한 38 cm²가 겉넓이야.」","correct":true,"mis_target":"M6-1-u6-X03"},{"t":"시우 — 「서로 다른 세 면의 넓이의 합은 38 cm²야.」","mis":"M6-1-u6-X18"},{"t":"은우 — 「겉넓이는 76 cm²야.」","mis":"M6-1-u6-X04"}],"explanation":["겨냥도에서는 세 면만 보이지만 겉넓이는 여섯 면 전부의 넓이예요.","38 × 2 = 76이므로 겉넓이는 76 cm²예요.","여울은 보이는 세 면만 더해 절반만 셌어요."],"asset":{"type":"geo","items":[{"w":204.0,"h":106.0,"pts":{"ㄱ":[48.0,0,"nw"],"ㄹ":[168.0,0,"ne"],"ㄴ":[0,48.0,"w"],"ㄷ":[120.0,48.0,"sw"],"ㅁ":[48.0,48.0,"ne"],"ㅇ":[168.0,48.0,"e"],"ㅂ":[0,96.0,"sw"],"ㅅ