INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_review_c#21','math',6,1,'u6','','g6_1_math_u6_review_c','unit_review','M6-1-u6-C7',3,'sa','auto','가로 8 cm, 세로 6 cm, 높이 5 cm인 두부(겉넓이 236 cm²)를 가로가 똑같이 나뉘도록 2조각으로 잘랐어요. 조각들의 겉넓이를 모두 더하면 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":21,"concept":"M6-1-u6-C7","difficulty":3,"kind":"sa","stem":"가로 8 cm, 세로 6 cm, 높이 5 cm인 두부(겉넓이 236 cm²)를 가로가 똑같이 나뉘도록 2조각으로 잘랐어요. 조각들의 겉넓이를 모두 더하면 몇 cm²인가요? 숫자로 쓰세요.","answer":["296"],"explanation":["2조각이 되려면 1번 잘라야 하고, 한 번 자를 때마다 6 × 5 = 30(cm²)인 새 면이 2개씩 생겨요.","새 면은 1 × 2 = 2개이고, 236 + 30 × 2 = 296이에요.","그래서 296 cm²예요."],"mis":"M6-1-u6-X16","asset":{"type":"geo","items":[{"w":226.0,"h":148.2,"pts":{"ㄱ":[51.8,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,51.8,"w"],"ㄷ":[138.2,51.8,"sw"],"ㅁ":[51.8,86.4,"ne"],"ㅇ":[190.0,86.4,"e"],"ㅂ":[0,138.2,"sw"],"ㅅ":[138.2,138.2,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[69.1,151.2],"8 cm"],[[186.1,118.3],"6 cm"],[[216.0,43.2],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 12 cm, 세로 10 cm, 높이 4 cm인 두부(겉넓이 416 cm²)를 가로가 똑같이 나뉘도록 3조각으로 잘랐어요. 조각들의 겉넓이를 모두 더하면 몇 cm²인가요? 숫자로 쓰세요.","answer":["576"],"explanation":["3조각이 되려면 2번 잘라야 하고, 한 번 자를 때마다 10 × 4 = 40(cm²)인 새 면이 2개씩 생겨요.","새 면은 2 × 2 = 4개이고, 416 + 40 × 4 = 576이에요.","그래서 576 cm²예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":110.6,"pts":{"ㄱ":[55.9,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,55.9,"w"],"ㄷ":[134.1,55.9,"sw"],"ㅁ":[55.9,44.7,"ne"],"ㅇ":[190.0,44.7,"e"],"ㅂ":[0,100.6,"sw"],"ㅅ":[134.1,100.6,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[67.0,113.6],"12 cm"],[[184.0,78.7],"10 cm"],[[216.0,22.4],"4 cm"]]}],"tag":false}},{"stem":"가로 10 cm, 세로 10 cm, 높이 5 cm인 두부(겉넓이 400 cm²)를 가로가 똑같이 나뉘도록 2조각으로 잘랐어요. 조각들의 겉넓이를 모두 더하면 몇 cm²인가요? 숫자로 쓰세요.","answer":["500"],"explanation":["2조각이 되려면 1번 잘라야 하고, 한 번 자를 때마다 10 × 5 = 50(cm²)인 새 면이 2개씩 생겨요.","새 면은 1 × 2 = 2개이고, 400 + 50 × 2 = 500이에요.","그래서 500 cm²예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":136.6,"pts":{"ㄱ":[63.3,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,63.3,"w"],"ㄷ":[126.7,63.3,"sw"],"ㅁ":[63.3,63.3,"ne"],"ㅇ":[190.0,63.3,"e"],"ㅂ":[0,126.6,"sw"],"ㅅ":[126.7,126.6,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[63.4,139.6],"10 cm"],[[180.3,100.9],"10 cm"],[[216.0,31.6],"5 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
