INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_review_d#14','math',6,1,'u6','','g6_1_math_u6_review_d','unit_review','M6-1-u6-C3',2,'sa','auto','가로 6 cm, 세로 2 cm, 높이 5 cm인 직육면체의 전개도예요. 옆면 네 개를 이어 붙인 큰 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M6-1-u6-C3","difficulty":2,"kind":"sa","stem":"가로 6 cm, 세로 2 cm, 높이 5 cm인 직육면체의 전개도예요. 옆면 네 개를 이어 붙인 큰 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["옆면을 펼치면 한 장의 직사각형이 되고, 그 가로는 한 밑면의 둘레와 같아요.","6 + 2 + 6 + 2 = 16이에요.","그래서 16 cm예요."],"mis":"M6-1-u6-X05","asset":{"type":"geo","items":[{"w":336.0,"h":162.0,"pts":{},"show":[],"poly":[[[36,0],[137.2,0],[137.2,33.8],[36,33.8]],[[36,118.2],[137.2,118.2],[137.2,152.0],[36,152.0]],[[36,33.8],[137.2,33.8],[137.2,118.2],[36,118.2]],[[137.2,33.8],[171.0,33.8],[171.0,118.2],[137.2,118.2]],[[171.0,33.8],[272.2,33.8],[272.2,118.2],[171.0,118.2]],[[272.2,33.8],[306.0,33.8],[306.0,118.2],[272.2,118.2]]],"lab":[[[86.6,-10],"6 cm"],[[14,16.9],"2 cm"],[[330.0,76.0],"5 cm"],[[221.6,132.2],"옆면의 가로 ?"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 4 cm, 세로 2 cm, 높이 3 cm인 직육면체의 전개도예요. 옆면 네 개를 이어 붙인 큰 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["옆면을 펼치면 한 장의 직사각형이 되고, 그 가로는 한 밑면의 둘레와 같아요.","4 + 2 + 4 + 2 = 12예요.","그래서 12 cm예요."],"asset":{"type":"geo","items":[{"w":282.0,"h":136.0,"pts":{},"show":[],"poly":[[[36,0],[108.0,0],[108.0,36.0],[36,36.0]],[[36,90.0],[108.0,90.0],[108.0,126.0],[36,126.0]],[[36,36.0],[108.0,36.0],[108.0,90.0],[36,90.0]],[[108.0,36.0],[144.0,36.0],[144.0,90.0],[108.0,90.0]],[[144.0,36.0],[216.0,36.0],[216.0,90.0],[144.0,90.0]],[[216.0,36.0],[252.0,36.0],[252.0,90.0],[216.0,90.0]]],"lab":[[[72.0,-10],"4 cm"],[[14,18.0],"2 cm"],[[276.0,63.0],"3 cm"],[[180.0,104.0],"옆면의 가로 ?"]]}],"tag":false}},{"stem":"가로 5 cm, 세로 3 cm, 높이 4 cm인 직육면체의 전개도예요. 옆면 네 개를 이어 붙인 큰 직사각형