INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_review_d#15','math',6,1,'u6','','g6_1_math_u6_review_d','unit_review','M6-1-u6-C6',2,'mc','auto','다음 중 부피를 m³로 나타내기에 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u6-X14']::text[],true,'{"seq":15,"concept":"M6-1-u6-C6","difficulty":2,"kind":"mc","stem":"다음 중 부피를 m³로 나타내기에 알맞은 것은 어느 것인가요?","options":[{"t":"트럭 짐칸","correct":true},{"t":"보석 상자","mis":"M6-1-u6-X14"},{"t":"우유갑","mis":"M6-1-u6-X14"},{"t":"필통","mis":"M6-1-u6-X14"}],"explanation":["작은 물건의 부피는 cm³로 나타내요.","방·교실·트럭 짐칸·컨테이너처럼 큰 것은 m³로 나타내는 것이 편해요.","정답은 「트럭 짐칸」이에요."],"variant_rule":{"alt":[{"stem":"넓이 1 m²와 부피 1 m³를 cm 단위로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"1 m² = 10000 cm², 1 m³ = 1000000 cm³","correct":true},{"t":"1 m² = 10000 cm², 1 m³ = 10000 cm³","mis":"M6-1-u6-X13"},{"t":"1 m² = 100 cm², 1 m³ = 1000 cm³","mis":"M6-1-u6-X13"},{"t":"1 m² = 1000000 cm², 1 m³ = 10000 cm³","mis":"M6-1-u6-X02"}],"explanation":["넓이는 두 방향을 곱해 1 m² = 100 × 100 = 10000(cm²)예요.","부피는 세 방향을 곱해 1 m³ = 100 × 100 × 100 = 1000000(cm³)예요.","정답은 「1 m² = 10000 cm², 1 m³ = 1000000 cm³」예요."]},{"stem":"100 × 100 × 100으로 구하는 것은 어느 것인가요?","options":[{"t":"1 m³가 몇 cm³인지","correct":true},{"t":"1 m²가 몇 cm²인지","mis":"M6-1-u6-X02"},{"t":"1 m가 몇 cm인지","mis":"M6-1-u6-X13"},{"t":"1 cm³가 몇 m³인지","mis":"M6-1-u6-X14"}],"explanation":["넓이는 두 방향을 곱해 1 m² = 100 × 100 = 10000(cm²)예요.","부피는 세 방향을 곱해 1 m³ = 100 × 100 × 100 = 1000000(cm³)예요.","정답은 「1 m³가 몇 cm³인지」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_review_d#16','math',6,1,'u6','','g6_1_math_u6_review_d','unit_review','M6-1-u6-C4',2,'sa','auto','부피가 1 cm³인 쌓기나무로 빈틈없이 쌓은 직육면체예요. 부피는 몇 cm³인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M6-1-u6-C4","difficulty":2,"kind":"sa","stem":"부피가 1 cm³인 쌓기나무로 빈틈없이 쌓은 직육면체예요. 부피는 몇 cm³인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["한 층에는 4 × 3 = 12개가 있어요.","2층이므로 12 × 2 = 24개예요.","그래서 부피는 24 cm³예요."],"mis":"M6-1-u6-X10","asset":{"type":"geo","items":[{"w":132.0,"h":84.0,"pts":{"ㄱ":[36.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,36.0,"w"],"ㄷ":[96.0,36.0,"sw"],"ㅁ":[36.0,48.0,"ne"],"ㅇ":[132.0,48.0,"e"],"ㅂ":[0,84.0,"sw"],"ㅅ":[96.0,84.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"],[[24.0,36.0],[24.0,84.0]],[[24.0,36.0],[60.0,0]],[[48.0,36.0],[48.0,84.0]],[[48.0,36.0],[84.0,0]],[[72.0,36.0],[72.0,84.0]],[[72.0,36.0],[108.0,0]],[[0,60.0],[96.0,60.0]],[[96.0,60.0],[132.0,24.0]],[[12.0,24.0],[108.0,24.0]],[[108.0,24.0],[108.0,72.0]],[[24.0,12.0],[120.0,12.0]],[[120.0,12.0],[120.0,60.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 부피가 1 cm³인 쌓기나무로 빈틈없이 쌓은 직육면체예요. 부피는 몇 cm³인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["한 층에는 3 × 2 = 6개가 있어요.","2층이므로 6 × 2 = 12개예요.","그래서 부피는 12 cm³예요."],"asset":{"type":"geo","items":[{"w":96.0,"h":72.0,"pts":{"ㄱ":[24.0,0,"nw"],"ㄹ":[96.0,0,"ne"],"ㄴ":[0,24.0,"w"],"ㄷ":[72.0,24.0,"sw"],"ㅁ":[24.0,48.0,"ne"],"ㅇ":[96.0,48.0,"e"],"ㅂ":[0,72.0,"sw"],"ㅅ":[72.0,72.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"],[[24.0,24.0],[24.0,72.0]],[[24.0,24.0],[48.0,0]],[[48.0,24.0],[48.0,72.0]],[[48.0,24.0],[72.0,0]],[[0,48.0],[72.0,48.0]],[[72.0,48.0],[96.0,24.0]],[[12.0,12.0],[84.0,12.0]],[[84.0,12.0],[84.0,60.0]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 부피가 1 cm³인 쌓기나무로 빈틈없이 쌓은 직육면체예요. 부피는 몇 cm³인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["한 층에는 4 × 2 = 8개가 있어요.","2층이므로 8 × 2 = 16개예요.","그래서 부피는 16 cm³예요."],"asset":{"type":"geo","items":[{"w":120.0,"h":72.0,"pts":{"ㄱ":[24.0,0,"nw"],"ㄹ":[120.0,0,"ne"],"ㄴ":[0,24.0,"w"],"ㄷ":[96.0,24.0,"sw"],"ㅁ":[24.0,48.0,"ne"],"ㅇ":[120.0,48.0,"e"],"ㅂ":[0,72.0,"sw"],"ㅅ":[96.0,72.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"],[[24.0,24.0],[24.0,72.0]],[[24.0,24.0],[48.0,0]],[[48.0,24.0],[48.0,72.0]],[[48.0,24.0],[72.0,0]],[[72.0,24.0],[72.0,72.0]],[[72.0,24.0],[96.0,0]],[[0,48.0],[96.0,48.0]],[[96.0,48.0],[120.0,24.0]],[[12.0,12.0],[108.0,12.0]],[[108.0,12.0],[108.0,60.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_review_d#17','math',6,1,'u6','','g6_1_math_u6_review_d','unit_review','M6-1-u6-C2',3,'error','auto','가로 5 cm, 세로 4 cm, 높이 2 cm인 직육면체의 겉넓이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u6-X03','M6-1-u6-X18','M6-1-u6-X04']::text[],true,'{"seq":17,"concept":"M6-1-u6-C2","difficulty":3,"kind":"error","stem":"가로 5 cm, 세로 4 cm, 높이 2 cm인 직육면체의 겉넓이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「겨냥도에 보이는 세 면의 넓이를 더한 38 cm²가 겉넓이야.」","correct":true,"mis_target":"M6-1-u6-X03"},{"t":"시우 — 「서로 다른 세 면의 넓이의 합은 38 cm²야.」","mis":"M6-1-u6-X18"},{"t":"은우 — 「겉넓이는 76 cm²야.」","mis":"M6-1-u6-X04"}],"explanation":["겨냥도에서는 세 면만 보이지만 겉넓이는 여섯 면 전부의 넓이예요.","38 × 2 = 76이므로 겉넓이는 76 cm²예요.","여울은 보이는 세 면만 더해 절반만 셌어요."],"asset":{"type":"geo","items":[{"w":204.0,"h":106.0,"pts":{"ㄱ":[48.0,0,"nw"],"ㄹ":[168.0,0,"ne"],"ㄴ":[0,48.0,"w"],"ㄷ":[120.0,48.0,"sw"],"ㅁ":[48.0,48.0,"ne"],"ㅇ":[168.0,48.0,"e"],"ㅂ":[0,96.0,"sw"],"ㅅ":[120.0,96.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[60.0,109.0],"5 cm"],[[166.0,78.0],"4 cm"],[[194.0,24.0],"2 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 4 cm, 세로 3 cm, 높이 6 cm인 직육면체의 겉넓이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「겨냥도에 보이는 세 면의 넓이를 더한 54 cm²가 겉넓이야.」","correct":true,"mis_target":"M6-1-u6-X03"},{"t":"도윤 — 「서로 다른 세 면의 넓이의 합은 54 cm²야.」","mis":"M6-1-u6-X18"},{"t":"서아 — 「겉넓이는 108 cm²야.」","mis":"M6-1-u6-X04"}],"explanation":["겨냥도에서는 세 면만 보이지만 겉넓이는 여섯 면 전부의 넓이예요.","54 × 2 = 108이므로 겉넓이는 108 cm²예요.","하린은 보이는 세 면만 더해 절반만 셌어요."],"asset":{"type":"geo","items":[{"w":168.0,"h":190.0,"pts":{"ㄱ":[36.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,36.0,"w"],"ㄷ":[96.0,36.0,"sw"],"ㅁ":[36.0,144.0,"ne"],"ㅇ":[132.0,144.0,"e"],"ㅂ":[0,180.0,"sw"],"ㅅ":[