INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_review_d#21','math',6,1,'u6','','g6_1_math_u6_review_d','unit_review','M6-1-u6-C7',3,'sa','auto','가로 12 cm, 세로 10 cm, 높이 4 cm인 두부(겉넓이 416 cm²)를 가로가 똑같이 나뉘도록 3조각으로 잘랐어요. 조각들의 겉넓이를 모두 더하면 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":21,"concept":"M6-1-u6-C7","difficulty":3,"kind":"sa","stem":"가로 12 cm, 세로 10 cm, 높이 4 cm인 두부(겉넓이 416 cm²)를 가로가 똑같이 나뉘도록 3조각으로 잘랐어요. 조각들의 겉넓이를 모두 더하면 몇 cm²인가요? 숫자로 쓰세요.","answer":["576"],"explanation":["3조각이 되려면 2번 잘라야 하고, 한 번 자를 때마다 10 × 4 = 40(cm²)인 새 면이 2개씩 생겨요.","새 면은 2 × 2 = 4개이고, 416 + 40 × 4 = 576이에요.","그래서 576 cm²예요."],"mis":"M6-1-u6-X16","asset":{"type":"geo","items":[{"w":226.0,"h":110.6,"pts":{"ㄱ":[55.9,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,55.9,"w"],"ㄷ":[134.1,55.9,"sw"],"ㅁ":[55.9,44.7,"ne"],"ㅇ":[190.0,44.7,"e"],"ㅂ":[0,100.6,"sw"],"ㅅ":[134.1,100.6,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[67.0,113.6],"12 cm"],[[184.0,78.7],"10 cm"],[[216.0,22.4],"4 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 10 cm, 세로 10 cm, 높이 5 cm인 두부(겉넓이 400 cm²)를 가로가 똑같이 나뉘도록 2조각으로 잘랐어요. 조각들의 겉넓이를 모두 더하면 몇 cm²인가요? 숫자로 쓰세요.","answer":["500"],"explanation":["2조각이 되려면 1번 잘라야 하고, 한 번 자를 때마다 10 × 5 = 50(cm²)인 새 면이 2개씩 생겨요.","새 면은 1 × 2 = 2개이고, 400 + 50 × 2 = 500이에요.","그래서 500 cm²예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":136.6,"pts":{"ㄱ":[63.3,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,63.3,"w"],"ㄷ":[126.7,63.3,"sw"],"ㅁ":[63.3,63.3,"ne"],"ㅇ":[190.0,63.3,"e"],"ㅂ":[0,126.6,"sw"],"ㅅ":[126.7,126.6,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[63.4,139.6],"10 cm"],[[180.3,100.9],"10 cm"],[[216.0,31.6],"5 cm"]]}],"tag":false}},{"stem":"가로 10 cm, 세로 10 cm, 높이 5 cm인 두부(겉넓이 400 cm²)를 가로가 똑같이 나뉘도록 4조각으로 잘랐어요. 조각들의 겉넓이를 모두 더하면 몇 cm²인가요? 숫자로 쓰세요.","answer":["700"],"explanation":["4조각이 되려면 3번 잘라야 하고, 한 번 자를 때마다 10 × 5 = 50(cm²)인 새 면이 2개씩 생겨요.","새 면은 3 × 2 = 6개이고, 400 + 50 × 6 = 700이에요.","그래서 700 cm²예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":136.6,"pts":{"ㄱ":[63.3,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,63.3,"w"],"ㄷ":[126.7,63.3,"sw"],"ㅁ":[63.3,63.3,"ne"],"ㅇ":[190.0,63.3,"e"],"ㅂ":[0,126.6,"sw"],"ㅅ":[126.7,126.6,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[63.4,139.6],"10 cm"],[[180.3,100.9],"10 cm"],[[216.0,31.6],"5 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_review_d#22','math',6,1,'u6','','g6_1_math_u6_review_d','unit_review','M6-1-u6-C5',3,'mc','auto','직육면체 가는 가로 3 cm, 세로 3 cm, 높이 12 cm, 나는 가로 6 cm, 세로 6 cm, 높이 3 cm예요. 옳은 것은 어느 것인가요?',ARRAY['M6-1-u6-X17','M6-1-u6-X18']::text[],true,'{"seq":22,"concept":"M6-1-u6-C5","difficulty":3,"kind":"mc","stem":"직육면체 가는 가로 3 cm, 세로 3 cm, 높이 12 cm, 나는 가로 6 cm, 세로 6 cm, 높이 3 cm예요. 옳은 것은 어느 것인가요?","options":[{"t":"부피는 같지만 겉넓이는 달라요","correct":true},{"t":"부피가 같으니 겉넓이도 같아요","mis":"M6-1-u6-X17"},{"t":"겉넓이가 다르니 부피도 달라요","mis":"M6-1-u6-X17"},{"t":"부피도 겉넓이도 달라요","mis":"M6-1-u6-X18"}],"explanation":["가의 부피는 3 × 3 × 12 = 108, 나의 부피는 6 × 6 × 3 = 108(cm³)예요.","가의 겉넓이는 162, 나의 겉넓이는 144(cm²)예요.","부피가 같아도 겉넓이는 다를 수 있어요."],"asset":{"type":"geo","items":[{"w":92.3,"h":178.8,"pts":{"ㄱ":[18.8,0,"nw"],"ㄹ":[56.3,0,"ne"],"ㄴ":[0,18.8,"w"],"ㄷ":[37.5,18.8,"sw"],"ㅁ":[18.8,150.0,"ne"],"ㅇ":[56.3,150.0,"e"],"ㅂ":[0,168.8,"sw"],"ㅅ":[37.5,168.8,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[18.8,181.8],"3 cm"],[[68.9,165.4],"3 cm"],[[82.3,75.0],"12 cm"]],"cap":"가"},{"w":226.0,"h":136.6,"pts":{"ㄱ":[63.3,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,63.3,"w"],"ㄷ":[126.7,63.3,"sw"],"ㅁ":[63.3,63.3,"ne"],"ㅇ":[190.0,63.3,"e"],"ㅂ":[0,126.6,"sw"],"ㅅ":[126.7,126.6,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[63.4,139.6],"6 cm"],[[180.3,100.9],"6 cm"],[[216.0,31.6],"3 cm"]],"cap":"나"}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체 가는 가로 4 cm, 세로 4 cm, 높이 4 cm, 나는 가로 8 cm, 세로 4 cm, 높이 2 cm예요. 옳은 것은 어느 것인가요?","options":[{"t":"부피는 같지만 겉넓이는 달라요","correct":true},{"t":"부피가 같으니 겉넓이도 같아요","mis":"M6-1-u6-X17"},{"t":"겉넓이가 다르니 부피도 달라요","mis":"M6-1-u6-X17"},{"t":"부피도 겉넓이도 달라요","mis":"M6-1-u6-X18"}],"explanation":["가의 부피는 4 × 4 × 4 = 64, 나의 부피는 8 × 4 × 2 = 64(cm³)예요.","가의 겉넓이는 96, 나의 겉넓이는 112(cm²)예요.","부피가 같아도 겉넓이는 다를 수 있어요."],"asset":{"type":"geo","items":[{"w":180.0,"h":154.0,"pts":{"ㄱ":[48.0,0,"nw"],"ㄹ":[144.0,0,"ne"],"ㄴ":[0,48.0,"w"],"ㄷ":[96.0,48.0,"sw"],"ㅁ":[48.0,96.0,"ne"],"ㅇ":[144.0,96.0,"e"],"ㅂ":[0,144.0,"sw"],"ㅅ":[96.0,144.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[48.0,157.0],"4 cm"],[[142.0,126.0],"4 cm"],[[170.0,48.0],"4 cm"]],"cap":"가"},{"w":226.0,"h":86.0,"pts":{"ㄱ":[38.0,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,38.0,"w"],"ㄷ":[152.0,38.0,"sw"],"ㅁ":[38.0,38.0,"ne"],"ㅇ":[190.0,38.0,"e"],"ㅂ":[0,76.0,"sw"],"ㅅ":[152.0,76.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[76.0,89.0],"8 cm"],[[193.0,63.0],"4 cm"],[[216.0,19.0],"2 cm"]],"cap":"나"}],"tag":false}},{"stem":"직육면체 가는 가로 6 cm, 세로 6 cm, 높이 6 cm, 나는 가로 12 cm, 세로 6 cm, 높이 3 cm예요. 옳은 것은 어느 것인가요?","options":[{"t":"부피는 같지만 겉넓이는 달라요","correct":true},{"t":"부피가 같으니 겉넓이도 같아요","mis":"M6-1-u6-X17"},{"t":"겉넓이가 다르니 부피도 달라요","mis":"M6-1-u6-X17"},{"t":"부피도 겉넓이도 달라요","mis":"M6-1-u6-X18"}],"explanation":["가의 부피는 6 × 6 × 6 = 216, 나의 부피는 12 × 6 × 3 = 216(cm³)예요.","가의 겉넓이는 216, 나의 겉넓이는 252(cm²)예요.","부피가 같아도 겉넓이는 다를 수 있어요."],"asset":{"type":"geo","items":[{"w":226.0,"h":200.0,"pts":{"ㄱ":[63.3,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,63.3,"w"],"ㄷ":[126.7,63.3,"sw"],"ㅁ":[63.3,126.7,"ne"],"ㅇ":[190.0,126.7,"e"],"ㅂ":[0,190.0,"sw"],"ㅅ":[126.7,190.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[63.4,203.0],"6 cm"],[[180.3,164.3],"6 cm"],[[216.0,63.4],"6 cm"]],"cap":"가"},{"w":226.0,"h":86.0,"pts":{"ㄱ":[38.0,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,38.0,"w"],"ㄷ":[152.0,38.0,"sw"],"ㅁ":[38.0,38.0,"ne"],"ㅇ":[190.0,38.0,"e"],"ㅂ":[0,76.0,"sw"],"ㅅ":[152.0,76.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[76.0,89.0],"12 cm"],[[193.0,63.0],"6 cm"],[[216.0,19.0],"3 cm"]],"cap":"나"}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_review_d#23','math',6,1,'u6','','g6_1_math_u6_review_d','unit_review','M6-1-u6-C5',4,'sa','auto','가로 12 cm, 세로 8 cm, 높이 6 cm인 직육면체 모양 상자에 한 모서리가 2 cm인 정육면체 블록을 빈틈없이 채우려고 해요. 블록은 모두 몇 개 들어가나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M6-1-u6-C5","difficulty":4,"kind":"sa","stem":"가로 12 cm, 세로 8 cm, 높이 6 cm인 직육면체 모양 상자에 한 모서리가 2 cm인 정육면체 블록을 빈틈없이 채우려고 해요. 블록은 모두 몇 개 들어가나요? 숫자로 쓰세요.","answer":["72"],"explanation":["가로에 12 ÷ 2 = 6개, 세로에 8 ÷ 2 = 4개, 높이에 6 ÷ 2 = 3개가 놓여요.","6 × 4 × 3 = 72예요.","그래서 72개예요."],"mis":"M6-1-u6-X10","asset":{"type":"geo","items":[{"w":226.0,"h":128.7,"pts":{"ㄱ":[47.5,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,47.5,"w"],"ㄷ":[142.5,47.5,"sw"],"ㅁ":[47.5,71.2,"ne"],"ㅇ":[190.0,71.2,"e"],"ㅂ":[0,118.7,"sw"],"ㅅ":[142.5,118.7,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[71.2,131.7],"12 cm"],[[188.2,101.0],"8 cm"],[[216.0,35.6],"6 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 2 m, 세로 150 cm, 높이 100 cm인 직육면체 모양 창고의 부피는 몇 m³인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["단위를 m로 맞춰요: 150 cm = 1.5 m, 100 cm = 1 m예요.","2 × 1.5 × 1 = 3이에요.","그래서 3 m³예요."]},{"stem":"겉넓이가 294 cm²인 정육면체가 있어요. 한 모서리는 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["한 면의 넓이는 294 ÷ 6 = 49예요.","같은 수를 두 번 곱해 49가 되는 수는 7 × 7 = 49이므로 7이에요.","그래서 한 모서리는 7 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_review_d#24','math',6,1,'u6','','g6_1_math_u6_review_d','unit_review','M6-1-u6-C7',4,'essay','teacher','가로 10 cm, 세로 10 cm, 높이 5 cm인 두부를 가로가 똑같이 나뉘도록 2조각으로 잘랐어요. 자르기 전과 비교하여 부피와 겉넓이가 각각 어떻게 되는지 셈과 함께 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-1-u6-C7","difficulty":4,"kind":"essay","stem":"가로 10 cm, 세로 10 cm, 높이 5 cm인 두부를 가로가 똑같이 나뉘도록 2조각으로 잘랐어요. 자르기 전과 비교하여 부피와 겉넓이가 각각 어떻게 되는지 셈과 함께 써 보세요.","answer_guide":{"answer":"예: 부피는 10 × 10 × 5 = 500(cm³)이고 두 조각을 더해도 250 + 250 = 500이므로 그대로다. 겉넓이는 처음 400 cm²에서 자른 면(10 × 5 = 50)이 2개 새로 생겨 400 + 50 × 2 = 500(cm²)으로 늘어난다.","scoring_points":["부피 500 cm³가 그대로라고 했는가","자른 면 50 cm²가 2개 생긴다고 했는가","겉넓이가 500 cm²로 늘어난다고 했는가"]},"explanation":["부피는 500 cm³ 그대로예요.","새 면 50 cm²가 2개 생겨요.","겉넓이는 400 + 100 = 500(cm²)이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_review_d#25','math',6,1,'u6','','g6_1_math_u6_review_d','unit_review','M6-1-u6-C1',4,'essay','teacher','여울이는 「겉면이 넓은 상자가 언제나 더 많이 담긴다.」고 말했어요. 이 말이 맞는지 판단하고, 겉넓이와 부피가 어떤 양인지 넣어 까닭을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-1-u6-C1","difficulty":4,"kind":"essay","stem":"여울이는 「겉면이 넓은 상자가 언제나 더 많이 담긴다.」고 말했어요. 이 말이 맞는지 판단하고, 겉넓이와 부피가 어떤 양인지 넣어 까닭을 써 보세요.","answer_guide":{"answer":"예: 맞지 않다. 겉넓이는 상자를 감싸는 종이의 양(겉면의 넓이)이고 부피는 상자 안에 담기는 공간의 크기라서 서로 다른 양이다. 그래서 겉면이 넓어도 담기는 양은 더 적을 수 있다.","scoring_points":["맞지 않다고 판단했는가","겉넓이 = 겉면의 넓이(감싸는 양)라고 썼는가","부피 = 담기는 공간의 크기라고 쓰고 두 양이 다르다고 설명했는가"]},"explanation":["겉넓이는 감싸는 양, 부피는 담기는 양이에요.","두 양은 서로 달라요.","그래서 겉면이 넓다고 언제나 더 많이 담기지는 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
